INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe1451a6-7b5d-41a5-98e7-e49699332293', '南陵留別段氏兄弟', '南陵留別段氏兄弟', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["不知身老大，猶似舊時狂。","爲酒遊山縣，留詩遍草堂。","歸期秋未盡，離恨日偏長。","更羨君兄弟，參差鴈一行。"]', '["不知身老大，猶似旧时狂。","爲酒游山縣，留诗遍草堂。","归期秋未尽，離恨日偏长。","更羨君兄弟，參差鴈一行。"]', '诗', 'shi', '', NULL, '南陵留別段氏兄弟 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24f44c0d-8200-4142-9478-31d01f861603', '旅中別姪暐', '旅中別姪暐', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["相見又南北，中宵淚滿襟。","旅遊知世薄，貧別覺情深。","歌管一尊酒，山川萬里心。","此身多在路，休誦異鄉吟。"]', '["相见又南北，中宵泪满襟。","旅游知世薄，貧別覺情深。","歌管一尊酒，山川万里心。","此身多在路，休誦異乡吟。"]', '诗', 'shi', '', NULL, '旅中別姪暐 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e200fdcc-28e7-4987-b9d2-0ae0e3d810fa', '松江渡送人', '松江渡送人', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["故國今何在，扁舟竟不歸。","雲移山漠漠，江闊樹依依。","晚色千帆落，秋聲一鴈飛。","此時兼送客，憑檻欲霑衣。"]', '["故国今何在，扁舟竟不归。","云移山漠漠，江闊樹依依。","晚色千帆落，秋声一鴈飞。","此时兼送客，憑檻欲霑衣。"]', '诗', 'shi', '', NULL, '松江渡送人 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11039f7d-7cf1-47c5-8701-e5c3c84f307a', '過鮑溶宅有感', '過鲍溶宅有感', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["寥落故人宅，重來身已亡。","古苔殘墨沼，深竹舊書堂。","秋色館池靜，雨聲雲木涼。","無因展交道，日暮倍心傷。"]', '["寥落故人宅，重来身已亡。","古苔殘墨沼，深竹旧书堂。","秋色館池静，雨声云木涼。","無因展交道，日暮倍心傷。"]', '诗', 'shi', '', NULL, '過鮑溶宅有感 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26d0076f-779c-46ca-bea9-a5caeb529729', '金陵懷古', '金陵懷古', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["玉樹歌殘王氣終，景陽兵合戍樓空。","松楸遠近千官塚，禾黍高低六代宮。","石燕拂雲晴亦雨，江豚吹浪夜還風。","英雄一去豪華盡，唯有青山似洛中。"]', '["玉樹歌殘王氣終，景陽兵合戍楼空。","松楸远近千官塚，禾黍高低六代宮。","石燕拂云晴亦雨，江豚吹浪夜還风。","英雄一去豪华尽，唯有青山似洛中。"]', '诗', 'shi', '', NULL, '金陵懷古 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ed571de-5397-40a0-a262-febbf957e1a4', '姑蘇懷古', '姑蘇懷古', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["宮館餘基輟棹過，黍苗無限獨悲歌。","荒臺麋鹿爭新草，空苑鳧鷖占淺莎。","吳岫雨來虛檻冷，楚江風急遠帆多。","可憐國破忠臣死，日日東流生白波。"]', '["宮館餘基輟棹過，黍苗無限独悲歌。","荒台麋鹿爭新草，空苑鳧鷖占淺莎。","吳岫雨来虛檻冷，楚江风急远帆多。","可怜国破忠臣死，日日东流生白波。"]', '诗', 'shi', '', NULL, '姑蘇懷古 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('116c803d-b32f-45fd-ad7d-3cb453dcfbdd', '凌歊臺', '凌歊台', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["宋祖凌高樂未回，三千歌舞宿層臺。","湘潭雲盡暮山出，巴蜀雪消春水來。","行殿有基荒薺合，寢園無主野棠開。","百年便作萬年計，嵒畔古碑空綠苔。"]', '["宋祖凌高乐未回，三千歌舞宿層台。","湘潭云尽暮山出，巴蜀雪消春水来。","行殿有基荒薺合，寢园無主野棠开。","百年便作万年計，嵒畔古碑空綠苔。"]', '诗', 'shi', '', NULL, '凌歊臺 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbb27494-21bd-446d-b1b4-ff9567d63c03', '驪山', '驪山', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["聞說先皇醉碧桃，日華浮動鬱金袍。","風隨玉輦笙歌逈，雲捲珠簾劒佩高。","鳳駕北歸山寂寂，龍旟西幸水滔滔。","貴妃沒後巡遊少，瓦落宮墻見野蒿。"]', '["闻说先皇醉碧桃，日华浮动鬱金袍。","风隨玉輦笙歌逈，云捲珠簾劒佩高。","鳳駕北归山寂寂，龙旟西幸水滔滔。","貴妃沒後巡游少，瓦落宮墻见野蒿。"]', '诗', 'shi', '', NULL, '驪山 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae5ca477-e66f-423f-bed6-944ed737f66b', '咸陽城東樓', '咸陽城东楼', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["一上高城萬里愁，蒹葭楊柳似汀洲。","溪雲初起日沈閣，山雨欲來風滿樓。","鳥下綠蕪秦苑夕，蟬鳴黃葉漢宮秋。","行人莫問當年事，故國東來渭水流。"]', '["一上高城万里愁，蒹葭楊柳似汀洲。","溪云初起日沈閣，山雨欲来风满楼。","鸟下綠蕪秦苑夕，蟬鳴黄葉漢宮秋。","行人莫问當年事，故国东来渭水流。"]', '诗', 'shi', '', NULL, '咸陽城東樓 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62a679ba-aae0-49ef-9f88-417c5ec8529c', '京口閑居寄京洛友人', '京口闲居寄京洛友人', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["吳門煙月昔同遊，楓葉蘆花並客舟。","聚散有期雲北去，浮沈無計水東流。","一尊酒盡青山暮，千里書回碧樹秋。","何處相思不相見，鳳城龍闕楚江頭。"]', '["吳门煙月昔同游，楓葉蘆花並客舟。","聚散有期云北去，浮沈無計水东流。","一尊酒尽青山暮，千里书回碧樹秋。","何处相思不相见，鳳城龙闕楚江头。"]', '诗', 'shi', '', NULL, '京口閑居寄京洛友人 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('584e5331-0d9c-4af4-94a6-c5250764f2b4', '冬日登越王臺懷歸', '冬日登越王台懷归', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["月沈高岫宿雲開，萬里歸心獨上來。","河畔雪飛揚子宅，海邊花盛越王臺。","瀧分桂嶺魚難過，瘴近衡峯鴈却回。","鄉信漸稀人漸老，只應頻看一枝梅。"]', '["月沈高岫宿云开，万里归心独上来。","河畔雪飞揚子宅，海邊花盛越王台。","瀧分桂嶺鱼难過，瘴近衡峯鴈却回。","乡信漸稀人漸老，只應頻看一枝梅。"]', '诗', 'shi', '', NULL, '冬日登越王臺懷歸 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16e667ab-12e3-49a0-88d3-ea8c3122ff19', '對雪', '对雪', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["雲度龍山暗倚城，先飛淅瀝引輕盈。","素娥冉冉拜瑤闕，皓鶴紛紛朝玉京。","陰嶺有風梅豔散，寒林無月桂華生。","剡溪一醉十年事，忽憶棹回天未明。"]', '["云度龙山暗倚城，先飞淅瀝引轻盈。","素娥冉冉拜瑤闕，皓鹤紛紛朝玉京。","陰嶺有风梅豔散，寒林無月桂华生。","剡溪一醉十年事，忽憶棹回天未明。"]', '诗', 'shi', '', NULL, '對雪 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1c4fd2b-87b4-438a-8803-bbf5ade86b4f', '送蕭處士歸緱嶺別業', '送蕭处士归緱嶺別業', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["醉斜烏帽髪如絲，曾看仙人一局棋。","賓館有魚爲客久，鄉書無鴈到家遲。","緱山住近吹笙廟，湘水行逢鼓瑟祠。","今夜月明何處宿，九疑雲盡碧參差。"]', '["醉斜烏帽髪如絲，曾看仙人一局棋。","賓館有鱼爲客久，乡书無鴈到家遲。","緱山住近吹笙廟，湘水行逢鼓瑟祠。","今夜月明何处宿，九疑云尽碧參差。"]', '诗', 'shi', '', NULL, '送蕭處士歸緱嶺別業 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51d5dd08-f139-4c99-a2c6-6a3d8191894a', '與鄭二秀才同舟東下洛中親朋送至景雲寺', '與鄭二秀才同舟东下洛中親朋送至景云寺', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["三十六峰橫一川，綠波無路草芊芊。","牛羊晚食鋪平地，鵰鶚晴飛摩遠天。","洛客盡回臨水寺，楚人皆逐下江船。","東西未有相逢日，更把繁華共醉眠。"]', '["三十六峰橫一川，綠波無路草芊芊。","牛羊晚食鋪平地，鵰鶚晴飞摩远天。","洛客尽回臨水寺，楚人皆逐下江船。","东西未有相逢日，更把繁华共醉眠。"]', '诗', 'shi', '', NULL, '與鄭二秀才同舟東下洛中親朋送至景雲寺 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ed0e43e-41ac-46bd-8723-329282f5036d', '長安歲暮', '长安歲暮', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["獨望天門倚劒歌，干時無計老關河。","東歸萬里慙張翰，西上四年羞卞和。","花暗楚城春醉少，月涼秦塞夜愁多。","三山歲歲有人去，唯恐海風生白波。"]', '["独望天门倚劒歌，干时無計老关河。","东归万里慙張翰，西上四年羞卞和。","花暗楚城春醉少，月涼秦塞夜愁多。","三山歲歲有人去，唯恐海风生白波。"]', '诗', 'shi', '', NULL, '長安歲暮 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('500c34e5-1431-4022-b031-9f4355d6bdba', '贈茅山高拾遺', '贈茅山高拾遺', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["諫獵歸來綺季歌，大茅峯影滿秋波。","山齋留客掃紅葉，野艇送僧披綠莎。","長覆舊圖棊勢盡，遍添新品藥名多。","雲中黃鵠日千里，自宿自飛無網羅。"]', '["諫獵归来綺季歌，大茅峯影满秋波。","山斋留客掃紅葉，野艇送僧披綠莎。","长覆旧圖棊勢尽，遍添新品藥名多。","云中黄鵠日千里，自宿自飞無網羅。"]', '诗', 'shi', '', NULL, '贈茅山高拾遺 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('979c2ce0-f38c-4374-b446-413a4969495b', '李秀才近自塗口遷居新安適枉緘書見寛悲戚因以此答', '李秀才近自塗口遷居新安適枉緘书见寛悲戚因以此答', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["遠書開罷更依依，晨坐高臺竟落暉。","顏巷雪深人已去，庾樓花盛客初歸。","東堂望絕遷鶯起，南國哀餘候鴈飛。","今日勞君猶問訊，一官唯長故山薇。"]', '["远书开罷更依依，晨坐高台竟落暉。","顏巷雪深人已去，庾楼花盛客初归。","东堂望絕遷鶯起，南国哀餘候鴈飞。","今日勞君猶问訊，一官唯长故山薇。"]', '诗', 'shi', '', NULL, '李秀才近自塗口遷居新安適枉緘書見寛悲戚因以此答 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c336e75d-4716-4826-aae6-ceefdec37f34', '贈蕭兵曹先輩', '贈蕭兵曹先輩', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["廣陵堤上昔離居，帆轉瀟湘萬里餘。","楚客病時無鵩鳥，越鄉歸處有鱸魚。","潮生水郭蒹葭響，雨過山城橘柚疎。","聞說攜琴兼載酒，邑人爭識馬相如。"]', '["廣陵堤上昔離居，帆轉瀟湘万里餘。","楚客病时無鵩鸟，越乡归处有鱸鱼。","潮生水郭蒹葭响，雨過山城橘柚疎。","闻说携琴兼載酒，邑人爭識马相如。"]', '诗', 'shi', '', NULL, '贈蕭兵曹先輩 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f605356f-b9ac-428c-bed0-02829db16142', '題舒女廟', '題舒女廟', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["山樂來迎去不言，廟前高柳水禽喧。","綺羅無色雨侵帳，珠翠有聲風繞幡。","妝鏡尚疑山月滿，寢屏猶認野花繁。","孤舟夢斷行雲散，何限離心寄曉猨。"]', '["山乐来迎去不言，廟前高柳水禽喧。","綺羅無色雨侵帳，珠翠有声风繞幡。","妝镜尚疑山月满，寢屏猶認野花繁。","孤舟梦斷行云散，何限離心寄晓猨。"]', '诗', 'shi', '', NULL, '題舒女廟 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cff78c1-915a-4ca4-8f08-33e7ccd21378', '姑孰官舍', '姑孰官舍', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["草生官舍似閑居，雪照南窗滿素書。","貧後始知爲吏拙，病來還喜識人疎。","青雲豈有窺梁燕，濁水應無避釣魚。","不待秋風便歸去，紫陽山下是吾廬。"]', '["草生官舍似闲居，雪照南窗满素书。","貧後始知爲吏拙，病来還喜識人疎。","青云豈有窺梁燕，濁水應無避釣鱼。","不待秋风便归去，紫陽山下是吾廬。"]', '诗', 'shi', '', NULL, '姑孰官舍 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9891018f-1c27-4e20-8503-1998a6273022', '凌歊臺送韋秀才', '凌歊台送韋秀才', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["雲起高臺日未沈，數村殘照半巖陰。","野蠶成繭桑柘盡，溪鳥引雛蒲稗深。","帆勢依依投極浦，鐘聲[杳杳]隔前林。","故山迢遰故人去，一夜月明千里心。"]', '["云起高台日未沈，數村殘照半巖陰。","野蠶成繭桑柘尽，溪鸟引雛蒲稗深。","帆勢依依投極浦，鐘声[杳杳]隔前林。","故山迢遰故人去，一夜月明千里心。"]', '诗', 'shi', '', NULL, '凌歊臺送韋秀才 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e0ad576-af17-4be9-a874-7b41216cde36', '送嶺南盧判官罷職歸華陰山居', '送嶺南盧判官罷職归华陰山居', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["曾事劉琨鴈塞空，十年書劒任飄蓬。","東堂舊屈移山志，南國新留煮海功。","還挂一帆青海上，更開三逕碧蓮中。","關西舊友如相問，已許滄浪伴釣翁。"]', '["曾事劉琨鴈塞空，十年书劒任飄蓬。","东堂旧屈移山志，南国新留煮海功。","還挂一帆青海上，更开三逕碧蓮中。","关西旧友如相问，已許滄浪伴釣翁。"]', '诗', 'shi', '', NULL, '送嶺南盧判官罷職歸華陰山居 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('593d815a-910b-4b76-9b8e-5e4df97707ce', '將度故城湖阻風夜泊永陽戍', '將度故城湖阻风夜泊永陽戍', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["行盡青溪日已蹉，雲容山影水嵯峨。","樓前歸客怨清夢，樓上美人凝夜歌。","獨樹高高風勢急，平湖渺渺月明多。","終期一艇載樵去，來往使帆凌白波。"]', '["行尽青溪日已蹉，云容山影水嵯峨。","楼前归客怨清梦，楼上美人凝夜歌。","独樹高高风勢急，平湖渺渺月明多。","終期一艇載樵去，来往使帆凌白波。"]', '诗', 'shi', '', NULL, '將度故城湖阻風夜泊永陽戍 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b35d7a78-6d97-4bbf-af77-c204ff9b7728', '鄭侍御廳翫鶴', '鄭侍御廳翫鹤', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["碧天飛舞下晴莎，金閣瑤池絕網羅。","嵒響數聲風滿樹，岸移孤影雪凌波。","緱山去遠雲霄迥，遼海歸遲歲月多。","雙翅一開千萬里，秖應棲隱戀喬柯。"]', '["碧天飞舞下晴莎，金閣瑤池絕網羅。","嵒响數声风满樹，岸移孤影雪凌波。","緱山去远云霄迥，遼海归遲歲月多。","雙翅一开千万里，秖應棲隐戀喬柯。"]', '诗', 'shi', '', NULL, '鄭侍御廳翫鶴 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94710607-3d19-4640-b897-4a37c5f9c8d7', '南亭夜坐貽開元禪定二道者', '南亭夜坐貽开元禪定二道者', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["暮暮焚香何處宿，西巖一室映疎藤。","光陰難駐跡如客，寒暑不驚心似僧。","高樹有風聞夜磬，遠山無月見秋燈。","身閑境靜日爲樂，若問其餘非我能。"]', '["暮暮焚香何处宿，西巖一室映疎藤。","光陰难駐跡如客，寒暑不驚心似僧。","高樹有风闻夜磬，远山無月见秋灯。","身闲境静日爲乐，若问其餘非我能。"]', '诗', 'shi', '', NULL, '南亭夜坐貽開元禪定二道者 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5577901c-fd3f-4c29-b633-dbc3617bf237', '朱坡故少保杜公池亭', '朱坡故少保杜公池亭', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["杜陵池榭綺城東，孤島回汀路不窮。","高岫乍疑三峽近，遠波初似五湖通。","楸梧葉暗瀟瀟雨，菱荇花香淡淡風。","還有昔時巢燕在，飛來飛去畫堂中。"]', '["杜陵池榭綺城东，孤島回汀路不窮。","高岫乍疑三峽近，远波初似五湖通。","楸梧葉暗瀟瀟雨，菱荇花香淡淡风。","還有昔时巢燕在，飞来飞去畫堂中。"]', '诗', 'shi', '', NULL, '朱坡故少保杜公池亭 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2fd4060-decf-49f0-90d8-0f718b902a9b', '秋日早朝', '秋日早朝', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["宵衣應待絕更籌，環佩鏘鏘月下樓。","井轉轆轤千樹曉，鏁開閶闔萬山秋。","龍旗盡列趨金殿，雉扇才分見玉旒。","虛戴鐵冠無一事，滄江歸去老漁舟。"]', '["宵衣應待絕更籌，环佩鏘鏘月下楼。","井轉轆轤千樹晓，鏁开閶闔万山秋。","龙旗尽列趨金殿，雉扇才分见玉旒。","虛戴鐵冠無一事，滄江归去老漁舟。"]', '诗', 'shi', '', NULL, '秋日早朝 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b35bf541-f8f6-4422-b30b-532eedfe4500', '滄浪峽', '滄浪峽', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["纓帶流塵髪半霜，獨尋殘月下滄浪。","一聲溪鳥暗雲散，萬片野花流水香。","昔日未知方外樂，暮年初信夢中忙。","紅蝦青鯽紫芹脆，歸去不辭來路長。"]', '["纓带流塵髪半霜，独尋殘月下滄浪。","一声溪鸟暗云散，万片野花流水香。","昔日未知方外乐，暮年初信梦中忙。","紅蝦青鯽紫芹脆，归去不辞来路长。"]', '诗', 'shi', '', NULL, '滄浪峽 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af3013bf-efd1-4f45-80f3-ad50c980c9f1', '故洛城', '故洛城', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["禾黍離離半野蒿，昔人城此豈知勞。","水聲東去市朝變，山勢北來宮殿高。","鴉噪暮雲歸古堞，鴈迷寒雨下空壕。","可憐緱嶺登仙子，猶自吹笙醉碧桃。"]', '["禾黍離離半野蒿，昔人城此豈知勞。","水声东去市朝变，山勢北来宮殿高。","鴉噪暮云归古堞，鴈迷寒雨下空壕。","可怜緱嶺登仙子，猶自吹笙醉碧桃。"]', '诗', 'shi', '', NULL, '故洛城 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c7bad4c-fd1c-4615-9bd6-df8feed4bfd3', '聞釋子栖玄欲奉道因寄', '闻釋子栖玄欲奉道因寄', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["欲求真訣戀禪扃，羽帔方袍盡有情。","仙骨本微靈鶴遠，法心潛動毒龍驚。","三山未有偷桃計，四海初傳問菊名。","今日勸師師莫惑，長生難學證無生。"]', '["欲求真訣戀禪扃，羽帔方袍尽有情。","仙骨本微靈鹤远，法心潛动毒龙驚。","三山未有偷桃計，四海初傳问菊名。","今日勸師師莫惑，长生难学證無生。"]', '诗', 'shi', '', NULL, '聞釋子栖玄欲奉道因寄 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1a14989-773a-413b-95b0-c3a868beda94', '南海府罷南康阻淺行侶稍登陸而邁主人燕餞至頻暮宿東溪', '南海府罷南康阻淺行侶稍登陸而邁主人燕餞至頻暮宿东溪', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["暗灘水落漲虛沙，灘去秦吳萬里賒。","馬上折殘江北柳，舟中開盡嶺南花。","離歌不斷如留客，歸夢初驚似到家。","山鳥一聲人未起，半牀春月在天涯。"]', '["暗灘水落漲虛沙，灘去秦吳万里賒。","马上折殘江北柳，舟中开尽嶺南花。","離歌不斷如留客，归梦初驚似到家。","山鸟一声人未起，半牀春月在天涯。"]', '诗', 'shi', '', NULL, '南海府罷南康阻淺行侶稍登陸而邁主人燕餞至頻暮宿東溪 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53ed7d72-b353-485e-b746-07574de6a42e', '秋晚雲陽驛西亭蓮池', '秋晚云陽驛西亭蓮池', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["心憶蓮池秉燭遊，葉殘花敗尚維舟。","煙開翠扇清風曉，水泥紅衣白露秋。","神女暫來雲易散，仙娥初去月難留。","空懷遠道難持贈，醉倚闌干盡日愁。"]', '["心憶蓮池秉燭游，葉殘花敗尚維舟。","煙开翠扇清风晓，水泥紅衣白露秋。","神女暫来云易散，仙娥初去月难留。","空懷远道难持贈，醉倚闌干尽日愁。"]', '诗', 'shi', '', NULL, '秋晚雲陽驛西亭蓮池 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f702ef8-9af6-410f-a375-c3ac88e8e3d8', '題勤尊師歷陽山居', '題勤尊師歷陽山居', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["二十知兵在羽林，中年潛識子房心。","蒼鷹出塞胡塵滅，白鶴還鄉楚水深。","春坼酒瓶浮藥氣，晚攜棊局帶松陰。","雞籠山上雲多處，自斸黃精不可尋。"]', '["二十知兵在羽林，中年潛識子房心。","蒼鷹出塞胡塵滅，白鹤還乡楚水深。","春坼酒瓶浮藥氣，晚携棊局带松陰。","雞籠山上云多处，自斸黄精不可尋。"]', '诗', 'shi', '', NULL, '題勤尊師歷陽山居 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5308b242-865a-4ed9-a716-9a6592c45590', '懷舊居', '懷旧居', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["兵書一篋老無功，故國郊扉在夢中。","藤蔓覆梨張谷暗，草花侵菊庾園空。","朱門跡忝登龍客，白屋心期失馬翁。","楚水吳山何處是，北窗殘月照屏風。"]', '["兵书一篋老無功，故国郊扉在梦中。","藤蔓覆梨張谷暗，草花侵菊庾园空。","朱门跡忝登龙客，白屋心期失马翁。","楚水吳山何处是，北窗殘月照屏风。"]', '诗', 'shi', '', NULL, '懷舊居 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36269a84-1558-48df-a0b9-5c998f12590d', '祗命許昌自郊居移就公館秋日寄茅山高拾遺', '祗命許昌自郊居移就公館秋日寄茅山高拾遺', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["一笛迎風萬葉飛，強攜刀筆換荷衣。","潮寒水國秋砧早，月暗山城夜漏稀。","巖響遠聞樵客過，浦深遙送釣童歸。","中年未識從軍樂，虛近三茅望少微。"]', '["一笛迎风万葉飞，強携刀笔換荷衣。","潮寒水国秋砧早，月暗山城夜漏稀。","巖响远闻樵客過，浦深遙送釣童归。","中年未識從軍乐，虛近三茅望少微。"]', '诗', 'shi', '', NULL, '祗命許昌自郊居移就公館秋日寄茅山高拾遺 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be76603e-2575-4ff5-9999-8c1828582755', '傷虞將軍', '傷虞將軍', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["白首從軍未有名，近將孤劒到江城。","巴童戍久能番語，胡馬調多解漢行。","對雪夜窮黃石略，望雲秋計黑山程。","可憐身死家猶遠，汴水東流無哭聲。"]', '["白首從軍未有名，近將孤劒到江城。","巴童戍久能番語，胡马調多解漢行。","对雪夜窮黄石略，望云秋計黑山程。","可怜身死家猶远，汴水东流無哭声。"]', '诗', 'shi', '', NULL, '傷虞將軍 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a1b4524-d02f-407b-92e4-2be633993da7', '晚自朝臺津至韋隱居郊園', '晚自朝台津至韋隐居郊园', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["秋來鳧鴈下方塘，繫馬朝臺步夕陽。","村徑繞山松葉暗，野門臨水稻花香。","雲連海氣琴書潤，風帶潮聲枕簟涼。","西下磻溪猶萬里，可能垂白待文王。"]', '["秋来鳧鴈下方塘，繫马朝台步夕陽。","村徑繞山松葉暗，野门臨水稻花香。","云連海氣琴书潤，风带潮声枕簟涼。","西下磻溪猶万里，可能垂白待文王。"]', '诗', 'shi', '', NULL, '晚自朝臺津至韋隱居郊園 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('319a9b28-fbea-4a75-8929-ad524ff4751f', '寓居開元精舍酬薛秀才見貽', '寓居开元精舍酬薛秀才见貽', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["知己蕭條信陸沈，茂陵扶疾臥西林。","芰荷風起客堂靜，松桂月高僧院深。","清露下時傷旅鬢，白雲歸處寄鄉心。","憐君詩句猶相憶，題在空齋夜夜吟。"]', '["知己蕭條信陸沈，茂陵扶疾臥西林。","芰荷风起客堂静，松桂月高僧院深。","清露下时傷旅鬢，白云归处寄乡心。","怜君诗句猶相憶，題在空斋夜夜吟。"]', '诗', 'shi', '', NULL, '寓居開元精舍酬薛秀才見貽 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34445d84-93cc-43fd-b651-97b205aeddf9', '別劉秀才', '別劉秀才', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["三獻無功玉有瑕，更攜書劒客天涯。","孤帆夜別瀟湘雨，廣陌春期鄠杜花。","燈照水螢千點滅，棹驚灘鴈一行斜。","關河萬里秋風急，望見鄉山不到家。"]', '["三獻無功玉有瑕，更携书劒客天涯。","孤帆夜別瀟湘雨，廣陌春期鄠杜花。","灯照水螢千点滅，棹驚灘鴈一行斜。","关河万里秋风急，望见乡山不到家。"]', '诗', 'shi', '', NULL, '別劉秀才 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed535503-69a1-4623-9738-a55aba7365a3', '早發天台中巖寺度關嶺次天姥岑', '早發天台中巖寺度关嶺次天姥岑', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["來往天台天姥間，欲求真訣駐衰顏。","星河半落巖前寺，雲霧初開嶺上關。","丹壑樹多風浩浩，碧溪苔淺水潺潺。","可知劉阮逢人處，行盡深山又是山。"]', '["来往天台天姥间，欲求真訣駐衰顏。","星河半落巖前寺，云霧初开嶺上关。","丹壑樹多风浩浩，碧溪苔淺水潺潺。","可知劉阮逢人处，行尽深山又是山。"]', '诗', 'shi', '', NULL, '早發天台中巖寺度關嶺次天姥岑 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a5fe5e1-1054-4b9e-a5db-60accc6effbf', '遊錢塘青山李隱居西齋', '游錢塘青山李隐居西斋', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["小隱西亭爲客開，翠蘿深處遍蒼苔。","林間掃石安棊局，巖下分泉遞酒盃。","蘭葉露光秋月上，蘆花風起夜潮來。","雲山遶屋猶嫌淺，欲棹漁舟近釣臺。"]', '["小隐西亭爲客开，翠蘿深处遍蒼苔。","林间掃石安棊局，巖下分泉遞酒盃。","蘭葉露光秋月上，蘆花风起夜潮来。","云山遶屋猶嫌淺，欲棹漁舟近釣台。"]', '诗', 'shi', '', NULL, '遊錢塘青山李隱居西齋 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0e5764c-b083-4019-8e88-a0629aab8431', '春日郊園戲贈楊嘏評事', '春日郊园戲贈楊嘏評事', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["十里蒹葭入薜蘿，春風誰許暫鳴珂。","相如渴後狂還減，曼倩歸來語更多。","門枕碧溪冰皓耀，檻齊青嶂雪嵯峨。","野橋沽酒茅簷醉，誰羨紅樓一曲歌。"]', '["十里蒹葭入薜蘿，春风誰許暫鳴珂。","相如渴後狂還減，曼倩归来語更多。","门枕碧溪冰皓耀，檻齊青嶂雪嵯峨。","野橋沽酒茅簷醉，誰羨紅楼一曲歌。"]', '诗', 'shi', '', NULL, '春日郊園戲贈楊嘏評事 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3a601c5-78a8-4db0-be89-9210d3ff375b', '晚自東郭回留一二遊侶', '晚自东郭回留一二游侶', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["鄉心迢遰宦情微，吏散尋幽竟落暉。","林下草腥巢鷺宿，洞前雲濕雨龍歸。","鐘隨野艇回孤棹，鼓絕山城掩半扉。","今夜西齋好風月，一瓢春酒莫相違。"]', '["乡心迢遰宦情微，吏散尋幽竟落暉。","林下草腥巢鷺宿，洞前云濕雨龙归。","鐘隨野艇回孤棹，鼓絕山城掩半扉。","今夜西斋好风月，一瓢春酒莫相違。"]', '诗', 'shi', '', NULL, '晚自東郭回留一二遊侶 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67a338bc-7a8a-4fd1-845e-46c11606671b', '與鄭秀才叔姪會送楊秀才昆仲東歸', '與鄭秀才叔姪會送楊秀才昆仲东归', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["書劒功遲白髮新，異鄉仍送故鄉人。","阮公留客竹林晚，田氏到家荆樹春。","雪盡塞鴻南翥少，風來胡馬北嘶頻。","洞庭煙月如終老，誰是長楊諫獵臣。"]', '["书劒功遲白髮新，異乡仍送故乡人。","阮公留客竹林晚，田氏到家荆樹春。","雪尽塞鴻南翥少，风来胡马北嘶頻。","洞庭煙月如終老，誰是长楊諫獵臣。"]', '诗', 'shi', '', NULL, '與鄭秀才叔姪會送楊秀才昆仲東歸 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b9cb934-5554-4eb2-a792-56a9062ca2d4', '送郭秀才遊天台', '送郭秀才游天台', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["雲埋陰壑雪凝峯，半壁天台已萬重。","人度碧溪疑輟棹，僧歸蒼嶺似聞鐘。","暖眠鸂鶒晴灘草，高挂獼猴暮澗松。","曾約共遊今獨去，赤城西面水溶溶。"]', '["云埋陰壑雪凝峯，半壁天台已万重。","人度碧溪疑輟棹，僧归蒼嶺似闻鐘。","暖眠鸂鶒晴灘草，高挂獼猴暮澗松。","曾約共游今独去，赤城西面水溶溶。"]', '诗', 'shi', '', NULL, '送郭秀才遊天台 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('005b0e22-126e-408a-a3cd-0b3f6057ae5e', '送張尊師歸洞庭', '送張尊師归洞庭', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["能琴道士洞庭西，風滿歸帆路不迷。","對岸水花霜後淺，傍簷山果雨來低。","杉松近晚移茶竈，巖谷初寒蓋藥畦。","他日相思兩行字，無人知處武陵溪。"]', '["能琴道士洞庭西，风满归帆路不迷。","对岸水花霜後淺，傍簷山果雨来低。","杉松近晚移茶竈，巖谷初寒蓋藥畦。","他日相思兩行字，無人知处武陵溪。"]', '诗', 'shi', '', NULL, '送張尊師歸洞庭 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ea2d0fa-d677-42cf-9877-5c9b09e13ace', '移攝太平寄前李明府', '移攝太平寄前李明府', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["病移嵒邑稱閑身，何處風光貰酒頻。","溪柳遶門彭澤令，野花連洞武陵人。","嬌歌自駐壺中景，豔舞長留海上春。","早晚高臺更同醉，綠蘿如帳草如茵。"]', '["病移嵒邑稱闲身，何处风光貰酒頻。","溪柳遶门彭澤令，野花連洞武陵人。","嬌歌自駐壺中景，豔舞长留海上春。","早晚高台更同醉，綠蘿如帳草如茵。"]', '诗', 'shi', '', NULL, '移攝太平寄前李明府 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df1590b2-d8e8-492a-b7b3-eee0a614e565', '再遊姑蘇玉芝觀', '再游姑蘇玉芝观', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["高梧一葉下秋初，迢遰重廊舊寄居。","月過碧窗今夜酒，雨昏紅壁去年書。","玉池露冷芙蓉淺，瓊樹風高薜荔疎。","明日挂帆更東去，仙翁應笑爲鱸魚。"]', '["高梧一葉下秋初，迢遰重廊旧寄居。","月過碧窗今夜酒，雨昏紅壁去年书。","玉池露冷芙蓉淺，瓊樹风高薜荔疎。","明日挂帆更东去，仙翁應笑爲鱸鱼。"]', '诗', 'shi', '', NULL, '再遊姑蘇玉芝觀 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0b93745-247b-41d1-af1a-678878f8c731', '夜歸驛樓', '夜归驛楼', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["水晚雲秋山不窮，自疑身在畫屏中。","孤舟移棹一江月，高閣捲簾千樹風。","窗下覆棋殘局在，橘邊沽酒半壜空。","早炊香稻待鱸鱠，南渚未明尋釣翁。"]', '["水晚云秋山不窮，自疑身在畫屏中。","孤舟移棹一江月，高閣捲簾千樹风。","窗下覆棋殘局在，橘邊沽酒半壜空。","早炊香稻待鱸鱠，南渚未明尋釣翁。"]', '诗', 'shi', '', NULL, '夜歸驛樓 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e2e07b9-33aa-4331-bd48-9ab9b49745a9', '題靈山寺行堅師院', '題靈山寺行堅師院', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["西巖一逕不通樵，八十持杯未覺遙。","龍在石潭聞夜雨，鴈移沙渚見秋潮。","經函露濕文多暗，香印風吹字半銷。","應笑東歸又南去，越山無路水迢迢。"]', '["西巖一逕不通樵，八十持杯未覺遙。","龙在石潭闻夜雨，鴈移沙渚见秋潮。","經函露濕文多暗，香印风吹字半銷。","應笑东归又南去，越山無路水迢迢。"]', '诗', 'shi', '', NULL, '題靈山寺行堅師院 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01089f7e-faae-4503-9174-b836f6ebdacf', '湖州韋長史山居', '湖州韋长史山居', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["一官唯買晝公堂，但得身閑日自長。","琴曲少聲重勘譜，藥丸多忌更尋方。","溪浮箬葉添醅綠，泉遶松根助茗香。","明日鱖魚何處釣，門前春水似滄浪。"]', '["一官唯買晝公堂，但得身闲日自长。","琴曲少声重勘譜，藥丸多忌更尋方。","溪浮箬葉添醅綠，泉遶松根助茗香。","明日鱖鱼何处釣，门前春水似滄浪。"]', '诗', 'shi', '', NULL, '湖州韋長史山居 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23d0926b-c071-448c-85af-737df08e22d6', '贈李伊闕', '贈李伊闕', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["桐履如飛不可尋，一壺雙笈嶧陽琴。","舟橫野度寒風急，門掩荒山夜雪深。","貧笑白駒無去意，病慙黃鵠有歸心。","雲間二室勞君畫，水墨蒼蒼半壁陰。"]', '["桐履如飞不可尋，一壺雙笈嶧陽琴。","舟橫野度寒风急，门掩荒山夜雪深。","貧笑白駒無去意，病慙黄鵠有归心。","云间二室勞君畫，水墨蒼蒼半壁陰。"]', '诗', 'shi', '', NULL, '贈李伊闕 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bd3176d-6a22-4757-b5f4-bf1ad16aa60a', '重遊綀湖懷舊', '重游綀湖懷旧', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["西風渺渺月連天，同醉蘭舟未十年。","鵩鳥賦成人已沒，嘉魚詩在世空傳。","榮枯盡寄浮雲外，哀樂猶驚逝水前。","日暮長隄更回首，一聲鄰笛舊山川。"]', '["西风渺渺月連天，同醉蘭舟未十年。","鵩鸟賦成人已沒，嘉鱼诗在世空傳。","榮枯尽寄浮云外，哀乐猶驚逝水前。","日暮长隄更回首，一声鄰笛旧山川。"]', '诗', 'shi', '', NULL, '重遊綀湖懷舊 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6ecb19a-f6b6-45f5-9e2a-e3057569f3b8', '乘月棹舟送大曆寺靈聰上人不及', '乘月棹舟送大曆寺靈聰上人不及', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["萬峰秋盡百泉清，舊鎖禪扉在赤城。","楓浦客來煙未散，竹窗僧去月猶明。","杯浮野渡魚龍遠，錫響空山虎豹驚。","一字不留何足訝，白雲無路水無情。"]', '["万峰秋尽百泉清，旧鎖禪扉在赤城。","楓浦客来煙未散，竹窗僧去月猶明。","杯浮野渡鱼龙远，錫响空山虎豹驚。","一字不留何足訝，白云無路水無情。"]', '诗', 'shi', '', NULL, '乘月棹舟送大曆寺靈聰上人不及 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8341c4f7-04b1-4c38-b0aa-2103807662cf', '汴河亭', '汴河亭', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["廣陵花盛帝東游，先劈崑崙一派流。","百二禁兵辭象闕，三千宮女下龍舟。","凝雲鼓震星辰動，拂浪旗開日月浮。","四海義師歸有道，迷樓還似景陽樓。"]', '["廣陵花盛帝东游，先劈崑崙一派流。","百二禁兵辞象闕，三千宮女下龙舟。","凝云鼓震星辰动，拂浪旗开日月浮。","四海義師归有道，迷楼還似景陽楼。"]', '诗', 'shi', '', NULL, '汴河亭 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b272de0-513c-470b-8d8a-2d802b5fd73c', '村舍二首 一', '村舍二首 一', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["自翦青莎織雨衣，南峰煙火是柴扉。","萊妻早報蒸藜熟，童子遙迎種豆歸。","魚下碧潭當鏡躍，鳥還青嶂拂屏飛。","花時未免人來往，欲買嚴光舊釣磯。"]', '["自翦青莎织雨衣，南峰煙火是柴扉。","萊妻早報蒸藜熟，童子遙迎種豆归。","鱼下碧潭當镜躍，鸟還青嶂拂屏飞。","花时未免人来往，欲買嚴光旧釣磯。"]', '诗', 'shi', '', NULL, '村舍二首 一 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ece41fd2-3321-4e1b-a32c-3c61f692c30d', '村舍二首 二', '村舍二首 二', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["尚平多累自歸難，一日身閑一日安。","山逕曉雲收獵網，水門涼月挂魚竿。","花間酒氣春風暖，竹裏棋聲暮雨寒。","三頃水田秋更熟，北窗誰拂舊塵冠。"]', '["尚平多累自归难，一日身闲一日安。","山逕晓云收獵網，水门涼月挂鱼竿。","花间酒氣春风暖，竹裏棋声暮雨寒。","三頃水田秋更熟，北窗誰拂旧塵冠。"]', '诗', 'shi', '', NULL, '村舍二首 二 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce3a66a7-1ce1-4c22-aaeb-437a84f6a730', '鄭秀才東歸憑達家書', '鄭秀才东归憑達家书', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["欲寄家書少客過，閉門心遠洞庭波。","兩巖花落夜風急，一逕草荒春雨多。","愁泛楚江吟浩渺，憶歸吳岫夢嵯峨。","貧居不問應知處，溪上閑船繫綠蘿。"]', '["欲寄家书少客過，閉门心远洞庭波。","兩巖花落夜风急，一逕草荒春雨多。","愁泛楚江吟浩渺，憶归吳岫梦嵯峨。","貧居不问應知处，溪上闲船繫綠蘿。"]', '诗', 'shi', '', NULL, '鄭秀才東歸憑達家書 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5c32cf7-392f-4562-80b4-cdae2ee192d7', '傷故湖州李郎中', '傷故湖州李郎中', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["政成身沒共興衰，鄉路兵戈旅櫬迴。","城上暮雲凝鼓角，海邊春草閉池臺。","經年未葬家人散，昨夜因齋故吏來。","南北相逢皆掩泣，白蘋洲暖百花開。"]', '["政成身沒共兴衰，乡路兵戈旅櫬迴。","城上暮云凝鼓角，海邊春草閉池台。","經年未葬家人散，昨夜因斋故吏来。","南北相逢皆掩泣，白蘋洲暖百花开。"]', '诗', 'shi', '', NULL, '傷故湖州李郎中 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8abd41dd-11fd-4885-b603-80d48230b720', '和友人送僧歸桂州靈巖寺', '和友人送僧归桂州靈巖寺', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["楚客送僧歸桂陽，海門帆勢極瀟湘。","碧雲千里暮愁合，白雪一聲春思長。","柳絮擁堤添衲軟，松花浮水注瓶香。","南京長老幾年別，聞道半巖多影堂。"]', '["楚客送僧归桂陽，海门帆勢極瀟湘。","碧云千里暮愁合，白雪一声春思长。","柳絮擁堤添衲軟，松花浮水注瓶香。","南京长老幾年別，闻道半巖多影堂。"]', '诗', 'shi', '', NULL, '和友人送僧歸桂州靈巖寺 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef407373-3f8b-403d-be5c-cb10e19aff82', '淮陰阻風寄呈楚州韋中丞', '淮陰阻风寄呈楚州韋中丞', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["垂釣京江欲白頭，江魚堪釣却西游。","劉伶臺下稻花晚，韓信廟前楓葉秋。","淮月未明先倚檻，海雲初起更維舟。","河橋有酒無人醉，獨上高城望庾樓。"]', '["垂釣京江欲白头，江鱼堪釣却西游。","劉伶台下稻花晚，韓信廟前楓葉秋。","淮月未明先倚檻，海云初起更維舟。","河橋有酒無人醉，独上高城望庾楼。"]', '诗', 'shi', '', NULL, '淮陰阻風寄呈楚州韋中丞 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ab08a25-3566-4685-bc84-135b01ff8b76', '途經敷水', '途經敷水', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["脩蛾顰翠倚柔桑，遙謝春風白面郎。","五夜有情隨暮雨，百年無節待秋霜。","重尋繡帶朱藤合，更認羅帬碧草長。","何處野花何處水，下峰流出一渠香。"]', '["脩蛾顰翠倚柔桑，遙謝春风白面郎。","五夜有情隨暮雨，百年無節待秋霜。","重尋繡带朱藤合，更認羅帬碧草长。","何处野花何处水，下峰流出一渠香。"]', '诗', 'shi', '', NULL, '途經敷水 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56c90199-7634-48a5-8718-69c170939617', '和人賀楊僕射致政', '和人賀楊僕射致政', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["蓮府公卿拜後塵，手持優詔挂朱輪。","從軍暮下三千客，聞禮庭中七十人。","錦帳麗詞推北巷，畫堂清樂掩南鄰。","豈同王謝山陰會，空敘流杯醉暮春。"]', '["蓮府公卿拜後塵，手持優詔挂朱輪。","從軍暮下三千客，闻禮庭中七十人。","錦帳丽词推北巷，畫堂清乐掩南鄰。","豈同王謝山陰會，空敘流杯醉暮春。"]', '诗', 'shi', '', NULL, '和人賀楊僕射致政 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df76ec52-49a3-4754-b7d9-32134fe039dc', '題四皓廟', '題四皓廟', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["桂香松暖廟門開，獨瀉椒漿奠一杯。","秦法欲興鴻已去，漢儲將廢鳳還來。","紫芝翳翳多青草，白石蒼蒼半綠苔。","山下驛塵南竄路，不知冠蓋幾人回。"]', '["桂香松暖廟门开，独瀉椒漿奠一杯。","秦法欲兴鴻已去，漢儲將廢鳳還来。","紫芝翳翳多青草，白石蒼蒼半綠苔。","山下驛塵南竄路，不知冠蓋幾人回。"]', '诗', 'shi', '', NULL, '題四皓廟 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8fd7fd1-7129-4704-9da4-39b0f585ff15', '鶴林寺中秋夜翫月', '鹤林寺中秋夜翫月', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["待月東林月正圓，廣庭無樹草無煙。","中秋雲盡出滄海，半夜露寒當碧天。","輪彩漸移金殿外，鏡光猶挂玉樓前。","莫辭達曙殷勤望，一墮西巖又隔年。"]', '["待月东林月正圓，廣庭無樹草無煙。","中秋云尽出滄海，半夜露寒當碧天。","輪彩漸移金殿外，镜光猶挂玉楼前。","莫辞達曙殷勤望，一墮西巖又隔年。"]', '诗', 'shi', '', NULL, '鶴林寺中秋夜翫月 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72ad73af-d452-47f2-9aee-63d0a1926b17', '南海府罷歸京口經大庾嶺贈張明府', '南海府罷归京口經大庾嶺贈張明府', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["樓船旌斾極天涯，一劍從軍兩鬢華。","回日眼明河畔草，去時腸斷嶺頭花。","陶詩盡寫行過縣，張賦初成臥到家。","官滿知君有歸處，姑蘇臺上舊煙霞。"]', '["楼船旌斾極天涯，一劍從軍兩鬢华。","回日眼明河畔草，去时腸斷嶺头花。","陶诗尽寫行過縣，張賦初成臥到家。","官满知君有归处，姑蘇台上旧煙霞。"]', '诗', 'shi', '', NULL, '南海府罷歸京口經大庾嶺贈張明府 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79f3675d-ca4e-40e3-b4f4-e851c9eba61f', '題衛將軍廟', '題衛將軍廟', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["武牢關下護龍旗，挾槊彎弧馬上飛。","漢業未興王霸在，秦軍纔散魯連歸。","墳穿大澤埋金劍，廟枕長溪挂鐵衣。","欲奠忠魂何處問，葦花楓葉雨霏霏。"]', '["武牢关下護龙旗，挾槊彎弧马上飞。","漢業未兴王霸在，秦軍纔散魯連归。","墳穿大澤埋金劍，廟枕长溪挂鐵衣。","欲奠忠魂何处问，葦花楓葉雨霏霏。"]', '诗', 'shi', '', NULL, '題衛將軍廟 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3a4e04f-e9d3-4333-964a-3c3146edad00', '訪別韋隱居不值', '訪別韋隐居不值', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["犬吠雙巖碧樹間，主人朝出半開關。","湯師閣上留詩別，杜叟橋邊載酒還。","櫟塢炭煙晴過嶺，蓼村漁火夜移灣。","故鄉蕪沒兵戈後，憑向溪南買一山。"]', '["犬吠雙巖碧樹间，主人朝出半开关。","湯師閣上留诗別，杜叟橋邊載酒還。","櫟塢炭煙晴過嶺，蓼村漁火夜移灣。","故乡蕪沒兵戈後，憑向溪南買一山。"]', '诗', 'shi', '', NULL, '訪別韋隱居不值 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aea5b341-7410-48c7-9578-dabf5dc34e46', '送前東陽于明府由鄂渚歸故林', '送前东陽于明府由鄂渚归故林', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["結束征車換黑貂，灞西風雨正瀟瀟。","茂陵久病書千卷，彭澤初歸酒一瓢。","帆背夕陽湓水闊，棹經滄海甑山遙。","殷勤爲謝南溪客，白首螢窗未見招。"]', '["結束征车換黑貂，灞西风雨正瀟瀟。","茂陵久病书千卷，彭澤初归酒一瓢。","帆背夕陽湓水闊，棹經滄海甑山遙。","殷勤爲謝南溪客，白首螢窗未见招。"]', '诗', 'shi', '', NULL, '送前東陽于明府由鄂渚歸故林 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7de37ff7-b0be-49c7-8266-0532cea36445', '聽歌鷓鴣辭', '听歌鷓鴣辞', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["南國多情多豔詞，鷓鴣清怨遶梁飛。","甘棠城上客先醉，苦竹嶺頭人未歸。","響轉碧霄雲駐影，曲終清漏月沈暉。","山行水宿不知遠，猶夢玉釵金縷衣。"]', '["南国多情多豔词，鷓鴣清怨遶梁飞。","甘棠城上客先醉，苦竹嶺头人未归。","响轉碧霄云駐影，曲終清漏月沈暉。","山行水宿不知远，猶梦玉釵金縷衣。"]', '诗', 'shi', '', NULL, '聽歌鷓鴣辭 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f309e84e-fe0a-464f-8f77-37fd3e63dc2e', '寄題華嚴韋秀才院', '寄題华嚴韋秀才院', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["三面樓臺百丈峰，西巖高枕樹重重。","晴攀翠竹題詩滑，秋摘黃花釀酒濃。","山殿日斜喧鳥雀，石潭波動戲魚龍。","今來故國遙相憶，月照千山半夜鐘。"]', '["三面楼台百丈峰，西巖高枕樹重重。","晴攀翠竹題诗滑，秋摘黄花釀酒濃。","山殿日斜喧鸟雀，石潭波动戲鱼龙。","今来故国遙相憶，月照千山半夜鐘。"]', '诗', 'shi', '', NULL, '寄題華嚴韋秀才院 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8fffc9d-a2e2-47e7-9aae-0f794790adda', '戲代李協律松江有贈', '戲代李協律松江有贈', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["蜀客操琴吳女歌，明珠十斛是天河。","霜凝薜荔怯秋樹，露滴芙蓉愁晚波。","蘭浦遠鄉應解珮，柳堤殘月未鳴珂。","西樓沈醉不知散，潮落洞庭洲渚多。"]', '["蜀客操琴吳女歌，明珠十斛是天河。","霜凝薜荔怯秋樹，露滴芙蓉愁晚波。","蘭浦远乡應解珮，柳堤殘月未鳴珂。","西楼沈醉不知散，潮落洞庭洲渚多。"]', '诗', 'shi', '', NULL, '戲代李協律松江有贈 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b5586c1-bacb-4ffa-971a-47322ed6a974', '送黃隱居歸南海', '送黄隐居归南海', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["瘴霧南邊久寄家，海中來往信流槎。","林藏●●多殘笋，樹過猩猩少落花。","深洞有雲龍蛻骨，半巖無草象生牙。","知君愛宿層峰頂，坐到三更見日華。"]', '["瘴霧南邊久寄家，海中来往信流槎。","林藏●●多殘笋，樹過猩猩少落花。","深洞有云龙蛻骨，半巖無草象生牙。","知君愛宿層峰頂，坐到三更见日华。"]', '诗', 'shi', '', NULL, '送黃隱居歸南海 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8f07dd3-8ebc-41cc-bdbb-ca8e8777de12', '朝臺送客有懷', '朝台送客有懷', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["趙佗西拜已登壇，馬援南征土宇寬。","越國舊無唐印綬，蠻鄉今有漢衣冠。","江雲帶日秋偏熱，海雨隨風夏亦寒。","嶺北歸人莫回首，蓼花楓葉萬重灘。"]', '["趙佗西拜已登壇，马援南征土宇寬。","越国旧無唐印綬，蠻乡今有漢衣冠。","江云带日秋偏熱，海雨隨风夏亦寒。","嶺北归人莫回首，蓼花楓葉万重灘。"]', '诗', 'shi', '', NULL, '朝臺送客有懷 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aea87c55-b0c8-40d1-8de9-42af0a04941a', '自楞伽寺晨起汎舟道中有懷', '自楞伽寺晨起汎舟道中有懷', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["碧樹蒼蒼茂苑東，佳期迢遰路何窮。","一聲山鳥曙雲外，萬點水螢秋草中。","門掩竹齋微有月，棹移蘭渚淡無風。","欲知此路堪惆悵，菱葉蓼花連故宮。"]', '["碧樹蒼蒼茂苑东，佳期迢遰路何窮。","一声山鸟曙云外，万点水螢秋草中。","门掩竹斋微有月，棹移蘭渚淡無风。","欲知此路堪惆悵，菱葉蓼花連故宮。"]', '诗', 'shi', '', NULL, '自楞伽寺晨起汎舟道中有懷 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37ebc5b7-0042-47f4-ba70-21fe5fb0e106', '十二月拜起居表回', '十二月拜起居表回', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["一章西奏拜仙曹，回馬天津北望勞。","寒水欲春冰彩薄，曉山初霽雪峰高。","樓形向日攢飛鳳，宮勢凌波壓抃鼇。","空鎖煙霞絕巡幸，周人誰識鬱金袍。"]', '["一章西奏拜仙曹，回马天津北望勞。","寒水欲春冰彩薄，晓山初霽雪峰高。","楼形向日攢飞鳳，宮勢凌波壓抃鼇。","空鎖煙霞絕巡幸，周人誰識鬱金袍。"]', '诗', 'shi', '', NULL, '十二月拜起居表回 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b466b514-5cc0-43b7-ac2f-124e16a9717f', '觀章中丞夜按歌舞', '观章中丞夜按歌舞', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["夜按雙娃禁曲新，東西簫鼓接雲津。","舞衫未換紅鉛濕，歌扇初移翠黛顰。","彩檻燭煙光吐日，畫屏香霧暖如春。","西樓月在襄王醉，十二山高不見人。"]', '["夜按雙娃禁曲新，东西簫鼓接云津。","舞衫未換紅鉛濕，歌扇初移翠黛顰。","彩檻燭煙光吐日，畫屏香霧暖如春。","西楼月在襄王醉，十二山高不见人。"]', '诗', 'shi', '', NULL, '觀章中丞夜按歌舞 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cdc8b6c6-510b-4fce-89bb-902748f76b09', '重遊飛泉觀題故梁道士宿龍池', '重游飞泉观題故梁道士宿龙池', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["西巖泉落水容寬，靈物蜿蜒黑處蟠。","松葉正秋琴韻響，菱花初曉鏡光寒。","雲開星月浮山殿，雨過風雷遶石壇。","仙客不歸龍亦去，稻畦長滿此池乾。"]', '["西巖泉落水容寬，靈物蜿蜒黑处蟠。","松葉正秋琴韻响，菱花初晓镜光寒。","云开星月浮山殿，雨過风雷遶石壇。","仙客不归龙亦去，稻畦长满此池乾。"]', '诗', 'shi', '', NULL, '重遊飛泉觀題故梁道士宿龍池 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbe6c582-80c9-4c5d-9ccc-d4a9dd2cde6f', '下第貽友人', '下第貽友人', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["身在關西家洞庭，夜寒歌苦燭熒熒。","人心高下月中桂，客思往來波上萍。","馬氏識君眉最白，阮公留我眼長青。","花前失意共寥落，莫遣東風吹酒醒。"]', '["身在关西家洞庭，夜寒歌苦燭熒熒。","人心高下月中桂，客思往来波上萍。","马氏識君眉最白，阮公留我眼长青。","花前失意共寥落，莫遣东风吹酒醒。"]', '诗', 'shi', '', NULL, '下第貽友人 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3636ccf3-83e5-4971-9515-ffbbe2076098', '晚登龍門驛樓', '晚登龙门驛楼', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["魚龍多處鑿門開，萬古人知夏禹材。","青嶂遠分從地斷，洪流高瀉自天來。","風雲有路皆燒尾，波浪無程盡曝腮。","心感膺門身過此，晚山秋樹獨徘徊。"]', '["鱼龙多处鑿门开，万古人知夏禹材。","青嶂远分從地斷，洪流高瀉自天来。","风云有路皆燒尾，波浪無程尽曝腮。","心感膺门身過此，晚山秋樹独徘徊。"]', '诗', 'shi', '', NULL, '晚登龍門驛樓 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b55d90d-c7cb-44c8-9af1-1815da24adb3', '題故李秀才居', '題故李秀才居', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["曾醉笙歌日正遲，醉中相送易前期。","橘花滿地人亡後，菰葉連天鴈過時。","琴倚舊窗塵漠漠，劍埋新塚草離離。","河橋酒熟平生事，更向東流奠一巵。"]', '["曾醉笙歌日正遲，醉中相送易前期。","橘花满地人亡後，菰葉連天鴈過时。","琴倚旧窗塵漠漠，劍埋新塚草離離。","河橋酒熟平生事，更向东流奠一巵。"]', '诗', 'shi', '', NULL, '題故李秀才居 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('715b7527-abf9-4f7f-bc9d-c7a8602722f1', '韶州韶陽樓夜讌', '韶州韶陽楼夜讌', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["待月西樓捲翠羅，玉杯瑤瑟近星河。","簾前碧樹窮秋密，窗外青山薄暮多。","鸜鵒未知狂客醉，鷓鴣先讓美人歌。","使君莫惜通宵飲，刀筆初從馬伏波。"]', '["待月西楼捲翠羅，玉杯瑤瑟近星河。","簾前碧樹窮秋密，窗外青山薄暮多。","鸜鵒未知狂客醉，鷓鴣先讓美人歌。","使君莫惜通宵饮，刀笔初從马伏波。"]', '诗', 'shi', '', NULL, '韶州韶陽樓夜讌 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa0d9975-9221-4550-86f8-6feecc7de0e5', '聞韶州李相公移拜郴州因寄', '闻韶州李相公移拜郴州因寄', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["詔移丞相木蘭舟，桂水潺湲嶺北流。","青漢夢歸雙闕曙，白雲吟過五湖秋。","恩迴玉扆人先喜，道在金縢世不憂。","聞說公卿盡南望，甘堂花暖鳳池頭。"]', '["詔移丞相木蘭舟，桂水潺湲嶺北流。","青漢梦归雙闕曙，白云吟過五湖秋。","恩迴玉扆人先喜，道在金縢世不憂。","闻说公卿尽南望，甘堂花暖鳳池头。"]', '诗', 'shi', '', NULL, '聞韶州李相公移拜郴州因寄 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69f6930a-1b7f-442e-a8f9-3e49b9d6dc41', '游江令舊宅', '游江令旧宅', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["身沒南朝宅已荒，邑人猶賞舊風光。","芹根生葉石池淺，桐樹落花金井香。","帶暖山蜂巢畫閣，欲陰溪燕集書堂。","閑愁此地更西望，潮侵臺城春草長。"]', '["身沒南朝宅已荒，邑人猶賞旧风光。","芹根生葉石池淺，桐樹落花金井香。","带暖山蜂巢畫閣，欲陰溪燕集书堂。","闲愁此地更西望，潮侵台城春草长。"]', '诗', 'shi', '', NULL, '游江令舊宅 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1fa5e04-8812-4be1-bfec-c6c46ee9b123', '灞上逢元九處士東歸', '灞上逢元九处士东归', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["瘦馬頻嘶灞水寒，灞南高處望長安。","何人更結王生韤，此客虛彈貢氏冠。","江上蟹螯沙渺渺，塢中蝸殻雪漫漫。","舊交已變新知少，却伴漁郎把釣竿。"]', '["瘦马頻嘶灞水寒，灞南高处望长安。","何人更結王生韤，此客虛彈貢氏冠。","江上蟹螯沙渺渺，塢中蝸殻雪漫漫。","旧交已变新知少，却伴漁郎把釣竿。"]', '诗', 'shi', '', NULL, '灞上逢元九處士東歸 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77720722-e794-4784-af17-a45629f48ffc', '別張秀才', '別張秀才', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["不知何計寫離憂，萬里山川半舊遊。","風捲暮沙和雪起，日融春水帶冰流。","凌晨客淚分東郭，竟夕鄉心共北樓。","青桂一枝年少事，莫因鱸鱠涉窮秋。"]', '["不知何計寫離憂，万里山川半旧游。","风捲暮沙和雪起，日融春水带冰流。","凌晨客泪分东郭，竟夕乡心共北楼。","青桂一枝年少事，莫因鱸鱠涉窮秋。"]', '诗', 'shi', '', NULL, '別張秀才 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6af20330-720f-421a-9053-fac494afe21f', '別表兄軍倅', '別表兄軍倅', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["盧橘花香拂釣磯，佳人猶舞越羅衣。","三洲水淺魚來少，五嶺山高鴈到稀。","客路晚依紅樹宿，鄉關朝望白雲歸。","交親不念征南吏，昨夜風帆去似飛。"]', '["盧橘花香拂釣磯，佳人猶舞越羅衣。","三洲水淺鱼来少，五嶺山高鴈到稀。","客路晚依紅樹宿，乡关朝望白云归。","交親不念征南吏，昨夜风帆去似飞。"]', '诗', 'shi', '', NULL, '別表兄軍倅 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2756ce65-b929-4076-8890-3edd27e5f2fa', '題蘇州虎丘寺僧院', '題蘇州虎丘寺僧院', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["暫引寒泉濯遠塵，此生多是異鄉人。","荆溪夜雨花開疾，吳苑秋風月滿頻。","萬里高低門外路，百年榮辱夢中身。","世間誰似西林客，一臥煙霞四十春。"]', '["暫引寒泉濯远塵，此生多是異乡人。","荆溪夜雨花开疾，吳苑秋风月满頻。","万里高低门外路，百年榮辱梦中身。","世间誰似西林客，一臥煙霞四十春。"]', '诗', 'shi', '', NULL, '題蘇州虎丘寺僧院 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2af6b992-2527-4dc6-afe4-ea147e6ae83e', '酬郭少府先奉使巡澇見寄兼呈裴明府', '酬郭少府先奉使巡澇见寄兼呈裴明府', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["載書攜榼別池龍，十幅輕帆處處通。","謝朓宅荒山翠裏，王敦城古月明中。","江村夜漲浮天水，澤國秋生動地風。","飽食鱠魚榜歸檝，待君琴酒醉陶公。"]', '["載书携榼別池龙，十幅轻帆处处通。","謝朓宅荒山翠裏，王敦城古月明中。","江村夜漲浮天水，澤国秋生动地风。","飽食鱠鱼榜归檝，待君琴酒醉陶公。"]', '诗', 'shi', '', NULL, '酬郭少府先奉使巡澇見寄兼呈裴明府 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80340874-0693-46e9-ae66-13a66ffbc102', '出永通門經李氏莊', '出永通门經李氏莊', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["飛軒危檻百花堂，朝讌歌鐘暮已荒。","中散獄成琴自怨，步兵廚廢酒猶香。","風池宿鳥喧朱閣，雨砌秋螢拂畫梁。","力保山河家又慶，秪應中令敵汾陽。"]', '["飞軒危檻百花堂，朝讌歌鐘暮已荒。","中散獄成琴自怨，步兵廚廢酒猶香。","风池宿鸟喧朱閣，雨砌秋螢拂畫梁。","力保山河家又慶，秪應中令敵汾陽。"]', '诗', 'shi', '', NULL, '出永通門經李氏莊 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf806992-1df3-4e62-aab9-07f7d54f4d1d', '漢水傷稼', '漢水傷稼', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["西北樓開四望通，殘霞成綺月懸弓。","江村夜漲浮天水，澤國秋生動地風。","高下綠苗千頃盡，新陳紅粟萬厫空。","才微分薄憂何益，却欲回心學釣翁。"]', '["西北楼开四望通，殘霞成綺月懸弓。","江村夜漲浮天水，澤国秋生动地风。","高下綠苗千頃尽，新陳紅粟万厫空。","才微分薄憂何益，却欲回心学釣翁。"]', '诗', 'shi', '', NULL, '漢水傷稼 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa80cf56-96c7-4b4d-b5c8-4932bd463d34', '送王總下第歸丹陽', '送王總下第归丹陽', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["秦樓心斷楚江湄，繫馬春風酒一巵。","汴水月明東下疾，練塘花發北來遲。","青蕪定沒安貧處，黃葉應催獻賦詩。","憑寄家書爲回報，舊鄉還有故人知。"]', '["秦楼心斷楚江湄，繫马春风酒一巵。","汴水月明东下疾，練塘花發北来遲。","青蕪定沒安貧处，黄葉應催獻賦诗。","憑寄家书爲回報，旧乡還有故人知。"]', '诗', 'shi', '', NULL, '送王總下第歸丹陽 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f77823c-b072-4d3f-9a75-092270339072', '南陽道中', '南陽道中', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["月斜孤館傍村行，野店高低帶古城。","籬上曉花齋後落，井邊秋葉社前生。","飢烏索哺隨雛叫，乳牸慵歸望犢鳴。","荒草連天風動地，不知誰學武侯耕。"]', '["月斜孤館傍村行，野店高低带古城。","籬上晓花斋後落，井邊秋葉社前生。","飢烏索哺隨雛叫，乳牸慵归望犢鳴。","荒草連天风动地，不知誰学武侯耕。"]', '诗', 'shi', '', NULL, '南陽道中 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6333f99b-7315-4c72-9e26-1abacd63737d', '破北虜太和公主歸宮闕', '破北虜太和公主归宮闕', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["毳幕承秋極斷蓬，飄颻一劍黑山空。","匈奴北走荒秦壘，貴主西還盛漢宮。","定是廟謨傾種落，必知邊寇畏驍雄。","恩霑殘類從歸去，莫使華人雜犬戎。"]', '["毳幕承秋極斷蓬，飄颻一劍黑山空。","匈奴北走荒秦壘，貴主西還盛漢宮。","定是廟謨傾種落，必知邊寇畏驍雄。","恩霑殘類從归去，莫使华人杂犬戎。"]', '诗', 'shi', '', NULL, '破北虜太和公主歸宮闕 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c40b2a94-60bc-499b-b9ef-c05f20f3088c', '李定言自殿院銜命歸闕拜員外郎遷右史因寄', '李定言自殿院銜命归闕拜員外郎遷右史因寄', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["白筆南征變二毛，越山愁瘴海驚濤。","才歸龍尾含雞舌，更立螭頭運兔毫。","閶闔欲開宮漏盡，冕旒初坐御香高。","吳中舊侶君先貴，曾憶王祥與佩刀。"]', '["白笔南征变二毛，越山愁瘴海驚濤。","才归龙尾含雞舌，更立螭头運兔毫。","閶闔欲开宮漏尽，冕旒初坐御香高。","吳中旧侶君先貴，曾憶王祥與佩刀。"]', '诗', 'shi', '', NULL, '李定言自殿院銜命歸闕拜員外郎遷右史因寄 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bc887f7-4db4-4fe3-b256-00bdfd813813', '早秋韶陽夜雨', '早秋韶陽夜雨', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["宋玉含悽夢亦驚，芙蓉山響一猨聲。","陰雲迎雨枕先潤，夜電引雷窗暫明。","暗惜水花飄廣檻，遠愁風葉下高城。","西歸萬里未千里，應到故園春草生。"]', '["宋玉含悽梦亦驚，芙蓉山响一猨声。","陰云迎雨枕先潤，夜電引雷窗暫明。","暗惜水花飄廣檻，远愁风葉下高城。","西归万里未千里，應到故园春草生。"]', '诗', 'shi', '', NULL, '早秋韶陽夜雨 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d84c01f4-7bec-4af9-8115-f9c0488f02a8', '將爲南行陪尚書崔公宴海榴堂', '將爲南行陪尚书崔公宴海榴堂', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["朝讌華堂暮未休，幾人偏得謝公留。","風傳鼓角霜侵戟，雲捲笙歌月上樓。","賓館盡開徐穉榻，客帆空戀李膺舟。","謾誇書劍無知己，水遠山長步步愁。"]', '["朝讌华堂暮未休，幾人偏得謝公留。","风傳鼓角霜侵戟，云捲笙歌月上楼。","賓館尽开徐穉榻，客帆空戀李膺舟。","謾誇书劍無知己，水远山长步步愁。"]', '诗', 'shi', '', NULL, '將爲南行陪尚書崔公宴海榴堂 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b765a61-6bd5-4495-8656-e18b25d5f07f', '贈王山人', '贈王山人', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["貰酒攜琴訪我頻，始知城市有閑人。","君臣藥在寧憂病，子母錢成豈患貧。","年長每勞推甲子，夜寒初共守庚申。","近來聞說燒丹處，玉洞桃花萬樹春。"]', '["貰酒携琴訪我頻，始知城市有闲人。","君臣藥在寧憂病，子母錢成豈患貧。","年长每勞推甲子，夜寒初共守庚申。","近来闻说燒丹处，玉洞桃花万樹春。"]', '诗', 'shi', '', NULL, '贈王山人 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e822a39-3f65-49b3-945c-3ce524349604', '宣城崔大夫召聯句偶疾不獲赴因獻', '宣城崔大夫召聯句偶疾不獲赴因獻', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["心慕知音命自拘，畫堂聞欲試吹竽。","茂陵罷酒慙中聖，漳浦題詩怯大巫。","鬐鬣幾年傷在藻，羽毛終日羨棲梧。","還愁旅棹空歸去，楓葉荷花釣五湖。"]', '["心慕知音命自拘，畫堂闻欲試吹竽。","茂陵罷酒慙中聖，漳浦題诗怯大巫。","鬐鬣幾年傷在藻，羽毛終日羨棲梧。","還愁旅棹空归去，楓葉荷花釣五湖。"]', '诗', 'shi', '', NULL, '宣城崔大夫召聯句偶疾不獲赴因獻 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0206f6dc-bd9e-4493-970f-0cafc6182d06', '贈鄭處士', '贈鄭处士', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["道傍年少莫矜誇，心在重霄鬢未華。","楊子可曾過北里，魯人何必敬東家。","寒雲曉散千峰雪，暖雨晴開一逕花。","且賣湖田釀春酒，與君書劍是生涯。"]', '["道傍年少莫矜誇，心在重霄鬢未华。","楊子可曾過北里，魯人何必敬东家。","寒云晓散千峰雪，暖雨晴开一逕花。","且賣湖田釀春酒，與君书劍是生涯。"]', '诗', 'shi', '', NULL, '贈鄭處士 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1beb4e80-dac6-4601-9037-54d728c4742f', '正元', '正元', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["高揭雞竿闢帝閽，祥風微暖瑞雲屯。","千官共削姦臣迹，萬國初銜聖主恩。","宮殿雪華齊紫閣，關河春色到青門。","華夷一軌人方泰，莫學論兵誤至尊。"]', '["高揭雞竿闢帝閽，祥风微暖瑞云屯。","千官共削姦臣迹，万国初銜聖主恩。","宮殿雪华齊紫閣，关河春色到青门。","华夷一軌人方泰，莫学論兵誤至尊。"]', '诗', 'shi', '', NULL, '正元 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('307680c8-bffb-452d-a569-92f95a985a6c', '登尉佗樓', '登尉佗楼', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["劉項持兵鹿未窮，自乘黃屋島夷中。","南來作尉任囂力，北向稱臣陸賈功。","簫鼓尚陳今世廟，旌旗猶鎮昔時宮。","越人未必知虞舜，一奏薰弦萬古風。"]', '["劉項持兵鹿未窮，自乘黄屋島夷中。","南来作尉任囂力，北向稱臣陸賈功。","簫鼓尚陳今世廟，旌旗猶鎮昔时宮。","越人未必知虞舜，一奏薰弦万古风。"]', '诗', 'shi', '', NULL, '登尉佗樓 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5de7e026-c57f-446b-96e5-76da05392c43', '詔州驛樓宴罷', '詔州驛楼宴罷', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["簷外千帆背夕陽，歸心杳杳鬢蒼蒼。","嶺猨羣宿夜山靜，沙鳥獨飛秋水涼。","露墮桂花棋局濕，風吹荷葉酒瓶香。","主人不醉下樓去，月在南軒更漏長。"]', '["簷外千帆背夕陽，归心杳杳鬢蒼蒼。","嶺猨羣宿夜山静，沙鸟独飞秋水涼。","露墮桂花棋局濕，风吹荷葉酒瓶香。","主人不醉下楼去，月在南軒更漏长。"]', '诗', 'shi', '', NULL, '詔州驛樓宴罷 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1adcd8fe-d00a-4794-ba69-a36f0807c30a', '和淮南王相公與賓僚同游瓜洲別業題舊書齋', '和淮南王相公與賓僚同游瓜洲別業題旧书斋', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["碧油紅斾想青衿，積雪窗前盡日吟。","巢鶴去時雲樹老，臥龍歸處石潭深。","道傍苦李猶垂實，城外甘棠已布陰。","賓御莫辭巖下醉，武丁高枕待爲霖。"]', '["碧油紅斾想青衿，積雪窗前尽日吟。","巢鹤去时云樹老，臥龙归处石潭深。","道傍苦李猶垂實，城外甘棠已布陰。","賓御莫辞巖下醉，武丁高枕待爲霖。"]', '诗', 'shi', '', NULL, '和淮南王相公與賓僚同游瓜洲別業題舊書齋 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87c548cc-0250-4e37-83e8-c72ad7d38bb5', '送盧先輩自衡岳赴復州嘉禮二首 一', '送盧先輩自衡岳赴复州嘉禮二首 一', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["名振金閨步玉京，暫留滄海見高情。","衆花盡處松千尺，羣鳥喧時鶴一聲。","朱閣簟涼疎雨過，碧溪船動早潮生。","離心不異西江水，直送征帆萬里行。"]', '["名振金閨步玉京，暫留滄海见高情。","衆花尽处松千尺，羣鸟喧时鹤一声。","朱閣簟涼疎雨過，碧溪船动早潮生。","離心不異西江水，直送征帆万里行。"]', '诗', 'shi', '', NULL, '送盧先輩自衡岳赴復州嘉禮二首 一 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc45bbb9-48b7-47e0-b76e-c228dec705e5', '送盧先輩自衡岳赴復州嘉禮二首 二', '送盧先輩自衡岳赴复州嘉禮二首 二', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["湘南詩客海中行，鵬翅垂雲不自矜。","秋水靜磨金鏡土，夜風寒結玉壺冰。","萬重嶺嶠辭衡岳，千里山陂問竟陵。","醉倚西樓人已遠，柳溪無浪月澄澄。"]', '["湘南诗客海中行，鵬翅垂云不自矜。","秋水静磨金镜土，夜风寒結玉壺冰。","万重嶺嶠辞衡岳，千里山陂问竟陵。","醉倚西楼人已远，柳溪無浪月澄澄。"]', '诗', 'shi', '', NULL, '送盧先輩自衡岳赴復州嘉禮二首 二 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96739c37-563c-4388-997b-021f963caaf1', '哭楊攀處士', '哭楊攀处士', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["先生憂道樂清貧，白髮終爲不仕身。","嵇阮沒來無酒客，應劉亡後少詩人。","山前月照荒墳曉，溪上花開舊宅春。","昨夜回舟更惆悵，至今鐘磬滿南鄰。"]', '["先生憂道乐清貧，白髮終爲不仕身。","嵇阮沒来無酒客，應劉亡後少诗人。","山前月照荒墳晓，溪上花开旧宅春。","昨夜回舟更惆悵，至今鐘磬满南鄰。"]', '诗', 'shi', '', NULL, '哭楊攀處士 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a133e01-9bdb-4643-94f4-2ae5ee9e71d3', '宿松江驛却寄蘇州一二同志', '宿松江驛却寄蘇州一二同志', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["候館人稀夜自長，姑蘇臺遠樹蒼蒼。","江湖潮落高樓迥，河漢秋歸廣簟涼。","月轉碧梧移鵲影，露低紅葉濕螢光。","西園詩侶應多思，莫醉笙歌掩畫堂。"]', '["候館人稀夜自长，姑蘇台远樹蒼蒼。","江湖潮落高楼迥，河漢秋归廣簟涼。","月轉碧梧移鵲影，露低紅葉濕螢光。","西园诗侶應多思，莫醉笙歌掩畫堂。"]', '诗', 'shi', '', NULL, '宿松江驛却寄蘇州一二同志 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d89b7239-db88-4797-85ba-3d44fe8e69d6', '盧山人自巴蜀由湘潭歸茅山因贈', '盧山人自巴蜀由湘潭归茅山因贈', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["太乙靈方鍊紫荷，紫荷飛盡髪皤皤。","猨啼巫峽曉雲薄，鴈宿洞庭秋月多。","導引豈如桃葉舞，步虛寧比竹枝歌。","華陽舊隱莫歸去，水沒芝田生綠莎。"]', '["太乙靈方鍊紫荷，紫荷飞尽髪皤皤。","猨啼巫峽晓云薄，鴈宿洞庭秋月多。","導引豈如桃葉舞，步虛寧比竹枝歌。","华陽旧隐莫归去，水沒芝田生綠莎。"]', '诗', 'shi', '', NULL, '盧山人自巴蜀由湘潭歸茅山因贈 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6d2ba3a-f3a7-479e-b4d7-705ef40659fc', '潁州從事西湖亭讌餞', '潁州從事西湖亭讌餞', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["西湖清宴不知回，一曲離歌酒一杯。","城帶夕陽聞鼓角，寺臨秋水見樓臺。","蘭堂客散蟬猶噪，桂檝人稀鳥自來。","獨想征車過鞏洛，此中霜菊遶潭開。"]', '["西湖清宴不知回，一曲離歌酒一杯。","城带夕陽闻鼓角，寺臨秋水见楼台。","蘭堂客散蟬猶噪，桂檝人稀鸟自来。","独想征车過鞏洛，此中霜菊遶潭开。"]', '诗', 'shi', '', NULL, '潁州從事西湖亭讌餞 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33a6b7e8-bb42-453c-a7f8-9be2693f18fd', '瓜洲留別李詡', '瓜洲留別李詡', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["泣玉三年一見君，白衣顦顇更離羣。","柳堤惜別春潮落，花榭留歡夜漏分。","孤館宿時風帶雨，遠帆歸處水連雲。","悲歌曲盡莫重奏，心遶關河不忍聞。"]', '["泣玉三年一见君，白衣顦顇更離羣。","柳堤惜別春潮落，花榭留歡夜漏分。","孤館宿时风带雨，远帆归处水連云。","悲歌曲尽莫重奏，心遶关河不忍闻。"]', '诗', 'shi', '', NULL, '瓜洲留別李詡 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d8f3075-99c5-41a3-ba13-67a91119a601', '余謝病東歸王秀才見寄今潘秀才南櫂奉酬', '余謝病东归王秀才见寄今潘秀才南櫂奉酬', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["酷似牢之玉不如，落星山下白雲居。","春耕旋搆金門客，夜學兼修玉府書。","風掃碧雲迎鷙鳥，水還滄海養嘉魚。","莫將年少輕時節，王氏家風在石渠。"]', '["酷似牢之玉不如，落星山下白云居。","春耕旋搆金门客，夜学兼修玉府书。","风掃碧云迎鷙鸟，水還滄海養嘉鱼。","莫將年少轻时節，王氏家风在石渠。"]', '诗', 'shi', '', NULL, '余謝病東歸王秀才見寄今潘秀才南櫂奉酬 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99d8f0c4-310a-4a90-a365-1b59cd3f0799', '獻韶陽相國崔公', '獻韶陽相国崔公', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["一匱爲功極九層，康莊猶自劍稜稜。","舟回北渚經年泊，門接東山盡日登。","萬國已聞傳玉璽，百官猶望啓金縢。","賢臣會致唐虞世，獨倚江樓笑范增。"]', '["一匱爲功極九層，康莊猶自劍稜稜。","舟回北渚經年泊，门接东山尽日登。","万国已闻傳玉璽，百官猶望啓金縢。","賢臣會致唐虞世，独倚江楼笑范增。"]', '诗', 'shi', '', NULL, '獻韶陽相國崔公 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8996f97b-e892-464e-82cd-d4243c29f2c6', '郡齋夜坐寄舊鄉二姪', '郡斋夜坐寄旧乡二姪', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["千官奉職衮龍垂，旅臥淮陽鬢日衰。","三月已乖棠樹政，二年空負竹林期。","樓侵白浪風來遠，城抱丹巖日到遲。","長欲挂帆君莫笑，越禽花晚夢南枝。"]', '["千官奉職衮龙垂，旅臥淮陽鬢日衰。","三月已乖棠樹政，二年空負竹林期。","楼侵白浪风来远，城抱丹巖日到遲。","长欲挂帆君莫笑，越禽花晚梦南枝。"]', '诗', 'shi', '', NULL, '郡齋夜坐寄舊鄉二姪 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fdf21e7-c157-41ed-92f7-ff05fb4085af', '病間寄郡中文士', '病间寄郡中文士', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["盧橘含花處處香，老人依舊臥清漳。","心同客舍驚秋早，跡似僧齋厭夜長。","風捲翠簾琴自響，露凝朱閣簟先涼。","明朝欲醉文中彥，猶覺吟聲帶越鄉。"]', '["盧橘含花处处香，老人依旧臥清漳。","心同客舍驚秋早，跡似僧斋厭夜长。","风捲翠簾琴自响，露凝朱閣簟先涼。","明朝欲醉文中彥，猶覺吟声带越乡。"]', '诗', 'shi', '', NULL, '病間寄郡中文士 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0284d1c9-9be7-41a1-9d22-fc0a4e4b520a', '賀少師相公致政', '賀少師相公致政', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["六十懸車自古稀，我公年少獨忘機。","門臨二室留侯隱，櫂倚三川越相歸。","不擬優遊同陸賈，已回清白遺胡威。","龍城鳳沼棠陰在，只恐歸鴻更北飛。"]', '["六十懸车自古稀，我公年少独忘機。","门臨二室留侯隐，櫂倚三川越相归。","不擬優游同陸賈，已回清白遺胡威。","龙城鳳沼棠陰在，只恐归鴻更北飞。"]', '诗', 'shi', '', NULL, '賀少師相公致政 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4898ea89-d27c-441c-aa79-673c163c6ff6', '題崔處士山居', '題崔处士山居', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["坐窮今古掩書堂，二頃湖田一半荒。","荆樹有花兄弟樂，橘林無實子孫忙。","龍歸曉洞雲猶濕，麝過春山草自香。","向夜欲歸心萬里，故園松月更蒼蒼。"]', '["坐窮今古掩书堂，二頃湖田一半荒。","荆樹有花兄弟乐，橘林無實子孫忙。","龙归晓洞云猶濕，麝過春山草自香。","向夜欲归心万里，故园松月更蒼蒼。"]', '诗', 'shi', '', NULL, '題崔處士山居 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e07c080-8f4d-44cf-9d59-5427832dadca', '疾後與郡中羣公讌李秀才', '疾後與郡中羣公讌李秀才', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["強留佳客讌王孫，巖上餘花落酒樽。","書院欲開蟲網戶，訟庭猶掩雀羅門。","耳虛盡日疑琴癖，眼暗經秋覺鏡昏。","莫引劉安倚西檻，夜來紅葉下江村。"]', '["強留佳客讌王孫，巖上餘花落酒樽。","书院欲开蟲網戶，訟庭猶掩雀羅门。","耳虛尽日疑琴癖，眼暗經秋覺镜昏。","莫引劉安倚西檻，夜来紅葉下江村。"]', '诗', 'shi', '', NULL, '疾後與郡中羣公讌李秀才 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edb8d270-6674-43e3-8a3c-189365ea0ee6', '晨起白雲樓寄龍興江準上人兼呈竇秀才', '晨起白云楼寄龙兴江準上人兼呈竇秀才', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["茲樓今是望鄉臺，鄉信全稀曉鴈哀。","山翠萬重當檻出，水華千里抱城來。","東巖月在僧初定，南浦花殘客未回。","欲弔靈均能賦否，秋風還有木蘭開。"]', '["茲楼今是望乡台，乡信全稀晓鴈哀。","山翠万重當檻出，水华千里抱城来。","东巖月在僧初定，南浦花殘客未回。","欲弔靈均能賦否，秋风還有木蘭开。"]', '诗', 'shi', '', NULL, '晨起白雲樓寄龍興江準上人兼呈竇秀才 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e49f19d-ff9e-4084-a579-8e4402cc53bd', '醼餞李員外', '醼餞李員外', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["病守江城眼暫開，昔年吳越共銜杯。","膺舟出鎮虛陳榻，鄭履還京下隗臺。","雲葉漸低朱閣掩，浪花初起畫檣回。","心期解印同君醉，九曲池西望月來。"]', '["病守江城眼暫开，昔年吳越共銜杯。","膺舟出鎮虛陳榻，鄭履還京下隗台。","云葉漸低朱閣掩，浪花初起畫檣回。","心期解印同君醉，九曲池西望月来。"]', '诗', 'shi', '', NULL, '醼餞李員外 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('816e9dc3-3f40-4290-b851-a447e7a8f973', '詶錢汝州', '詶錢汝州', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["白雪多隨漢水流，謾勞旌斾晚悠悠。","笙歌暗寫終年恨，臺榭潛消盡日憂。","鳥散落花人自醉，馬嘶芳草客先愁。","怪來雅韻清無敵，三十六峰當庾樓。"]', '["白雪多隨漢水流，謾勞旌斾晚悠悠。","笙歌暗寫終年恨，台榭潛消尽日憂。","鸟散落花人自醉，马嘶芳草客先愁。","怪来雅韻清無敵，三十六峰當庾楼。"]', '诗', 'shi', '', NULL, '詶錢汝州 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fc69cf4-3bc3-47b5-8600-8bd4cb5515e6', '將歸姑蘇南樓餞送李明府', '將归姑蘇南楼餞送李明府', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["無處登臨不繫情，一憑春酒醉高城。","暫移羅綺見山色，纔駐管弦聞水聲。","花落西亭添別恨，柳陰南浦促歸程。","前期迢遰今宵短，更倚朱闌待月明。"]', '["無处登臨不繫情，一憑春酒醉高城。","暫移羅綺见山色，纔駐管弦闻水声。","花落西亭添別恨，柳陰南浦促归程。","前期迢遰今宵短，更倚朱闌待月明。"]', '诗', 'shi', '', NULL, '將歸姑蘇南樓餞送李明府 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47b0d54b-9f1c-4124-92d4-59f9312be617', '和浙西從事劉三復送僧南歸', '和浙西從事劉三复送僧南归', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["楚客送僧歸故鄉，海門帆勢極瀟湘。","碧雲千里暮愁合，白雪一聲春思長。","滿院草花平講席，繞龕藤葉蓋禪牀。","憐師不得隨師去，已戴儒冠事素王。"]', '["楚客送僧归故乡，海门帆勢極瀟湘。","碧云千里暮愁合，白雪一声春思长。","满院草花平講席，繞龕藤葉蓋禪牀。","怜師不得隨師去，已戴儒冠事素王。"]', '诗', 'shi', '', NULL, '和浙西從事劉三復送僧南歸 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e3810b3-0ca1-40c8-a8d9-19156b51460a', '送上元王明府赴任', '送上元王明府赴任', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["莫言名重懶驅雞，六代江山碧海西。","日照蒹葭明楚塞，煙分楊柳見隋堤。","荒城樹暗沈書浦，舊宅花連罨畫溪。","官滿定知歸未得，九重霄漢有丹梯。"]', '["莫言名重懶驱雞，六代江山碧海西。","日照蒹葭明楚塞，煙分楊柳见隋堤。","荒城樹暗沈书浦，旧宅花連罨畫溪。","官满定知归未得，九重霄漢有丹梯。"]', '诗', 'shi', '', NULL, '送上元王明府赴任 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a803e904-ec95-442b-b8f3-4477f0c0ee9f', '送沈卓少府任江都', '送沈卓少府任江都', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["煬帝都城春水邊，笙歌夜上木蘭船。","三千宮女自塗地，十萬人家如洞天。","豔豔花枝官舍晚，重重雲影寺牆連。","少年作尉須兢慎，莫向樓前墜馬鞭。"]', '["煬帝都城春水邊，笙歌夜上木蘭船。","三千宮女自塗地，十万人家如洞天。","豔豔花枝官舍晚，重重云影寺牆連。","少年作尉須兢慎，莫向楼前墜马鞭。"]', '诗', 'shi', '', NULL, '送沈卓少府任江都 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ee1895a-17b4-4e66-8377-308dc408d24c', '酬邢杜二員外', '酬邢杜二員外', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["雪帶東風洗畫屏，客星懸處聚文星。","未歸嵩嶺暮雲碧，久別杜陵春草青。","熊軾並驅因雀噪，隼旟齊駐是鴻冥。","豈知京洛舊親友，夢繞潺湲江上亭。"]', '["雪带东风洗畫屏，客星懸处聚文星。","未归嵩嶺暮云碧，久別杜陵春草青。","熊軾並驱因雀噪，隼旟齊駐是鴻冥。","豈知京洛旧親友，梦繞潺湲江上亭。"]', '诗', 'shi', '', NULL, '酬邢杜二員外 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a51dd2a-aa07-4658-9c14-17c686a47e4f', '經故丁補闕郊居', '經故丁補闕郊居', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["死酧知己道終全，波暖孤冰且自堅。","鵩上承塵纔一日，鶴歸華表已千年。","風吹藥蔓迷樵徑，雨暗蘆花失釣船。","四尺孤墳何處是，闔閭城外草連天。"]', '["死酧知己道終全，波暖孤冰且自堅。","鵩上承塵纔一日，鹤归华表已千年。","风吹藥蔓迷樵徑，雨暗蘆花失釣船。","四尺孤墳何处是，闔閭城外草連天。"]', '诗', 'shi', '', NULL, '經故丁補闕郊居 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c17bd85-8502-487c-8bf2-0fb87c33e3b8', '陪宣城大夫崔公泛後池兼北樓讌二首 一', '陪宣城大夫崔公泛後池兼北楼讌二首 一', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["陪汎芳池醉北樓，水花繁豔照膺舟。","亭臺陰合樹初晝，弦管韻高山欲秋。","皆賀虢巖終選傅，自傷燕谷未逢鄒。","昔時恩遇今能否，一尉滄洲已白頭。"]', '["陪汎芳池醉北楼，水花繁豔照膺舟。","亭台陰合樹初晝，弦管韻高山欲秋。","皆賀虢巖終選傅，自傷燕谷未逢鄒。","昔时恩遇今能否，一尉滄洲已白头。"]', '诗', 'shi', '', NULL, '陪宣城大夫崔公泛後池兼北樓讌二首 一 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f47ae2fa-2bc3-488f-8bb8-fd2984a643ed', '陪宣城大夫崔公泛後池兼北樓讌二首 二', '陪宣城大夫崔公泛後池兼北楼讌二首 二', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["江上西來共鳥飛，翦荷浮汎似輕肥。","王珣作簿公曾喜，劉表爲邦客盡依。","雲外軒窗通早景，風前簫鼓送殘暉。","宛陵行樂金陵住，遙對家山未憶歸。"]', '["江上西来共鸟飞，翦荷浮汎似轻肥。","王珣作簿公曾喜，劉表爲邦客尽依。","云外軒窗通早景，风前簫鼓送殘暉。","宛陵行乐金陵住，遙对家山未憶归。"]', '诗', 'shi', '', NULL, '陪宣城大夫崔公泛後池兼北樓讌二首 二 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89694013-f59f-42a4-be7d-d65a14196ccf', '留別趙端公', '留別趙端公', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["海門征櫂赴龍瀧，暫寄華筵倒玉缸。","簫鼓散時逢夜雨，綺羅分處下秋江。","孤帆已過滕王閣，高榻留眠謝守窗。","却願煙波阻風雪，待君同拜碧油幢。"]', '["海门征櫂赴龙瀧，暫寄华筵倒玉缸。","簫鼓散时逢夜雨，綺羅分处下秋江。","孤帆已過滕王閣，高榻留眠謝守窗。","却願煙波阻风雪，待君同拜碧油幢。"]', '诗', 'shi', '', NULL, '留別趙端公 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd6f957f-ee7f-457a-a664-544531da50b1', '寄陽陵處士', '寄陽陵处士', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["舊隱青山紫桂陰，一書迢遰寄歸心。","謝公樓上晚花盛，楊子宅前春草深。","吳岫雨來溪鳥浴，楚江雲暗嶺猨吟。","野人寧憶滄洲畔，會待吹噓定至音。"]', '["旧隐青山紫桂陰，一书迢遰寄归心。","謝公楼上晚花盛，楊子宅前春草深。","吳岫雨来溪鸟浴，楚江云暗嶺猨吟。","野人寧憶滄洲畔，會待吹噓定至音。"]', '诗', 'shi', '', NULL, '寄陽陵處士 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4bfbf60-807d-4b5b-adb3-4850fccec952', '與張道士同訪李隱君不遇', '與張道士同訪李隐君不遇', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["千巖萬壑獨攜琴，知在陵陽不可尋。","去轍已平秋草遍，空齋長掩暮雲深。","霜寒橡栗留山鼠，月冷菰蒲散水禽。","唯有西鄰張仲蔚，坐來同愴別離心。"]', '["千巖万壑独携琴，知在陵陽不可尋。","去轍已平秋草遍，空斋长掩暮云深。","霜寒橡栗留山鼠，月冷菰蒲散水禽。","唯有西鄰張仲蔚，坐来同愴別離心。"]', '诗', 'shi', '', NULL, '與張道士同訪李隱君不遇 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dceaf0ae-da50-421e-8bf2-3f81c53bc475', '聞州中有讌寄崔大夫兼簡邢羣評事', '闻州中有讌寄崔大夫兼簡邢羣評事', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["簫管筵間列翠蛾，玉杯金液耀金波。","池邊雨過飄帷幕，海上風來動綺羅。","顏子巷深青草遍，庾君樓迥碧山多。","甘心不及同年友，臥聽行雲一曲歌。"]', '["簫管筵间列翠蛾，玉杯金液耀金波。","池邊雨過飄帷幕，海上风来动綺羅。","顏子巷深青草遍，庾君楼迥碧山多。","甘心不及同年友，臥听行云一曲歌。"]', '诗', 'shi', '', NULL, '聞州中有讌寄崔大夫兼簡邢羣評事 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a5a14ae-2d4c-4761-8097-c4172980b419', '寄殷堯藩先輩', '寄殷堯藩先輩', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["十載功名翰墨林，爲從知己信浮沈。","青山有雪諳松性，碧落無雲稱鶴心。","帶月獨歸蕭寺遠，翫花頻醉庾樓深。","思君一見如瓊樹，空把新詩盡日吟。"]', '["十載功名翰墨林，爲從知己信浮沈。","青山有雪諳松性，碧落無云稱鹤心。","带月独归蕭寺远，翫花頻醉庾楼深。","思君一见如瓊樹，空把新诗尽日吟。"]', '诗', 'shi', '', NULL, '寄殷堯藩先輩 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ba36582-927b-4654-b37f-d0d2de6cfb3f', '贈河東虞押衙二首 一', '贈河东虞押衙二首 一', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["長劍高歌換素衣，君恩未報不言歸。","舊精鳥篆諳書體，新授龍韜識戰機。","萬里往來征馬瘦，十年離別故人稀。","生平志氣何人見，空上西樓望落暉。"]', '["长劍高歌換素衣，君恩未報不言归。","旧精鸟篆諳书體，新授龙韜識戰機。","万里往来征马瘦，十年離別故人稀。","生平志氣何人见，空上西楼望落暉。"]', '诗', 'shi', '', NULL, '贈河東虞押衙二首 一 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0388111a-99bc-4f44-8ec0-32290cb53e4e', '贈河東虞押衙二首 二', '贈河东虞押衙二首 二', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["吳門風水各萍流，月滿花開懶獨遊。","萬里山川分曉夢，四鄰歌管送春愁。","昔年顧我長青眼，今日逢君盡白頭。","莫向尊前更惆悵，古來投筆盡封侯。"]', '["吳门风水各萍流，月满花开懶独游。","万里山川分晓梦，四鄰歌管送春愁。","昔年顧我长青眼，今日逢君尽白头。","莫向尊前更惆悵，古来投笔尽封侯。"]', '诗', 'shi', '', NULL, '贈河東虞押衙二首 二 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d853097-278c-4891-8a3c-22f39c71b878', '陵陽春日寄汝洛舊游', '陵陽春日寄汝洛旧游', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["百年身世似飄蓬，澤國移家疊嶂中。","萬里綠波魚戀釣，九重青漢鶴愁籠。","西池水冷春巖雪，南浦花香曉樹風。","縱倒芳尊心不醉，故人多在洛城東。"]', '["百年身世似飄蓬，澤国移家叠嶂中。","万里綠波鱼戀釣，九重青漢鹤愁籠。","西池水冷春巖雪，南浦花香晓樹风。","縱倒芳尊心不醉，故人多在洛城东。"]', '诗', 'shi', '', NULL, '陵陽春日寄汝洛舊游 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75340376-04dc-4aaf-860c-86ddadba733c', '酬杜補闕初春雨中舟次橫江喜裴郎中相迎見寄', '酬杜補闕初春雨中舟次橫江喜裴郎中相迎见寄', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["江館維舟爲庾公，暖波微淥雨濛濛。","紅橋迤邐春巖下，朱斾聯翩曉樹中。","柳滴圓波生細浪，梅含香豔吐輕風。","郢歌莫問青山吏，魚在深池鳥在籠。"]', '["江館維舟爲庾公，暖波微淥雨濛濛。","紅橋迤邐春巖下，朱斾聯翩晓樹中。","柳滴圓波生細浪，梅含香豔吐轻风。","郢歌莫问青山吏，鱼在深池鸟在籠。"]', '诗', 'shi', '', NULL, '酬杜補闕初春雨中舟次橫江喜裴郎中相迎見寄 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04f84781-2c74-4eed-a4bc-c10457f14ed9', '送張厚浙東謁丁常侍', '送張厚浙东謁丁常侍', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["涼露清蟬柳陌空，故人遙指浙江東。","青山有雪松當澗，碧落無雲鶴出籠。","齊唱離歌愁晚月，獨看征棹怨秋風。","定知洛下聲名士，共說膺門得孔融。"]', '["涼露清蟬柳陌空，故人遙指浙江东。","青山有雪松當澗，碧落無云鹤出籠。","齊唱離歌愁晚月，独看征棹怨秋风。","定知洛下声名士，共说膺门得孔融。"]', '诗', 'shi', '', NULL, '送張厚浙東謁丁常侍 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8e7bfe1-cce1-4bf8-b300-ae465898f9f5', '酬副使鄭端公見寄', '酬副使鄭端公见寄', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["一日高名遍九州，玄珠仍向道中求。","郢中白雪慙新唱，塗上青山憶舊遊。","笙磬有文終易別，珠璣無價竟難酬。","柳營迢遰江風闊，夜夜孤吟月下樓。"]', '["一日高名遍九州，玄珠仍向道中求。","郢中白雪慙新唱，塗上青山憶旧游。","笙磬有文終易別，珠璣無價竟难酬。","柳營迢遰江风闊，夜夜孤吟月下楼。"]', '诗', 'shi', '', NULL, '酬副使鄭端公見寄 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be64b039-6c88-48d7-9e09-82d13654fceb', '酬綿州于中丞使君見寄', '酬綿州于中丞使君见寄', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["故人書信越襃斜，新意雖多舊約賒。","皆就一麾先去國，共謀三逕未還家。","荆巫夜隔巴西月，鄢郢春連漢上花。","半月離居猶悵望，可堪垂白各天涯。"]', '["故人书信越襃斜，新意雖多旧約賒。","皆就一麾先去国，共謀三逕未還家。","荆巫夜隔巴西月，鄢郢春連漢上花。","半月離居猶悵望，可堪垂白各天涯。"]', '诗', 'shi', '', NULL, '酬綿州于中丞使君見寄 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65d71f2c-3ca3-4972-ba5f-64bd528c3075', '春早郡樓書事寄呈府中羣公', '春早郡楼书事寄呈府中羣公', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["兩鬢垂絲髪半霜，石城孤夢繞襄陽。","鴛鴻幕裏蓮披檻，虎豹營中柳拂牆。","畫舸欲行春水急，翠簾初捲暮山長。","峴亭風起花千片，流入南湖盡日香。"]', '["兩鬢垂絲髪半霜，石城孤梦繞襄陽。","鴛鴻幕裏蓮披檻，虎豹營中柳拂牆。","畫舸欲行春水急，翠簾初捲暮山长。","峴亭风起花千片，流入南湖尽日香。"]', '诗', 'shi', '', NULL, '春早郡樓書事寄呈府中羣公 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de53db97-52bf-48cb-a0d4-340e1e6ba8f1', '元處士自洛歸宛陵山居見示詹事相公餞行之什因贈', '元处士自洛归宛陵山居见示詹事相公餞行之什因贈', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["紫霄峰下絕韋編，舊隱相如結韈前。","月落尚留東閤醉，風高還憶北窗眠。","江城夜別瀟瀟雨，山檻晴歸漠漠煙。","一頃豆花三頃竹，想應拋却釣魚船。"]', '["紫霄峰下絕韋編，旧隐相如結韈前。","月落尚留东閤醉，风高還憶北窗眠。","江城夜別瀟瀟雨，山檻晴归漠漠煙。","一頃豆花三頃竹，想應拋却釣鱼船。"]', '诗', 'shi', '', NULL, '元處士自洛歸宛陵山居見示詹事相公餞行之什因贈 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd74383b-d6a0-421a-ad3b-b7b837b436f4', '送元晝上人歸蘇州兼寄張厚二首 一', '送元晝上人归蘇州兼寄張厚二首 一', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["自卜閑居荆水頭，感時相別思悠悠。","一樽酒盡青山暮，千里書回碧樹秋。","深巷久貧知寂寞，小詩多病尚風流。","晝公此去應相問，爲說沾巾憶舊遊。"]', '["自卜闲居荆水头，感时相別思悠悠。","一樽酒尽青山暮，千里书回碧樹秋。","深巷久貧知寂寞，小诗多病尚风流。","晝公此去應相问，爲说沾巾憶旧游。"]', '诗', 'shi', '', NULL, '送元晝上人歸蘇州兼寄張厚二首 一 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07b44017-861c-4383-9383-6fc6a284e535', '送元晝上人歸蘇州兼寄張厚二首 二', '送元晝上人归蘇州兼寄張厚二首 二', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["三年無事客吳鄉，南陌春園碧草長。","共醉八門回畫舸，獨還三徑掩書堂。","前山雨過池塘滿，小院秋歸枕簟涼。","經歲別離心自苦，何堪黃葉落清漳。"]', '["三年無事客吳乡，南陌春园碧草长。","共醉八门回畫舸，独還三徑掩书堂。","前山雨過池塘满，小院秋归枕簟涼。","經歲別離心自苦，何堪黄葉落清漳。"]', '诗', 'shi', '', NULL, '送元晝上人歸蘇州兼寄張厚二首 二 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73473f8c-8930-4b1b-805e-39058c3e5c45', '送陸拾遺東歸', '送陸拾遺东归', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["獨振儒風遇盛時，紫泥初降世人知。","文章報主非無意，書劍還家素有期。","秋寺臥雲移棹晚，暮江乘月落帆遲。","東歸自是緣清興，莫比商山詠紫芝。"]', '["独振儒风遇盛时，紫泥初降世人知。","文章報主非無意，书劍還家素有期。","秋寺臥云移棹晚，暮江乘月落帆遲。","东归自是緣清兴，莫比商山詠紫芝。"]', '诗', 'shi', '', NULL, '送陸拾遺東歸 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fbfcea6-fdd6-449f-867a-31115ca512f4', '湖南徐明府余之南鄰久不還家因題林館', '湖南徐明府余之南鄰久不還家因題林館', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["湘南官罷不歸來，高閣經年掩綠苔。","魚溢池塘秋雨過，鳥還洲島暮潮回。","階前石穩棋終局，窗外山寒酒滿杯。","借問先生獨何處，一籬疎菊又花開。"]', '["湘南官罷不归来，高閣經年掩綠苔。","鱼溢池塘秋雨過，鸟還洲島暮潮回。","階前石穩棋終局，窗外山寒酒满杯。","借问先生独何处，一籬疎菊又花开。"]', '诗', 'shi', '', NULL, '湖南徐明府余之南鄰久不還家因題林館 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd8a4b00-617e-45d8-8d7a-8254f28c1efd', '酬和杜侍御', '酬和杜侍御', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["花時曾省杜陵遊，聞下書帷不舉頭。","因過石城先訪戴，欲朝金闕暫依劉。","征帆夜轉鸕鷀穴，騁騎春辭鸛雀樓。","正把新詩望南浦，棹歌應是木蘭舟。"]', '["花时曾省杜陵游，闻下书帷不舉头。","因過石城先訪戴，欲朝金闕暫依劉。","征帆夜轉鸕鷀穴，騁騎春辞鸛雀楼。","正把新诗望南浦，棹歌應是木蘭舟。"]', '诗', 'shi', '', NULL, '酬和杜侍御 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d87d9f56-8560-40ae-9a95-1006100f0635', '酬河中杜侍御重寄', '酬河中杜侍御重寄', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["五色如絲下碧空，片帆還遶楚王宮。","文章已變南山霧，羽翼應摶北海風。","春雪預呈霜簡白，曉霞先染繡衣紅。","十千沽酒留君醉，莫道歸心似轉蓬。"]', '["五色如絲下碧空，片帆還遶楚王宮。","文章已变南山霧，羽翼應摶北海风。","春雪預呈霜簡白，晓霞先染繡衣紅。","十千沽酒留君醉，莫道归心似轉蓬。"]', '诗', 'shi', '', NULL, '酬河中杜侍御重寄 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af269292-808a-4710-ac33-0089d4cc4b61', '寄獻三川守劉公 一', '寄獻三川守劉公 一', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["三川歌頌徹咸秦，十二樓前侍從臣。","休閉玉籠留鸑鷟，早開金埒縱麒麟。","花深穉榻迎何客，月在膺舟醉幾人。","自笑東風過寒食，茂陵寥落未知春。"]', '["三川歌頌徹咸秦，十二楼前侍從臣。","休閉玉籠留鸑鷟，早开金埒縱麒麟。","花深穉榻迎何客，月在膺舟醉幾人。","自笑东风過寒食，茂陵寥落未知春。"]', '诗', 'shi', '', NULL, '寄獻三川守劉公 一 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da333783-256b-458a-ad39-0698e596e9ed', '寄獻三川守劉公 二', '寄獻三川守劉公 二', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["半年三度轉蓬居，錦帳心闌羨隼旟。","老去自驚秦塞鴈，病來先憶楚江魚。","長聞季氏千金諾，更望劉公一紙書。","春雪未晴春酒貴，莫教愁殺馬相如。"]', '["半年三度轉蓬居，錦帳心闌羨隼旟。","老去自驚秦塞鴈，病来先憶楚江鱼。","长闻季氏千金諾，更望劉公一紙书。","春雪未晴春酒貴，莫教愁殺马相如。"]', '诗', 'shi', '', NULL, '寄獻三川守劉公 二 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c92f5167-d1af-41bc-b92b-def9a469dcfe', '送段覺之西蜀結婚', '送段覺之西蜀結婚', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["詞賦名高身不閑，綵衣如錦度函關。","鏡中鸞影胡威去，劍外花歸衛玠還。","秋浪遠侵黃鶴嶺，暮雲遙斷碧雞山。","時人若問西遊客，心在重霄鬢欲斑。"]', '["词賦名高身不闲，綵衣如錦度函关。","镜中鸾影胡威去，劍外花归衛玠還。","秋浪远侵黄鹤嶺，暮云遙斷碧雞山。","时人若问西游客，心在重霄鬢欲斑。"]', '诗', 'shi', '', NULL, '送段覺之西蜀結婚 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d990f982-aca7-4915-83bb-72059b45f36a', '長慶寺遇常州阮秀才', '长慶寺遇常州阮秀才', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["高閣晴軒對一峰，毗陵書客此相逢。","晚收紅葉題詩遍，秋待黃花釀酒濃。","山館日斜喧鳥雀，石潭波動戲魚龍。","上方有路應知處，疎磬寒蟬樹幾重。"]', '["高閣晴軒对一峰，毗陵书客此相逢。","晚收紅葉題诗遍，秋待黄花釀酒濃。","山館日斜喧鸟雀，石潭波动戲鱼龙。","上方有路應知处，疎磬寒蟬樹幾重。"]', '诗', 'shi', '', NULL, '長慶寺遇常州阮秀才 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52f5edfc-5afb-47dd-80a6-2aa8e679b3b4', '贈閑師', '贈闲師', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["近日高僧更有誰，宛陵山下遇閑師。","東林共許三乘學，南國爭傳五字詩。","初到庾樓紅葉墜，夜投蕭寺碧雲隨。","秋江莫惜題佳句，正是磷磷見底時。"]', '["近日高僧更有誰，宛陵山下遇闲師。","东林共許三乘学，南国爭傳五字诗。","初到庾楼紅葉墜，夜投蕭寺碧云隨。","秋江莫惜題佳句，正是磷磷见底时。"]', '诗', 'shi', '', NULL, '贈閑師 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15e4cee1-9e6c-4ad7-acae-f21f07320c0c', '東遊留別李叢秀才', '东游留別李叢秀才', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["煩君沽酒強登樓，罷唱離歌說遠遊。","文字豈勞諸子重，風塵多幸故人憂。","數程山路長侵夜，千里家書動隔秋。","起憑欄干各垂淚，又驅羸馬向東州。"]', '["煩君沽酒強登楼，罷唱離歌说远游。","文字豈勞諸子重，风塵多幸故人憂。","數程山路长侵夜，千里家书动隔秋。","起憑欄干各垂泪，又驱羸马向东州。"]', '诗', 'shi', '', NULL, '東遊留別李叢秀才 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4df33db-e607-485e-bde9-902e47857293', '竹林寺別友人', '竹林寺別友人', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["騷人吟罷起鄉愁，暗覺年華似水流。","花滿謝城傷共別，蟬鳴蕭寺喜同遊。","前山月落杉松晚，深夜風清枕簟秋。","明日分襟又何處，江南江北路悠悠。"]', '["騷人吟罷起乡愁，暗覺年华似水流。","花满謝城傷共別，蟬鳴蕭寺喜同游。","前山月落杉松晚，深夜风清枕簟秋。","明日分襟又何处，江南江北路悠悠。"]', '诗', 'shi', '', NULL, '竹林寺別友人 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60303547-3ae7-4608-9fbd-7a2b1d3d7c71', '送處士武君歸章洪山居', '送处士武君归章洪山居', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["形影無羣消息沈，登聞三擊血沾襟。","皇綱一日開冤氣，青史千年重壯心。","却望烏臺春樹老，獨歸蝸舍暮雲深。","他時縱有徵書至，雪滿空山不可尋。"]', '["形影無羣消息沈，登闻三擊血沾襟。","皇綱一日开冤氣，青史千年重壯心。","却望烏台春樹老，独归蝸舍暮云深。","他时縱有徵书至，雪满空山不可尋。"]', '诗', 'shi', '', NULL, '送處士武君歸章洪山居 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee56e25b-e97d-4a94-9116-0c3a74a42fa9', '題義女亭', '題義女亭', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["身沒蘭閨道日明，郭南尋得舊池亭。","詩人愁立暮山碧，賈客怨離秋草青。","四望月沈疑掩鏡，兩簷花動認收屏。","至今鄉里風猶在，借問誰傳義女銘。"]', '["身沒蘭閨道日明，郭南尋得旧池亭。","诗人愁立暮山碧，賈客怨離秋草青。","四望月沈疑掩镜，兩簷花动認收屏。","至今乡里风猶在，借问誰傳義女銘。"]', '诗', 'shi', '', NULL, '題義女亭 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2635058f-3712-485b-a8bb-37b01a193cd6', '吳門送振武李從事', '吳门送振武李從事', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["晚促離筵醉玉缸，伊州一曲淚雙雙。","欲攜刀筆從新幕，更宿烟霞別舊窗。","胡馬近秋侵紫塞，吳帆乘月下清江。","嫖姚若許傳書檄，坐築三城看受降。"]', '["晚促離筵醉玉缸，伊州一曲泪雙雙。","欲携刀笔從新幕，更宿烟霞別旧窗。","胡马近秋侵紫塞，吳帆乘月下清江。","嫖姚若許傳书檄，坐築三城看受降。"]', '诗', 'shi', '', NULL, '吳門送振武李從事 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61eb02b7-0955-41f3-8e89-99739cd129db', '郊居春日有懷府中諸公幷柬王兵曹', '郊居春日有懷府中諸公幷柬王兵曹', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["欲學漁翁釣艇新，濯纓猶惜九衢塵。","花前更謝依劉客，雪後空懷訪戴人。","僧舍覆碁消白日，市樓賒酒過青春。","一山桃杏同時發，誰似東風不厭貧。"]', '["欲学漁翁釣艇新，濯纓猶惜九衢塵。","花前更謝依劉客，雪後空懷訪戴人。","僧舍覆碁消白日，市楼賒酒過青春。","一山桃杏同时發，誰似东风不厭貧。"]', '诗', 'shi', '', NULL, '郊居春日有懷府中諸公幷柬王兵曹 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89735a19-c227-4556-84fe-71599e1eef96', '同韋少尹傷故衛尉李少卿', '同韋少尹傷故衛尉李少卿', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["客醉更長樂未窮，似知身世一宵空。","香街寶馬嘶殘月，暖閣佳人哭曉風。","未捲繡筵朱閣上，已開塵席畫屏中。","何須更賦山陽笛，寒月沈西水向東。"]', '["客醉更长乐未窮，似知身世一宵空。","香街寶马嘶殘月，暖閣佳人哭晓风。","未捲繡筵朱閣上，已开塵席畫屏中。","何須更賦山陽笛，寒月沈西水向东。"]', '诗', 'shi', '', NULL, '同韋少尹傷故衛尉李少卿 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('992ae4d9-15a2-4f55-99ca-43d93875e85e', '舟行早發廬陵郡郭寄滕郎中', '舟行早發廬陵郡郭寄滕郎中', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["楚客停橈太守知，露凝丹葉自秋悲。","蟹螯只恐相如渴，鱸鱠應防曼倩飢。","風捲曙雲飄角遠，雨昏寒浪挂帆遲。","離心更羨高齋夕，巫峽花深醉玉巵。"]', '["楚客停橈太守知，露凝丹葉自秋悲。","蟹螯只恐相如渴，鱸鱠應防曼倩飢。","风捲曙云飄角远，雨昏寒浪挂帆遲。","離心更羨高斋夕，巫峽花深醉玉巵。"]', '诗', 'shi', '', NULL, '舟行早發廬陵郡郭寄滕郎中 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81548238-fab4-4640-a71c-77249bd3bd0a', '聞邊將劉臯無辜受戮', '闻邊將劉臯無辜受戮', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["外監多假帝王尊，威脅偏裨勢不存。","纔許誓心安玉壘，已傷傳首動金門。","三千客裏寧無義，五百人中必有恩。","却賴漢庭多烈士，至今猶自伏蒲輪。"]', '["外監多假帝王尊，威脅偏裨勢不存。","纔許誓心安玉壘，已傷傳首动金门。","三千客裏寧無義，五百人中必有恩。","却賴漢庭多烈士，至今猶自伏蒲輪。"]', '诗', 'shi', '', NULL, '聞邊將劉臯無辜受戮 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adacb016-80c1-43ec-8438-9bd8610aa4e6', '送薛秀才南遊', '送薛秀才南游', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["姑蘇城外柳初凋，同上江樓更寂寥。","遶壁舊詩塵漠漠，對窗寒竹雨瀟瀟。","憐君別路隨秋鴈，盡我離觴任晚潮。","從此草玄應有處，白雲青嶂一相招。"]', '["姑蘇城外柳初凋，同上江楼更寂寥。","遶壁旧诗塵漠漠，对窗寒竹雨瀟瀟。","怜君別路隨秋鴈，尽我離觴任晚潮。","從此草玄應有处，白云青嶂一相招。"]', '诗', 'shi', '', NULL, '送薛秀才南遊 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('280875c7-9ec4-4d0e-9022-ecf6b1d67705', '夜歸孤山寺却寄盧郎中', '夜归孤山寺却寄盧郎中', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["青山有志路猶賒，心在琴書自憶家。","醉別庾樓山色曉，夜歸蕭寺月光斜。","落帆露濕回塘柳，別院風驚滿地花。","他日此身須報德，莫言空愛舊烟霞。"]', '["青山有志路猶賒，心在琴书自憶家。","醉別庾楼山色晓，夜归蕭寺月光斜。","落帆露濕回塘柳，別院风驚满地花。","他日此身須報德，莫言空愛旧烟霞。"]', '诗', 'shi', '', NULL, '夜歸孤山寺却寄盧郎中 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a770979-4299-46a7-8b87-cbf54e2de6a9', '贈桐廬房明府先輩', '贈桐廬房明府先輩', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["帝城春榜謫靈仙，四海聲華二十年。","闕下書功無後輩，卷中文字掩前賢。","官閑每喜江山靜，道在寧憂雨露偏。","自笑小儒非一鶚，亦趨門屏冀相憐。"]', '["帝城春榜謫靈仙，四海声华二十年。","闕下书功無後輩，卷中文字掩前賢。","官闲每喜江山静，道在寧憂雨露偏。","自笑小儒非一鶚，亦趨门屏冀相怜。"]', '诗', 'shi', '', NULL, '贈桐廬房明府先輩 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79551141-ba7a-4174-afa9-11ec1fb2ae79', '甘露寺感事貽同志', '甘露寺感事貽同志', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["雲蔽長安路更賒，獨隨漁艇老天涯。","青山盡日尋黃絹，滄海經年夢絳紗。","雪憤有期心自壯，報恩無處髪先華。","東堂舊侶勤書劍，同出膺門是一家。"]', '["云蔽长安路更賒，独隨漁艇老天涯。","青山尽日尋黄絹，滄海經年梦絳紗。","雪憤有期心自壯，報恩無处髪先华。","东堂旧侶勤书劍，同出膺门是一家。"]', '诗', 'shi', '', NULL, '甘露寺感事貽同志 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e30479e-6de0-492f-8b8b-60cb82165ffd', '泛溪夜回寄道玄上人', '泛溪夜回寄道玄上人', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["南郭煙光異世間，碧桃紅杏水潺潺。","猨來近嶺獼猴散，魚下深潭翡翠閑。","猶阻晚風停桂檝，欲乘春月訪松關。","幾回策杖終難去，洞口雲歸不見山。"]', '["南郭煙光異世间，碧桃紅杏水潺潺。","猨来近嶺獼猴散，鱼下深潭翡翠闲。","猶阻晚风停桂檝，欲乘春月訪松关。","幾回策杖終难去，洞口云归不见山。"]', '诗', 'shi', '', NULL, '泛溪夜回寄道玄上人 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a24e4a8-7235-4b12-a713-4cb2d40e2cc4', '客至', '客至', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["得路逢津更俊才，可憐鞍馬照春來。","殘花幾日小齋閉，大笑一聲幽抱開。","袖拂碧溪寒繚繞，冠欹紅樹晚徘徊。","相逢少別更堪恨，何必秋風江上臺。"]', '["得路逢津更俊才，可怜鞍马照春来。","殘花幾日小斋閉，大笑一声幽抱开。","袖拂碧溪寒繚繞，冠欹紅樹晚徘徊。","相逢少別更堪恨，何必秋风江上台。"]', '诗', 'shi', '', NULL, '客至 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de60a434-7a6c-427d-b25e-5973eaf337c7', '經李給事舊居', '經李給事旧居', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["歸作儒翁出致君，故山誰復有遺文。","漢庭使氣摧張禹，楚國懷憂送范雲。","楓葉暗時迷舊宅，芳花落處認荒墳。","朱弦一奏沈湘怨，風起寒波日欲曛。"]', '["归作儒翁出致君，故山誰复有遺文。","漢庭使氣摧張禹，楚国懷憂送范云。","楓葉暗时迷旧宅，芳花落处認荒墳。","朱弦一奏沈湘怨，风起寒波日欲曛。"]', '诗', 'shi', '', NULL, '經李給事舊居 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b38e04f-ff49-45ee-8d98-246067381473', '新興道中', '新兴道中', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["芙蓉村步失官金，折獄無功不可尋。","初挂海帆逢歲暮，却開山館值春深。","波渾未辨魚龍跡，霧暗寧知蚌鷸心。","夜榜歸舟望漁火，一溪風雨兩巖陰。"]', '["芙蓉村步失官金，折獄無功不可尋。","初挂海帆逢歲暮，却开山館值春深。","波渾未辨鱼龙跡，霧暗寧知蚌鷸心。","夜榜归舟望漁火，一溪风雨兩巖陰。"]', '诗', 'shi', '', NULL, '新興道中 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b462969-fc43-4e39-aee8-df9671c0312c', '下第有懷親友', '下第有懷親友', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["萬山晴雪九衢塵，何處風光寄夢頻？","花盛庾園攜酒客，草深顏巷讀書人。","征帆又過湘南月，旅館還悲渭水春。","無限別情多病後，杜陵寥落在漳濱。"]', '["万山晴雪九衢塵，何处风光寄梦頻？","花盛庾园携酒客，草深顏巷读书人。","征帆又過湘南月，旅館還悲渭水春。","無限別情多病後，杜陵寥落在漳濱。"]', '诗', 'shi', '', NULL, '下第有懷親友 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('545dc6a4-3260-4440-b04d-d784288f4c7d', '中秋夕寄大梁劉尚書', '中秋夕寄大梁劉尚书', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["汴人迎拜洛人留，虎豹旌旗擁碧油。","[刁]斗嚴更軍耳目，戈鋋長控國咽喉。","柳營出號風生纛，蓮幕題詩月上樓。","應念散郎千里外，去年今夜醉蘭舟。"]', '["汴人迎拜洛人留，虎豹旌旗擁碧油。","[刁]斗嚴更軍耳目，戈鋋长控国咽喉。","柳營出號风生纛，蓮幕題诗月上楼。","應念散郎千里外，去年今夜醉蘭舟。"]', '诗', 'shi', '', NULL, '中秋夕寄大梁劉尚書 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b012a42-9286-4620-9602-ba1231af33e6', '臥病', '臥病', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["寒窗燈盡月斜暉，珮馬朝天獨掩扉。","清露已凋秦塞柳，白雲空長越山薇。","病中送客難爲別，夢裏還家不當歸。","惟有寄書書未得，臥聞燕鴈向南飛。"]', '["寒窗灯尽月斜暉，珮马朝天独掩扉。","清露已凋秦塞柳，白云空长越山薇。","病中送客难爲別，梦裏還家不當归。","惟有寄书书未得，臥闻燕鴈向南飞。"]', '诗', 'shi', '', NULL, '臥病 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f0d2f08-f56e-44e7-b169-9db09f396aa6', '殘雪', '殘雪', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["憶昨新春霰雪飛，堦前簷上鬬寒姿。","狂風送在竹深處，隔日未消花發時。","輕壓嫩蔬旁出土，冷衝幽鳥別尋枝。","晚來又喜登樓見，一曲高歌和者誰。"]', '["憶昨新春霰雪飞，堦前簷上鬬寒姿。","狂风送在竹深处，隔日未消花發时。","轻壓嫩蔬旁出土，冷衝幽鸟別尋枝。","晚来又喜登楼见，一曲高歌和者誰。"]', '诗', 'shi', '', NULL, '殘雪 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e4c7b5b-286c-4a4c-b41c-28f01f9854fd', '和常秀才寄簡歸州鄭使君借猨', '和常秀才寄簡归州鄭使君借猨', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["謝守攜猨東路長，褭藤穿竹似瀟湘。","碧山初鳴嘯秋月，紅樹生寒啼曉霜。","陌上楚人皆駐馬，里中巴客半歸鄉。","心知欲借南遊侶，未到三聲恐斷腸。"]', '["謝守携猨东路长，褭藤穿竹似瀟湘。","碧山初鳴嘯秋月，紅樹生寒啼晓霜。","陌上楚人皆駐马，里中巴客半归乡。","心知欲借南游侶，未到三声恐斷腸。"]', '诗', 'shi', '', NULL, '和常秀才寄簡歸州鄭使君借猨 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab08dd28-14cb-4e19-ad5c-5ee1475cc0f6', '送人之任邛州', '送人之任邛州', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["綠髮監州丹府歸，還家樂事我先知。","羣童竹馬交迎日，二老蘭觴初見時。","黃卷新書芸委積，青山舊路菊離披。","亨衢自有橫飛勢，便到西垣視訓辭。"]', '["綠髮監州丹府归，還家乐事我先知。","羣童竹马交迎日，二老蘭觴初见时。","黄卷新书芸委積，青山旧路菊離披。","亨衢自有橫飞勢，便到西垣視訓辞。"]', '诗', 'shi', '', NULL, '送人之任邛州 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ed89f0f-c3ef-4368-b2ab-41a6e0dbb6a2', '和河南楊少尹奉陪薛司空石笋詩', '和河南楊少尹奉陪薛司空石笋诗', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["暖溪寒井碧巖前，謝傅賓朋盛綺筵。","雲斷石峰高竝笋，日臨山勢遠開蓮。","閑留幢節低春水，醉擁笙歌出暮煙。","聞道詩成歸已夕，柳風花露月初圓。"]', '["暖溪寒井碧巖前，謝傅賓朋盛綺筵。","云斷石峰高竝笋，日臨山勢远开蓮。","闲留幢節低春水，醉擁笙歌出暮煙。","闻道诗成归已夕，柳风花露月初圓。"]', '诗', 'shi', '', NULL, '和河南楊少尹奉陪薛司空石笋詩 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2779e5d-a0ee-4d06-8e64-39ab4d5d6b40', '獻鄜坊丘常侍', '獻鄜坊丘常侍', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["詔選將軍護北戎，身騎白馬臂彤弓。","柳營遠識金貂貴，榆塞遙知玉帳雄。","秋檻鼓鼙驚朔雪，曉階旗纛起邊風。","蓬萊每望平安火，應奏班超定遠功。"]', '["詔選將軍護北戎，身騎白马臂彤弓。","柳營远識金貂貴，榆塞遙知玉帳雄。","秋檻鼓鼙驚朔雪，晓階旗纛起邊风。","蓬萊每望平安火，應奏班超定远功。"]', '诗', 'shi', '', NULL, '獻鄜坊丘常侍 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb9a55e7-9256-4677-b699-ba051b47b4ff', '寄當塗李遠', '寄當塗李远', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["賦擬相如詩似陶，雲陽烟月又同袍。","車前驥病駑駘逸，架上鷹閑鳥雀高。","舊日樂貧能飲水，他時隨俗願餔糟。","不須倚向青山住，詠雪題詩用意勞。"]', '["賦擬相如诗似陶，云陽烟月又同袍。","车前驥病駑駘逸，架上鷹闲鸟雀高。","旧日乐貧能饮水，他时隨俗願餔糟。","不須倚向青山住，詠雪題诗用意勞。"]', '诗', 'shi', '', NULL, '寄當塗李遠 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b44675aa-e4ad-4035-a190-bf500f535e59', '和崔大夫新廣北樓登眺', '和崔大夫新廣北楼登眺', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["北望高樓夏亦寒，山重水闊接長安。","修梁暗換丹楹小，疎牖全開彩檻寬。","風卷浮雲披睥睨，露涼明月墜闌干。","庾公戀闕懷鄉處，目送歸帆下遠灘。"]', '["北望高楼夏亦寒，山重水闊接长安。","修梁暗換丹楹小，疎牖全开彩檻寬。","风卷浮云披睥睨，露涼明月墜闌干。","庾公戀闕懷乡处，目送归帆下远灘。"]', '诗', 'shi', '', NULL, '和崔大夫新廣北樓登眺 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5cf9d4c-ef1c-4735-a1f6-8874a0363147', '送客自兩河歸江南', '送客自兩河归江南', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["兩河庶事已堪傷，南客秋歸路更長。","臺畔古松悲魏帝，苑邊脩竹弔梁王。","山行露變茱萸色，水宿風披菡萏香。","遙羨落帆逢舊友，綠蛾青鬢醉橫塘。"]', '["兩河庶事已堪傷，南客秋归路更长。","台畔古松悲魏帝，苑邊脩竹弔梁王。","山行露变茱萸色，水宿风披菡萏香。","遙羨落帆逢旧友，綠蛾青鬢醉橫塘。"]', '诗', 'shi', '', NULL, '送客自兩河歸江南 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c6d9217-b2f8-48f5-afab-b3a225323e4e', '題陸侍御林亭', '題陸侍御林亭', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["野水通池石疊臺，五營無事隱雄才。","松齋下馬書千卷，蘭舫逢人酒一杯。","寒樹雪晴紅豔吐，遠山雲曉翠光來。","定知別後無多日，海柳江花次第開。"]', '["野水通池石叠台，五營無事隐雄才。","松斋下马书千卷，蘭舫逢人酒一杯。","寒樹雪晴紅豔吐，远山云晓翠光来。","定知別後無多日，海柳江花次第开。"]', '诗', 'shi', '', NULL, '題陸侍御林亭 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5c75d33-b0b2-4295-81e9-8a7504ac0b0b', '泊蒜山津聞東林寺光儀上人物故', '泊蒜山津闻东林寺光儀上人物故', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["雲齋曾宿借方袍，因說浮生大夢勞。","言下是非齊虎尾，宿來榮辱比鴻毛。","孤舟千棹水猶闊，寒殿一燈夜更高。","明日東林有誰在，不堪秋磬拂煙濤。"]', '["云斋曾宿借方袍，因说浮生大梦勞。","言下是非齊虎尾，宿来榮辱比鴻毛。","孤舟千棹水猶闊，寒殿一灯夜更高。","明日东林有誰在，不堪秋磬拂煙濤。"]', '诗', 'shi', '', NULL, '泊蒜山津聞東林寺光儀上人物故 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd72a57b-767f-40ec-aa38-6acc90c327d4', '春日思舊遊寄南徐從事劉三復', '春日思旧游寄南徐從事劉三复', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["風暖曲江花半開，忽思京口共銜杯。","湘潭雲盡暮山出，巴蜀雪消春水來。","懷玉尚悲迷楚塞，捧金猶羨樂燕臺。","薊門高處極歸思，隴鴈北飛雙燕迴。"]', '["风暖曲江花半开，忽思京口共銜杯。","湘潭云尽暮山出，巴蜀雪消春水来。","懷玉尚悲迷楚塞，捧金猶羨乐燕台。","薊门高处極归思，隴鴈北飞雙燕迴。"]', '诗', 'shi', '', NULL, '春日思舊遊寄南徐從事劉三復 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('498ff761-8d92-40ec-9438-b74ceaed7b4b', '郊園秋日寄洛中友人', '郊园秋日寄洛中友人', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["楚水西來天際流，感時傷別思悠悠。","一尊酒盡青山莫，萬里書迴碧樹秋。","日落遠波驚宿鴈，風吹輕浪起眠鷗。","嵩陽親友如相問，潘岳閑居欲白頭。"]', '["楚水西来天際流，感时傷別思悠悠。","一尊酒尽青山莫，万里书迴碧樹秋。","日落远波驚宿鴈，风吹轻浪起眠鷗。","嵩陽親友如相问，潘岳闲居欲白头。"]', '诗', 'shi', '', NULL, '郊園秋日寄洛中友人 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a75c701-e7ec-453d-97dd-ba70181e07b5', '送杜秀才歸桂林', '送杜秀才归桂林', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["桂州南去與誰同，處處山連水自通。","兩岸曉霞千里草，半帆斜日一江風。","瘴雨欲來楓樹黑，火雲初起荔枝紅。","愁君路遠銷年月，莫滯三湘五嶺中。"]', '["桂州南去與誰同，处处山連水自通。","兩岸晓霞千里草，半帆斜日一江风。","瘴雨欲来楓樹黑，火云初起荔枝紅。","愁君路远銷年月，莫滯三湘五嶺中。"]', '诗', 'shi', '', NULL, '送杜秀才歸桂林 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a96ae6b8-8c3a-4218-b457-b8b777d1ad26', '春雨舟中次和橫江裴使君見迎李趙二秀才同來因書四韻兼寄江南', '春雨舟中次和橫江裴使君见迎李趙二秀才同来因书四韻兼寄江南', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["芳草渡頭微雨時，萬株楊柳拂波垂。","蒲根水暖鴈初落，梅徑香寒蜂未知。","詞客倚風吹暗淡，使君迴馬濕旌旗。","江南仲蔚多情調，悵望青雲幾首詩。"]', '["芳草渡头微雨时，万株楊柳拂波垂。","蒲根水暖鴈初落，梅徑香寒蜂未知。","词客倚风吹暗淡，使君迴马濕旌旗。","江南仲蔚多情調，悵望青云幾首诗。"]', '诗', 'shi', '', NULL, '春雨舟中次和橫江裴使君見迎李趙二秀才同來因書四韻兼寄江南 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('471078c4-1f0a-4335-beef-82ed33e0b5c4', '東陵赴京道病東歸寓居開元寺寄盧員外宋魏二先輩', '东陵赴京道病东归寓居开元寺寄盧員外宋魏二先輩', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["西風吹雨鴈初時，病寄僧齋罷獻書。","萬里咸秦勞我馬，四鄰松桂憶吾廬。","滄洲有約心還靜，青漢無媒跡自疎。","不是醉眠愁不散，莫言琴酒學相如。"]', '["西风吹雨鴈初时，病寄僧斋罷獻书。","万里咸秦勞我马，四鄰松桂憶吾廬。","滄洲有約心還静，青漢無媒跡自疎。","不是醉眠愁不散，莫言琴酒学相如。"]', '诗', 'shi', '', NULL, '東陵赴京道病東歸寓居開元寺寄盧員外宋魏二先輩 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('800459a9-3b15-4c28-bd7d-a4f0cbef09b7', '聞開江宋相公申錫下世二首 一', '闻开江宋相公申錫下世二首 一', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["權門陰奏奪移才，馹騎如星墮峽來。","鼂氏有恩忠作禍，賈生無罪直爲災。","貞魂誤向崇山歿，冤氣疑從汩水回。","畢竟功成何處是，五湖雲月一帆開。"]', '["權门陰奏奪移才，馹騎如星墮峽来。","鼂氏有恩忠作禍，賈生無罪直爲災。","貞魂誤向崇山歿，冤氣疑從汩水回。","畢竟功成何处是，五湖云月一帆开。"]', '诗', 'shi', '', NULL, '聞開江宋相公申錫下世二首 一 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcb6cff0-b9dc-468c-bd3c-68207cd2f7cc', '聞開江宋相公申錫下世二首 二', '闻开江宋相公申錫下世二首 二', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["月落湘潭棹不喧，玉杯瑤瑟奠蘋蘩。","誰能力制乘時鶴，自取機沈在檻猨。","位極乾坤三事貴，謗興華夏一夫冤。","宵衣旰食明天子，日伏青蒲不敢言。"]', '["月落湘潭棹不喧，玉杯瑤瑟奠蘋蘩。","誰能力制乘时鹤，自取機沈在檻猨。","位極乾坤三事貴，謗兴华夏一夫冤。","宵衣旰食明天子，日伏青蒲不敢言。"]', '诗', 'shi', '', NULL, '聞開江宋相公申錫下世二首 二 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47020bcc-b367-4b8d-9f4c-ef4d92311916', '贈所知', '贈所知', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["因釣鱸魚住淛河，挂帆千里亦相過。","茅簷夜醉平階月，蘭棹春歸拍岸波。","湖日似陰鼉鼓響，海雲纔起蜃樓多。","明時又作閑居賦，誰薦東門策四科。"]', '["因釣鱸鱼住淛河，挂帆千里亦相過。","茅簷夜醉平階月，蘭棹春归拍岸波。","湖日似陰鼉鼓响，海云纔起蜃楼多。","明时又作闲居賦，誰薦东门策四科。"]', '诗', 'shi', '', NULL, '贈所知 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5158f1e-b1fe-4b53-b379-792967a9cb44', '謝人贈鞭', '謝人贈鞭', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["蜀國名鞭見惠稀，駑駘從此長光輝。","獨根擁腫來雲岫，紫陌提攜在繡衣。","幾度拂花香裏過，也曾敲𩍐月中歸。","莫言三尺長無用，百萬軍中要指揮。"]', '["蜀国名鞭见惠稀，駑駘從此长光輝。","独根擁腫来云岫，紫陌提携在繡衣。","幾度拂花香裏過，也曾敲𩍐月中归。","莫言三尺长無用，百万軍中要指揮。"]', '诗', 'shi', '', NULL, '謝人贈鞭 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d19937e9-56ce-4e0f-9744-5899a8d73a20', '早秋寄劉尚書', '早秋寄劉尚书', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["天生心識富人侯，將相門中第一流。","旗纛早開擒虎帳，戈[鋋]初發斬鯨舟。","柳營書號海山暝，菌閣賦詩江樹秋。","昨夜雨涼今夜月，笙歌應醉最高樓。"]', '["天生心識富人侯，將相门中第一流。","旗纛早开擒虎帳，戈[鋋]初發斬鯨舟。","柳營书號海山暝，菌閣賦诗江樹秋。","昨夜雨涼今夜月，笙歌應醉最高楼。"]', '诗', 'shi', '', NULL, '早秋寄劉尚書 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc1d76f5-fac3-4c38-859c-18c33f071b7e', '及第後春情', '及第後春情', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["世間得意是春風，散誕經過觸處通。","細搖柳臉牽長帶，慢撼桃株舞碎紅。","也從吹幌驚殘夢，何處飄香別故叢？","猶以西都名下客，今年一月始相逢。"]', '["世间得意是春风，散誕經過觸处通。","細搖柳臉牽长带，慢撼桃株舞碎紅。","也從吹幌驚殘梦，何处飄香別故叢？","猶以西都名下客，今年一月始相逢。"]', '诗', 'shi', '', NULL, '及第後春情 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56db2c39-3151-46eb-979b-bc83bda14daf', '歸長安', '归长安', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["三年何處淚汍瀾，白帝城邊曉角殘。","非是無心戀巫峽，自緣□臂到長安。","黔江水暖還曾飲，楚岫雲深不識寒。","大抵莫教聞雨後，此時腸斷不應難。"]', '["三年何处泪汍瀾，白帝城邊晓角殘。","非是無心戀巫峽，自緣□臂到长安。","黔江水暖還曾饮，楚岫云深不識寒。","大抵莫教闻雨後，此时腸斷不應难。"]', '诗', 'shi', '', NULL, '歸長安 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65ea21f5-cf90-4931-8ba0-edf0b1a9e8ba', '經古行宮', '經古行宮', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["臺閣參差倚太陽，年年花發滿山香。","重門堪鎖青春晚，深院垂簾白晝長。","草色芊綿侵御路，泉聲嗚咽繞宮牆。","先皇一去無迴駕，紅粉雲鬟空斷腸。"]', '["台閣參差倚太陽，年年花發满山香。","重门堪鎖青春晚，深院垂簾白晝长。","草色芊綿侵御路，泉声嗚咽繞宮牆。","先皇一去無迴駕，紅粉云鬟空斷腸。"]', '诗', 'shi', '', NULL, '經古行宮 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbc7e327-1e4e-497e-8287-020b100770ed', '秋晚懷茅山石涵村舍', '秋晚懷茅山石涵村舍', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["十畝山田近石涵，村居風俗舊曾諳。","簾前白艾驚春燕，籬上青桑待晚蠶。","雲暖採茶來嶺北，月明沽酒過溪南。","陵陽秋盡多歸思，紅樹蕭蕭覆碧潭。"]', '["十畝山田近石涵，村居风俗旧曾諳。","簾前白艾驚春燕，籬上青桑待晚蠶。","云暖採茶来嶺北，月明沽酒過溪南。","陵陽秋尽多归思，紅樹蕭蕭覆碧潭。"]', '诗', 'shi', '', NULL, '秋晚懷茅山石涵村舍 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcee5cb9-8093-4ec0-ad9c-53cfcc717292', '貴游', '貴游', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["朝回佩馬早淒淒，年少恩深衛霍齊。","斧鉞舊威龍塞北，池臺新賜鳳城西。","門通碧樹開金鎖，樓對青山倚玉梯。","南陌行人盡回首，笙歌一曲暮雲低。"]', '["朝回佩马早淒淒，年少恩深衛霍齊。","斧鉞旧威龙塞北，池台新賜鳳城西。","门通碧樹开金鎖，楼对青山倚玉梯。","南陌行人尽回首，笙歌一曲暮云低。"]', '诗', 'shi', '', NULL, '貴游 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('243bebda-5020-47a7-ba9f-80d46e1ea847', '贈別', '贈別', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["眼前迎送不曾休，相續輪蹄似水流。","門外若無南北路，人間應免別離愁。","蘇秦六印歸何日，潘岳雙毛去值秋。","莫怪分襟銜淚語，十年耕釣憶滄洲。"]', '["眼前迎送不曾休，相續輪蹄似水流。","门外若無南北路，人间應免別離愁。","蘇秦六印归何日，潘岳雙毛去值秋。","莫怪分襟銜泪語，十年耕釣憶滄洲。"]', '诗', 'shi', '', NULL, '贈別 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d654c12-b466-4236-86fd-ea22bc62f0b7', '秋夜與友人宿', '秋夜與友人宿', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["楚國同游過十霜，萬重心事幾堪傷。","蒹葭露白蓮塘淺，砧杵夜清河漢涼。","雲外山川歸夢遠，天涯岐路客愁長。","塞城欲曉聞吹笛，猶臥東軒月滿牀。"]', '["楚国同游過十霜，万重心事幾堪傷。","蒹葭露白蓮塘淺，砧杵夜清河漢涼。","云外山川归梦远，天涯岐路客愁长。","塞城欲晓闻吹笛，猶臥东軒月满牀。"]', '诗', 'shi', '', NULL, '秋夜與友人宿 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76f35975-4f72-491f-a6a2-4deaf25a9439', '將赴京留贈僧院', '將赴京留贈僧院', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["九衢塵土遞追攀，馬跡軒車日暮間。","玄髪盡驚爲客換，白頭曾見幾人閑。","空悲浮世雲無定，多感流年水不還。","謝却從前受恩地，歸來依止叩禪關。"]', '["九衢塵土遞追攀，马跡軒车日暮间。","玄髪尽驚爲客換，白头曾见幾人闲。","空悲浮世云無定，多感流年水不還。","謝却從前受恩地，归来依止叩禪关。"]', '诗', 'shi', '', NULL, '將赴京留贈僧院 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd9871b5-c027-48b8-8617-e9dc38134f92', '寄湘中友人', '寄湘中友人', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["莫戀醉鄉迷酒杯，流年長怕老年催。","西陵水闊魚難到，南國路遙書未回。","匹馬計程愁日盡，一蟬何事引秋來。","相如已定題橋志，江上無由夢釣臺。"]', '["莫戀醉乡迷酒杯，流年长怕老年催。","西陵水闊鱼难到，南国路遙书未回。","匹马計程愁日尽，一蟬何事引秋来。","相如已定題橋志，江上無由梦釣台。"]', '诗', 'shi', '', NULL, '寄湘中友人 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('194bda4e-ebea-47c6-ad2d-52f6e72f5ae4', '江上逢友人', '江上逢友人', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["故國歸人酒一杯，暫停蘭棹共徘徊。","村連三峽暮雲起，潮送九江寒雨來。","已作相如投賦計，還憑殷浩寄書回。","到時若見東籬菊，爲問經霜幾度開。"]', '["故国归人酒一杯，暫停蘭棹共徘徊。","村連三峽暮云起，潮送九江寒雨来。","已作相如投賦計，還憑殷浩寄书回。","到时若见东籬菊，爲问經霜幾度开。"]', '诗', 'shi', '', NULL, '江上逢友人 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74cf74fc-2b58-4a5f-97bb-0a38dcb3f446', '金谷懷古', '金谷懷古', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["淒涼遺跡洛川東，浮世榮枯萬古同。","桃李香銷金谷在，綺羅魂斷玉樓空。","往年人事傷心外，今日風光屬夢中。","□□□□□□□，□□□□□□□。"]', '["淒涼遺跡洛川东，浮世榮枯万古同。","桃李香銷金谷在，綺羅魂斷玉楼空。","往年人事傷心外，今日风光屬梦中。","□□□□□□□，□□□□□□□。"]', '诗', 'shi', '', NULL, '金谷懷古 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6928b5f1-e683-406d-8c61-7ef93fce7090', '經行廬山東林寺', '經行廬山东林寺', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["離魂斷續楚江壖，葉墜初紅十月天。","紫陌事多難數悉，青山長在好閑眠。","方趨上國期干祿，未得空堂學坐禪。","他歲若教如范蠡，也應須入五湖煙。"]', '["離魂斷續楚江壖，葉墜初紅十月天。","紫陌事多难數悉，青山长在好闲眠。","方趨上国期干祿，未得空堂学坐禪。","他歲若教如范蠡，也應須入五湖煙。"]', '诗', 'shi', '', NULL, '經行廬山東林寺 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3c5e473-825c-484a-8074-18a549f9ec29', '途中逢故人話西山讀書早曾游覽', '途中逢故人話西山读书早曾游覽', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["西巖曾到讀書堂，穿竹行沙十里強。","湖上夢餘波灩灩，嶺頭愁斷路茫茫。","經過事寄煙霞遠，名利塵隨日月長。","莫道少年頭不白，君看潘岳幾莖霜。"]', '["西巖曾到读书堂，穿竹行沙十里強。","湖上梦餘波灩灩，嶺头愁斷路茫茫。","經過事寄煙霞远，名利塵隨日月长。","莫道少年头不白，君看潘岳幾莖霜。"]', '诗', 'shi', '', NULL, '途中逢故人話西山讀書早曾游覽 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b51cf31a-cc2e-45b8-9843-0759538e03db', '將赴京題陵陽王氏水居', '將赴京題陵陽王氏水居', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["簾捲平蕪接遠天，暫寬行役到尊前。","是非境裏有閑日，榮辱塵中無了年。","山簇暮雲千野雨，江分秋水九條煙。","馬蹄不道貪西去，爭向一聲高樹蟬。"]', '["簾捲平蕪接远天，暫寬行役到尊前。","是非境裏有闲日，榮辱塵中無了年。","山簇暮云千野雨，江分秋水九條煙。","马蹄不道貪西去，爭向一声高樹蟬。"]', '诗', 'shi', '', NULL, '將赴京題陵陽王氏水居 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2645d81c-e7c0-4693-b3c7-bccbbff58c17', '冬日五浪館水亭懷別', '冬日五浪館水亭懷別', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["蘆荻花多觸處飛，獨憑虛檻雨微微。","寒林葉落鳥巢出，古渡浪高魚艇稀。","雲抱四山終日在，草荒三徑幾時歸。","江城向暝東風急，一半鄉愁聞擣衣。"]', '["蘆荻花多觸处飞，独憑虛檻雨微微。","寒林葉落鸟巢出，古渡浪高鱼艇稀。","云抱四山終日在，草荒三徑幾时归。","江城向暝东风急，一半乡愁闻擣衣。"]', '诗', 'shi', '', NULL, '冬日五浪館水亭懷別 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73a98d35-21df-4623-8f7d-35b8c26caf98', '送別', '送別', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["溪邊楊柳色參差，攀折年年贈別離。","一片風帆望已極，三湘煙水返何時？","多緣去棹將愁遠，猶倚危樓欲下遲。","莫殢酒杯閑過日，碧雲深處是佳期。"]', '["溪邊楊柳色參差，攀折年年贈別離。","一片风帆望已極，三湘煙水返何时？","多緣去棹將愁远，猶倚危楼欲下遲。","莫殢酒杯闲過日，碧云深处是佳期。"]', '诗', 'shi', '', NULL, '送別 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36b114b0-5eb3-4167-82df-539143815797', '寄遠', '寄远', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["兩葉愁眉愁不開，獨含惆悵上層臺。","碧雲空斷鴈行處，紅葉已凋人未來。","塞外音書無信息，道傍車馬起塵埃。","功名待寄凌烟閣，力盡遼城不肯回。"]', '["兩葉愁眉愁不开，独含惆悵上層台。","碧云空斷鴈行处，紅葉已凋人未来。","塞外音书無信息，道傍车马起塵埃。","功名待寄凌烟閣，力尽遼城不肯回。"]', '诗', 'shi', '', NULL, '寄遠 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf0976a1-a812-4a23-8351-278e20c77e55', '新柳', '新柳', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["無力搖風曉色新，細腰爭妒看來頻。","綠陰未覆長堤水，金穗先迎上苑春。","幾處傷心懷遠路，一枝和日送行塵。","東□門外多離別，愁殺朝朝暮暮人。"]', '["無力搖风晓色新，細腰爭妒看来頻。","綠陰未覆长堤水，金穗先迎上苑春。","幾处傷心懷远路，一枝和日送行塵。","东□门外多離別，愁殺朝朝暮暮人。"]', '诗', 'shi', '', NULL, '新柳 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('555f9e74-ec5f-42a3-be1f-d669a4b08f55', '旅懷作', '旅懷作', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["促促因吟晝短詩，朝驚穠色暮空枝。","無情春色不長久，有限年光多盛衰。","往事只應隨夢裏，勞生何處是閑時。","眼前擾擾日一日，暗送白頭人不知。"]', '["促促因吟晝短诗，朝驚穠色暮空枝。","無情春色不长久，有限年光多盛衰。","往事只應隨梦裏，勞生何处是闲时。","眼前擾擾日一日，暗送白头人不知。"]', '诗', 'shi', '', NULL, '旅懷作 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b31b2b15-a6a6-4614-8f7c-70af0c4b9a95', '鴈', '鴈', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["萬里銜蘆別故鄉，雲飛水宿向瀟湘。","數聲孤枕堪垂淚，幾處高樓欲斷腸。","度日翩翩斜避影，臨風一一直成行。","年年辛苦來衡岳，羽翼摧殘隴塞霜。"]', '["万里銜蘆別故乡，云飞水宿向瀟湘。","數声孤枕堪垂泪，幾处高楼欲斷腸。","度日翩翩斜避影，臨风一一直成行。","年年辛苦来衡岳，羽翼摧殘隴塞霜。"]', '诗', 'shi', '', NULL, '鴈 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb4e987f-a755-4a95-ae4a-4ed6fdbb5c60', '出關', '出关', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["朝纓初解佐江濱，麋鹿心知自有羣。","漢囿獵稀慵獻賦，楚山耕早任移文。","臥歸漁浦月連海，行望鳳城花隔雲。","關吏不須迎馬笑，去時無意學終軍。"]', '["朝纓初解佐江濱，麋鹿心知自有羣。","漢囿獵稀慵獻賦，楚山耕早任移文。","臥归漁浦月連海，行望鳳城花隔云。","关吏不須迎马笑，去时無意学終軍。"]', '诗', 'shi', '', NULL, '出關 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1da88c9-ff35-4efc-a94a-3dd3db72548c', '寄房千里博士', '寄房千里博士', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["春風白馬紫絲韁，正值蠶眠未採桑。","五夜有心隨暮雨，百年無節待秋霜。","重尋繡帶朱藤合，更認羅裙碧草長。","爲報西遊減離恨，阮郎纔去嫁劉郎。"]', '["春风白马紫絲韁，正值蠶眠未採桑。","五夜有心隨暮雨，百年無節待秋霜。","重尋繡带朱藤合，更認羅裙碧草长。","爲報西游減離恨，阮郎纔去嫁劉郎。"]', '诗', 'shi', '', NULL, '寄房千里博士 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd8c31b2-bd05-4db4-8857-ba6c160d6f9d', '泛五雲溪', '泛五云溪', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["此溪何處路，遙問白髯翁。","佛廟千巖裏，人家一島中。","魚傾荷葉露，蟬噪柳林風。","急瀨鳴車軸，微波漾釣筒。","石苔縈棹綠，山果拂舟紅。","更就千村宿，溪橋與剡通。"]', '["此溪何处路，遙问白髯翁。","佛廟千巖裏，人家一島中。","鱼傾荷葉露，蟬噪柳林风。","急瀨鳴车軸，微波漾釣筒。","石苔縈棹綠，山果拂舟紅。","更就千村宿，溪橋與剡通。"]', '诗', 'shi', '', NULL, '泛五雲溪 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8c58d42-53a2-40c0-91dd-cef51c70e3db', '寄郴州李相公', '寄郴州李相公', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["高樓王與謝，逸韻比南金。","不遇銷憂日，埃塵誰復尋。","曠懷澹得喪，失意縱登臨。","彩檻浮雲迥，綺窗明月深。","虯龍壓滄海，鴛鴦思鄧林。","青雲傷國器，白髮軫鄉心。","功高恩自洽，道直謗徒侵。","應笑靈均恨，江畔獨行吟。"]', '["高楼王與謝，逸韻比南金。","不遇銷憂日，埃塵誰复尋。","曠懷澹得喪，失意縱登臨。","彩檻浮云迥，綺窗明月深。","虯龙壓滄海，鴛鴦思鄧林。","青云傷国器，白髮軫乡心。","功高恩自洽，道直謗徒侵。","應笑靈均恨，江畔独行吟。"]', '诗', 'shi', '', NULL, '寄郴州李相公 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1c42b46-54f6-4dc0-97c1-0c740c9c7ec9', '贈蕭鍊師', '贈蕭鍊師', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["曾試昭陽曲，瑤齋帝自臨。","紅珠絡繡帽，翠鈿束羅襟。","雙闕胡塵起，千門宿露陰。","出宮迷國步，回駕軫皇心。","桂殿春空晚，椒房夜自深。","急宣求故劒，冥契得遺簪。","暗記神仙傳，潛封女史箴。","壺中知日永，掌上畏年侵。","莫比班家扇，寧同卓氏琴。","雲車辭鳳輦，羽帔別鴛衾。","網斷魚遊藻，籠開鶴戲林。","洛煙浮碧漢，嵩月上丹岑。","露草爭三秀，風篁共八音。","吹笙延鶴舞，敲磬引龍吟。","旄節纖腰舉，霞杯皓腕斟。","還磨照寶鏡，猶插辟寒金。","東海人情變，南山聖壽沈。","朱顏常似渥，綠髪已如尋。","養氣齊生死，留形盡古今。","更求應不見，雞犬日駸駸。"]', '["曾試昭陽曲，瑤斋帝自臨。","紅珠絡繡帽，翠鈿束羅襟。","雙闕胡塵起，千门宿露陰。","出宮迷国步，回駕軫皇心。","桂殿春空晚，椒房夜自深。","急宣求故劒，冥契得遺簪。","暗記神仙傳，潛封女史箴。","壺中知日永，掌上畏年侵。","莫比班家扇，寧同卓氏琴。","云车辞鳳輦，羽帔別鴛衾。","網斷鱼游藻，籠开鹤戲林。","洛煙浮碧漢，嵩月上丹岑。","露草爭三秀，风篁共八音。","吹笙延鹤舞，敲磬引龙吟。","旄節纖腰舉，霞杯皓腕斟。","還磨照寶镜，猶插辟寒金。","东海人情变，南山聖壽沈。","朱顏常似渥，綠髪已如尋。","養氣齊生死，留形尽古今。","更求應不见，雞犬日駸駸。"]', '诗', 'shi', '', NULL, '贈蕭鍊師 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b55e673-26f6-4c1b-bde3-ae7a06d67698', '冬日宣城開元寺贈元孚上人', '冬日宣城开元寺贈元孚上人', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["一鉢事南宗，僧儀稱病容。","曹溪花裏別，蕭寺竹前逢。","燭影深寒殿，經聲徹曙鐘。","欲齋簷睡鴿，初定壁吟蛩。","詩繼休遺韻，書傳永逸蹤。","藝多人譽洽，機絕道情濃。","汲澗瓶沈藻，眠堦錫挂松。","雲鳴新放鶴，池臥舊降龍。","露茗山廚焙，霜秔野碓舂。","梵文明處譯，禪衲暖時縫。","層塔題應遍，飛軒步不慵。","繡梁交薜荔，畫井倒芙蓉。","翠戶垂旗網，朱窗列劒鋒。","寒風金磬遠，晴雪玉樓重。","妙理三乘達，清才萬象供。","山高橫睥睨，灘淺聚艨艟。","微霧蒼平楚，殘暉淡遠峰。","林疎霜摵摵，波靜月溶溶。","劒出因雷煥，琴全遇蔡邕。","西方知有社，支許合相從。"]', '["一鉢事南宗，僧儀稱病容。","曹溪花裏別，蕭寺竹前逢。","燭影深寒殿，經声徹曙鐘。","欲斋簷睡鴿，初定壁吟蛩。","诗繼休遺韻，书傳永逸蹤。","藝多人譽洽，機絕道情濃。","汲澗瓶沈藻，眠堦錫挂松。","云鳴新放鹤，池臥旧降龙。","露茗山廚焙，霜秔野碓舂。","梵文明处譯，禪衲暖时縫。","層塔題應遍，飞軒步不慵。","繡梁交薜荔，畫井倒芙蓉。","翠戶垂旗網，朱窗列劒鋒。","寒风金磬远，晴雪玉楼重。","妙理三乘達，清才万象供。","山高橫睥睨，灘淺聚艨艟。","微霧蒼平楚，殘暉淡远峰。","林疎霜摵摵，波静月溶溶。","劒出因雷煥，琴全遇蔡邕。","西方知有社，支許合相從。"]', '诗', 'shi', '', NULL, '冬日宣城開元寺贈元孚上人 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4317b99-3ac8-476f-a825-b3eb745b1006', '維舟秦淮過溫州李給事宅', '維舟秦淮過溫州李給事宅', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["給事爲郎日，青溪醉隱銜。","冰池通極浦，雪逕遶高巖。","珠玉砂同棄，松筠草共芟。","帝圖憂一失，臣節恥三緘。","代有王陵戇，時無靳尚讒。","定應標直筆，寧爲發空函。","霧黑連雲棧，風狂截海帆。","石梯迎雨潤，沙井待潮鹹。","蠟屐青筇杖，藍輿白罽衫。","應勞北歸夢，山路正巉巉。"]', '["給事爲郎日，青溪醉隐銜。","冰池通極浦，雪逕遶高巖。","珠玉砂同棄，松筠草共芟。","帝圖憂一失，臣節恥三緘。","代有王陵戇，时無靳尚讒。","定應標直笔，寧爲發空函。","霧黑連云棧，风狂截海帆。","石梯迎雨潤，沙井待潮鹹。","蠟屐青筇杖，藍輿白罽衫。","應勞北归梦，山路正巉巉。"]', '诗', 'shi', '', NULL, '維舟秦淮過溫州李給事宅 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1dc5bd7-2fe5-4341-81e5-b9d2a3e4a336', '登蒜山觀發軍', '登蒜山观發軍', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["羽檄徵兵急，轅門選將雄。","犬羊憂破竹，貔虎極飛蓬。","定繫猖狂虜，何煩矍鑠翁。","更探黃石略，重振黑山功。","別馬嘶營柳，驚烏散井桐。","低星連寶劍，殘月讓雕弓。","浪曉戈鋋裏，山晴鼓角中。","甲開魚照水，旗颺虎拏風。","去想金河遠，行知玉塞空。","漢庭應有問，師律在元戎。"]', '["羽檄徵兵急，轅门選將雄。","犬羊憂破竹，貔虎極飞蓬。","定繫猖狂虜，何煩矍鑠翁。","更探黄石略，重振黑山功。","別马嘶營柳，驚烏散井桐。","低星連寶劍，殘月讓雕弓。","浪晓戈鋋裏，山晴鼓角中。","甲开鱼照水，旗颺虎拏风。","去想金河远，行知玉塞空。","漢庭應有问，師律在元戎。"]', '诗', 'shi', '', NULL, '登蒜山觀發軍 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4045d99-2c15-4797-9d52-637f5d70c11b', '送從兄別駕歸蜀', '送從兄別駕归蜀', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["聞與湘南令，童年侍玉墀。","家留秦塞曲，官謫瘴溪湄。","道直姦臣屏，冤深聖主知。","逝川東去疾，霈澤北來遲。","青漢龍髯絕，蒼岑馬鬣移。","風淒聞笛處，月慘罷琴時。","客路黃公廟，鄉關白帝祠。","已稱鸚鵡賦，寧誦鶺鴒詩。","遠道書難達，長亭酒莫持。","當憑蜀江水，萬里寄相思。"]', '["闻與湘南令，童年侍玉墀。","家留秦塞曲，官謫瘴溪湄。","道直姦臣屏，冤深聖主知。","逝川东去疾，霈澤北来遲。","青漢龙髯絕，蒼岑马鬣移。","风淒闻笛处，月慘罷琴时。","客路黄公廟，乡关白帝祠。","已稱鸚鵡賦，寧誦鶺鴒诗。","远道书难達，长亭酒莫持。","當憑蜀江水，万里寄相思。"]', '诗', 'shi', '', NULL, '送從兄別駕歸蜀 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cb80b1d-05c5-4ce1-aac2-cd50be0f795d', '金陵阻風登延祚閣', '金陵阻风登延祚閣', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["極目皆陳迹，披圖問遠公。","戈鋋三國後，冠蓋六朝中。","葛蔓交殘壘，芒花沒後宮。","水流簫鼓絕，山在綺羅空。","極浦千艘聚，高臺一徑通。","雲移吳岫雨，潮轉楚江風。","登閣慙漂梗，停舟憶斷蓬。","歸期與歸路，杉桂海門東。"]', '["極目皆陳迹，披圖问远公。","戈鋋三国後，冠蓋六朝中。","葛蔓交殘壘，芒花沒後宮。","水流簫鼓絕，山在綺羅空。","極浦千艘聚，高台一徑通。","云移吳岫雨，潮轉楚江风。","登閣慙漂梗，停舟憶斷蓬。","归期與归路，杉桂海门东。"]', '诗', 'shi', '', NULL, '金陵阻風登延祚閣 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ceceb959-5df2-42d6-a3e1-52346582a259', '送林處士自閩中道越由霅抵兩川', '送林处士自閩中道越由霅抵兩川', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["書劒少青眼，煙波初白頭。","鄉關背梨嶺，客路轉蘋洲。","處困道難固，乘時恩易酬。","鏡中非訪戴，劒外欲依劉。","高枕海天暝，落帆江雨秋。","鼉聲應遠鼓，蜃氣學危樓。","智士役千慮，達人經百憂。","唯聞陶靖節，多在醉鄉遊。"]', '["书劒少青眼，煙波初白头。","乡关背梨嶺，客路轉蘋洲。","处困道难固，乘时恩易酬。","镜中非訪戴，劒外欲依劉。","高枕海天暝，落帆江雨秋。","鼉声應远鼓，蜃氣学危楼。","智士役千慮，達人經百憂。","唯闻陶靖節，多在醉乡游。"]', '诗', 'shi', '', NULL, '送林處士自閩中道越由霅抵兩川 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8938a98a-d140-4c87-8f4c-bc8b7a14e428', '宣城贈蕭兵曹', '宣城贈蕭兵曹', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["桂檝謫湘渚，三年波上春。","舟寒剡溪雪，衣破洛城塵。","客道恥搖尾，皇恩寬犯鱗。","花時去國遠，月夕上樓頻。","貪酒不辭病，傭書非爲貧。","行吟值漁父，坐隱對樵人。","紫陌罷雙轍，碧潭窮一綸。","高歌更南去，煙水是通津。"]', '["桂檝謫湘渚，三年波上春。","舟寒剡溪雪，衣破洛城塵。","客道恥搖尾，皇恩寬犯鱗。","花时去国远，月夕上楼頻。","貪酒不辞病，傭书非爲貧。","行吟值漁父，坐隐对樵人。","紫陌罷雙轍，碧潭窮一綸。","高歌更南去，煙水是通津。"]', '诗', 'shi', '', NULL, '宣城贈蕭兵曹 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3af556b9-f9b8-4d73-afcb-ab5011717a57', '秋夕宴李侍御宅', '秋夕宴李侍御宅', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["公子徵詞客，秋堂遞玉杯。","月高羅幕卷，風度錦屏開。","鳳管添簧品，鵾弦促柱哀。","轉喉雲旋合，垂手露徐來。","燭換三條燼，香銷十炷灰。","蛩聲聞鼓歇，螢燄觸簾回。","廣檻煙分柳，空庭露積苔。","解酲須滿酌，應爲撥新醅。"]', '["公子徵词客，秋堂遞玉杯。","月高羅幕卷，风度錦屏开。","鳳管添簧品，鵾弦促柱哀。","轉喉云旋合，垂手露徐来。","燭換三條燼，香銷十炷灰。","蛩声闻鼓歇，螢燄觸簾回。","廣檻煙分柳，空庭露積苔。","解酲須满酌，應爲撥新醅。"]', '诗', 'shi', '', NULL, '秋夕宴李侍御宅 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a84cd5f-662d-44c7-b931-96c8424e8783', '晨自竹徑至龍興寺崇隱上人院', '晨自竹徑至龙兴寺崇隐上人院', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["佛寺通南徑，僧堂倚北坡。","藤陰迷晚竹，苔滑仰晴莎。","病憶春前別，閑宜雨後過。","石橫聞水遠，林缺見山多。","欲結三天社，初降十地魔。","毒龍來有窟，靈鶴去無窠。","客路隨萍梗，鄉園失薜蘿。","禪心如可學，不藉魯陽戈。"]', '["佛寺通南徑，僧堂倚北坡。","藤陰迷晚竹，苔滑仰晴莎。","病憶春前別，闲宜雨後過。","石橫闻水远，林缺见山多。","欲結三天社，初降十地魔。","毒龙来有窟，靈鹤去無窠。","客路隨萍梗，乡园失薜蘿。","禪心如可学，不藉魯陽戈。"]', '诗', 'shi', '', NULL, '晨自竹徑至龍興寺崇隱上人院 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e2a847a-b1a0-4626-9a35-b2fd83f36e03', '歲暮自廣江至新興往復中題峽山寺四首 一', '歲暮自廣江至新兴往复中題峽山寺四首 一', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["夜醉晨方醒，孤吟恐失羣。","海鰌潮上見，江鵠霧中聞。","未臘梅先實，經冬草自薰。","樹隨山崦合，泉到石稜分。","虎跡空林雨，猨聲絕嶺雲。","蕭蕭異鄉鬢，明日共絲棼。"]', '["夜醉晨方醒，孤吟恐失羣。","海鰌潮上见，江鵠霧中闻。","未臘梅先實，經冬草自薰。","樹隨山崦合，泉到石稜分。","虎跡空林雨，猨声絕嶺云。","蕭蕭異乡鬢，明日共絲棼。"]', '诗', 'shi', '', NULL, '歲暮自廣江至新興往復中題峽山寺四首 一 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ce95734-7eb6-40aa-a0d5-6e027bcfd08b', '歲暮自廣江至新興往復中題峽山寺四首 二', '歲暮自廣江至新兴往复中題峽山寺四首 二', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["薄暮緣西峽，停橈一訪僧。","鷺巢橫臥柳，猨飲倒垂藤。","水曲巖千疊，雲重樹百層。","山風寒殿磬，溪雨夜船燈。","灘漲危槎沒，泉衝怪石崩。","中臺一襟淚，歲杪別良朋。"]', '["薄暮緣西峽，停橈一訪僧。","鷺巢橫臥柳，猨饮倒垂藤。","水曲巖千叠，云重樹百層。","山风寒殿磬，溪雨夜船灯。","灘漲危槎沒，泉衝怪石崩。","中台一襟泪，歲杪別良朋。"]', '诗', 'shi', '', NULL, '歲暮自廣江至新興往復中題峽山寺四首 二 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebcbe812-820c-4cc2-961e-f126020353d3', '歲暮自廣江至新興往復中題峽山寺四首 三', '歲暮自廣江至新兴往复中題峽山寺四首 三', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["密樹分蒼壁，長溪抱碧岑。","海風聞鶴遠，潭日見魚深。","松蓋環清韵，榕根架綠陰。","洞丁多斵石，蠻女半淘金。","南浦驚春至，西樓送月沈。"]', '["密樹分蒼壁，长溪抱碧岑。","海风闻鹤远，潭日见鱼深。","松蓋环清韵，榕根架綠陰。","洞丁多斵石，蠻女半淘金。","南浦驚春至，西楼送月沈。"]', '诗', 'shi', '', NULL, '歲暮自廣江至新興往復中題峽山寺四首 三 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89450ca6-ce2b-474a-9da8-4c6c6f83d991', '歲暮自廣江至新興往復中題峽山寺四首 四', '歲暮自廣江至新兴往复中題峽山寺四首 四', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["月在行人起，千峰復萬峰。","海虛爭翡翠，溪邏鬬芙蓉。","古木高生槲，陰池滿種松。","火探深洞燕，香送遠潭龍。","藍塢寒先燒，禾堂晚併舂。","更投何處宿，西峽隔雲鐘。"]', '["月在行人起，千峰复万峰。","海虛爭翡翠，溪邏鬬芙蓉。","古木高生槲，陰池满種松。","火探深洞燕，香送远潭龙。","藍塢寒先燒，禾堂晚併舂。","更投何处宿，西峽隔云鐘。"]', '诗', 'shi', '', NULL, '歲暮自廣江至新興往復中題峽山寺四首 四 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('995153fc-153b-4165-8a84-3cbad12232ef', '南海使院對菊懷丁卯別墅', '南海使院对菊懷丁卯別墅', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["何處曾移菊，溪橋鶴嶺東。","籬疎還有豔，園小亦無叢。","日晚秋煙裏，星繁曉露中。","影搖金澗水，香染玉潭風。","罷酒慙陶令，題詩答謝公。","朝來數花發，身在尉佗宮。"]', '["何处曾移菊，溪橋鹤嶺东。","籬疎還有豔，园小亦無叢。","日晚秋煙裏，星繁晓露中。","影搖金澗水，香染玉潭风。","罷酒慙陶令，題诗答謝公。","朝来數花發，身在尉佗宮。"]', '诗', 'shi', '', NULL, '南海使院對菊懷丁卯別墅 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f4d037c-df03-4ba7-8833-5c959dbe2d19', '和李相國', '和李相国', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["巨實珍吳果，馴雛重越禽。","摘來漁浦上，攜在兔園陰。","霜合凝丹頰，風披斂素襟。","刀分瓊液散，籠簌雪華深。","虎帳齋中設，龍樓洛下吟。","含消兼受彩，應貴冢卿心。"]', '["巨實珍吳果，馴雛重越禽。","摘来漁浦上，携在兔园陰。","霜合凝丹頰，风披斂素襟。","刀分瓊液散，籠簌雪华深。","虎帳斋中設，龙楼洛下吟。","含消兼受彩，應貴冢卿心。"]', '诗', 'shi', '', NULL, '和李相國 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('938f24c6-32d8-4947-babd-d31c17dc281c', '陪少師李相國崔賓客宴居守狄僕射池亭', '陪少師李相国崔賓客宴居守狄僕射池亭', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["池色似瀟湘，仙舟正日長。","燕飛驚蛺蝶，魚躍動鴛鴦。","雲聚歌初轉，風回舞欲翔。","暖醅松葉嫩，寒粥杏花香。","羅綺留春色，笙竽送晚光。","何須明月夜，紅燭在華堂。"]', '["池色似瀟湘，仙舟正日长。","燕飞驚蛺蝶，鱼躍动鴛鴦。","云聚歌初轉，风回舞欲翔。","暖醅松葉嫩，寒粥杏花香。","羅綺留春色，笙竽送晚光。","何須明月夜，紅燭在华堂。"]', '诗', 'shi', '', NULL, '陪少師李相國崔賓客宴居守狄僕射池亭 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcb950cd-3e82-4e28-99d0-7703b303511d', '和賓客相國詠雪', '和賓客相国詠雪', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["近臘千巖白，迎春四氣催。","雲陰連海起，風急度山來。","盡日隋堤絮，經冬越嶺梅。","豔疑歌處散，輕似舞時迴。","道蘊詩傳麗，相如賦騁才。","霽添松篠媚，寒積蕙蘭猜。","暗漲宮池水，平封輦路埃。","燭龍初照耀，巢鶴乍裴回。","簷日瓊先挂，牆風粉旋摧。","五門環玉壘，雙闕對瑤臺。","綺席陵寒坐，珠簾遠曙開。","靈芝霜下秀，仙桂月中栽。","卷幌書千帙，援琴酒百桮。","垂休編太史，呈瑞表中台。","皓夜迷三徑，浮光徹九垓。","茲辰是豐歲，歌詠屬良哉。"]', '["近臘千巖白，迎春四氣催。","云陰連海起，风急度山来。","尽日隋堤絮，經冬越嶺梅。","豔疑歌处散，轻似舞时迴。","道蘊诗傳丽，相如賦騁才。","霽添松篠媚，寒積蕙蘭猜。","暗漲宮池水，平封輦路埃。","燭龙初照耀，巢鹤乍裴回。","簷日瓊先挂，牆风粉旋摧。","五门环玉壘，雙闕对瑤台。","綺席陵寒坐，珠簾远曙开。","靈芝霜下秀，仙桂月中栽。","卷幌书千帙，援琴酒百桮。","垂休編太史，呈瑞表中台。","皓夜迷三徑，浮光徹九垓。","茲辰是豐歲，歌詠屬良哉。"]', '诗', 'shi', '', NULL, '和賓客相國詠雪 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('832310bd-8175-4083-a6b1-e4ab89759bbf', '奉和盧大夫新立假山', '奉和盧大夫新立假山', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["巖谷留心賞，爲山極自然。","孤峰空迸笋，攢萼旋開蓮。","黛色朱樓下，雲形繡戶前。","砌塵凝積靄，簷溜挂飛泉。","樹暗壺中月，花香洞裏天。","何如謝康樂，海嶠獨題篇。"]', '["巖谷留心賞，爲山極自然。","孤峰空迸笋，攢萼旋开蓮。","黛色朱楼下，云形繡戶前。","砌塵凝積靄，簷溜挂飞泉。","樹暗壺中月，花香洞裏天。","何如謝康乐，海嶠独題篇。"]', '诗', 'shi', '', NULL, '奉和盧大夫新立假山 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('422e404e-4c01-436b-9a49-dc2ec98add6e', '奉命和後池十韻', '奉命和後池十韻', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["疊石通溪水，量波失舊規。","芳洲還屈曲，朱閣更逶迤。","浴鳥翻荷葉，驚蟬出柳絲。","翠煙秋檜聳，紅露曉蓮披。","攀檻登樓近，停橈待客遲。","野橋從浪沒，輕舸信風移。","竹韻遷棊局，松陰遞酒巵。","性閑鷗自識，心遠鶴先知。","應想秦人會，休懷越相祠。","當期穆天子，簫鼓宴瑤池。"]', '["叠石通溪水，量波失旧規。","芳洲還屈曲，朱閣更逶迤。","浴鸟翻荷葉，驚蟬出柳絲。","翠煙秋檜聳，紅露晓蓮披。","攀檻登楼近，停橈待客遲。","野橋從浪沒，轻舸信风移。","竹韻遷棊局，松陰遞酒巵。","性闲鷗自識，心远鹤先知。","應想秦人會，休懷越相祠。","當期穆天子，簫鼓宴瑤池。"]', '诗', 'shi', '', NULL, '奉命和後池十韻 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('389ff335-4c86-4f7f-9e5f-5c00b8bce978', '雨後思湖上居', '雨後思湖上居', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["前山風雨涼，歇馬坐垂楊。","何處芙蓉落，南渠秋水香。"]', '["前山风雨涼，歇马坐垂楊。","何处芙蓉落，南渠秋水香。"]', '诗', 'shi', '', NULL, '雨後思湖上居 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('206a9053-d835-4517-b91d-928e8015e4a0', '聞歌', '闻歌', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["新秋弦管清，時轉遏雲聲。","曲盡不知處，月高風滿城。"]', '["新秋弦管清，时轉遏云声。","曲尽不知处，月高风满城。"]', '诗', 'shi', '', NULL, '聞歌 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2590a5ec-50b9-41f7-860d-0b18cc6ddd11', '思天台', '思天台', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["赤城雲雪深，山客負歸心。","昨夜西齋宿，月明琪樹陰。"]', '["赤城云雪深，山客負归心。","昨夜西斋宿，月明琪樹陰。"]', '诗', 'shi', '', NULL, '思天台 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1f63452-0108-44fb-9e7f-c9895e39d8e2', '長安早春懷江南', '长安早春懷江南', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["雲月有歸處，故山清洛南。","如何一花發，春夢徧江潭。"]', '["云月有归处，故山清洛南。","如何一花發，春梦徧江潭。"]', '诗', 'shi', '', NULL, '長安早春懷江南 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('421c7cc0-287b-4b55-bb0d-4233d0cf0cee', '塞下', '塞下', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["夜戰桑乾北，秦兵半不歸。","朝來有鄉信，猶自寄征衣。"]', '["夜戰桑乾北，秦兵半不归。","朝来有乡信，猶自寄征衣。"]', '诗', 'shi', '', NULL, '塞下 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07d523ec-3559-47a1-a9af-ec41e00e10a4', '送客南歸', '送客南归', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["野寺薜蘿晚，官渠楊柳春。","歸心已無限，更送洞庭人。"]', '["野寺薜蘿晚，官渠楊柳春。","归心已無限，更送洞庭人。"]', '诗', 'shi', '', NULL, '送客南歸 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8cd3e922-6f07-444f-8418-9d15c469ebf5', '寄桐江隱者', '寄桐江隐者', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["潮去潮來洲渚春，山花如繡草如茵。","嚴陵臺下桐江水，解釣鱸魚能幾人。"]', '["潮去潮来洲渚春，山花如繡草如茵。","嚴陵台下桐江水，解釣鱸鱼能幾人。"]', '诗', 'shi', '', NULL, '寄桐江隱者 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b9c1e01-17bc-47ef-bc6f-1f85bfcae47c', '送曾主簿歸楚州省覲予亦明日歸姑孰', '送曾主簿归楚州省覲予亦明日归姑孰', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["帆轉清淮極鳥飛，落帆應換老萊衣。","河亭未醉先惆悵，明日還從此路歸。"]', '["帆轉清淮極鸟飞，落帆應換老萊衣。","河亭未醉先惆悵，明日還從此路归。"]', '诗', 'shi', '', NULL, '送曾主簿歸楚州省覲予亦明日歸姑孰 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af0420cd-97dc-442a-a03c-77c7f7276dbe', '重別', '重別', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["淚沿紅粉濕羅巾，重繫蘭舟勸酒頻。","留却一枝河畔柳，明朝猶有遠行人。"]', '["泪沿紅粉濕羅巾，重繫蘭舟勸酒頻。","留却一枝河畔柳，明朝猶有远行人。"]', '诗', 'shi', '', NULL, '重別 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb5950fa-f3b3-481c-ad2e-d77835f0b9ee', '湖上', '湖上', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["髣髴欲當三五夕，萬蟬清雜亂泉紋。","釣魚船上一尊酒，月出渡頭零落雲。"]', '["髣髴欲當三五夕，万蟬清杂亂泉紋。","釣鱼船上一尊酒，月出渡头零落云。"]', '诗', 'shi', '', NULL, '湖上 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd395d3e-36e3-4c57-a468-73faab8671b8', '夜泊永樂有懷', '夜泊永乐有懷', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["蓮渚愁紅蕩碧波，吳娃齊唱採蓮歌。","橫塘一別已千里，蘆葦蕭蕭風雨多。"]', '["蓮渚愁紅蕩碧波，吳娃齊唱採蓮歌。","橫塘一別已千里，蘆葦蕭蕭风雨多。"]', '诗', 'shi', '', NULL, '夜泊永樂有懷 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fa0657c-1edd-45f6-8350-eb3a8ed70056', '宿水閤', '宿水閤', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["野客從來不解愁，等閑乘月海西頭。","未知南陌誰家子，夜半吹笙入水樓。"]', '["野客從来不解愁，等闲乘月海西头。","未知南陌誰家子，夜半吹笙入水楼。"]', '诗', 'shi', '', NULL, '宿水閤 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d453c853-bbb5-4159-8ba9-b847d5466639', '謝亭送別', '謝亭送別', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["勞歌一曲解行舟，紅葉青山水急流。","日暮酒醒人已遠，滿天風雨下西樓。"]', '["勞歌一曲解行舟，紅葉青山水急流。","日暮酒醒人已远，满天风雨下西楼。"]', '诗', 'shi', '', NULL, '謝亭送別 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00ac54aa-6fb4-4680-b5fe-3d415aed851d', '酬李當', '酬李當', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["知有瑤華手自開，巴人虛唱懶封回。","山陰一夜滿溪雪，借問扁舟來不來。"]', '["知有瑤华手自开，巴人虛唱懶封回。","山陰一夜满溪雪，借问扁舟来不来。"]', '诗', 'shi', '', NULL, '酬李當 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f32e213-8f47-4e3b-a4eb-64f8dadccde6', '蟬', '蟬', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["噪柳鳴槐晚未休，不知何事愛悲秋。","朱門大有長吟處，剛傍愁人又送愁。"]', '["噪柳鳴槐晚未休，不知何事愛悲秋。","朱门大有长吟处，剛傍愁人又送愁。"]', '诗', 'shi', '', NULL, '蟬 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f6e07d0-b3fa-4ab0-b465-bb9bdb7ead53', '夜過松江渡寄友人', '夜過松江渡寄友人', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["清露白雲明月天，與君齊棹木蘭船。","南湖風雨一相失，夜泊橫塘心渺然。"]', '["清露白云明月天，與君齊棹木蘭船。","南湖风雨一相失，夜泊橫塘心渺然。"]', '诗', 'shi', '', NULL, '夜過松江渡寄友人 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39fce43a-b644-4a16-a3be-347a01e1eb4a', '守風淮陰', '守风淮陰', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["遙見江陰夜漁客，因思京口釣魚時。","一潭明月萬株柳，自去自來人不知。"]', '["遙见江陰夜漁客，因思京口釣鱼时。","一潭明月万株柳，自去自来人不知。"]', '诗', 'shi', '', NULL, '守風淮陰 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('454d1f56-4e0b-402a-8f88-e6ed7ef4d441', '亡題', '亡題', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["商嶺採芝尋四老，紫陽收朮訪三茅。","欲求不死長生訣，骨裏無仙不肯教。"]', '["商嶺採芝尋四老，紫陽收朮訪三茅。","欲求不死长生訣，骨裏無仙不肯教。"]', '诗', 'shi', '', NULL, '亡題 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('faeb7219-b951-4dc3-a9df-da54029a4882', '送楊發東歸', '送楊發东归', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["紅花半落燕于飛，同客長安今獨歸。","一紙鄉書報兄弟，還家羞著別時衣。"]', '["紅花半落燕于飞，同客长安今独归。","一紙乡书報兄弟，還家羞著別时衣。"]', '诗', 'shi', '', NULL, '送楊發東歸 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1aeb4a0-79b9-4b3b-a2d4-c1f8a214c881', '寄宋邧', '寄宋邧', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["朱檻煙霜夜坐勞，美人南國舊同袍。","山長水遠無消息，瑤瑟一彈秋月高。"]', '["朱檻煙霜夜坐勞，美人南国旧同袍。","山长水远無消息，瑤瑟一彈秋月高。"]', '诗', 'shi', '', NULL, '寄宋邧 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d7f8d32-d6d0-4c3d-89c6-f9941844fbff', '題四老廟二首 一', '題四老廟二首 一', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["峨峨商嶺采芝人，雪頂霜髯虎豹茵。","山酒一巵歌一曲，漢家天子忌功臣。"]', '["峨峨商嶺采芝人，雪頂霜髯虎豹茵。","山酒一巵歌一曲，漢家天子忌功臣。"]', '诗', 'shi', '', NULL, '題四老廟二首 一 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41e686cc-ea20-409e-a417-8441c6ec8d55', '題四老廟二首 二', '題四老廟二首 二', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["避秦安漢出藍關，松桂花陰滿舊山。","自是無人有歸意，白雲常在水潺潺。"]', '["避秦安漢出藍关，松桂花陰满旧山。","自是無人有归意，白云常在水潺潺。"]', '诗', 'shi', '', NULL, '題四老廟二首 二 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6aed28fd-a1f1-44ee-93a7-4a84b0d1ae55', '夏日寄江上親友', '夏日寄江上親友', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["雨過前山日未斜，清蟬嘒嘒落槐花。","車輪南北已無限，江上故人纔到家。"]', '["雨過前山日未斜，清蟬嘒嘒落槐花。","车輪南北已無限，江上故人纔到家。"]', '诗', 'shi', '', NULL, '夏日寄江上親友 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5409f3b-9dd6-47ba-8aa9-eade79760d58', '下第懷友人', '下第懷友人', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["獨掩衡門花盛時，一封書信緩歸期。","南宗更有瀟湘客，夜夜月明聞竹枝。"]', '["独掩衡门花盛时，一封书信緩归期。","南宗更有瀟湘客，夜夜月明闻竹枝。"]', '诗', 'shi', '', NULL, '下第懷友人 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1642fd97-bc35-4798-b40f-0174e0444fb8', '客有卜居不遂薄遊汧隴因題', '客有卜居不遂薄游汧隴因題', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["海燕西飛白日斜，天門遙望五侯家。","樓臺深鎖無人到，落盡春風第一花。"]', '["海燕西飞白日斜，天门遙望五侯家。","楼台深鎖無人到，落尽春风第一花。"]', '诗', 'shi', '', NULL, '客有卜居不遂薄遊汧隴因題 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b154c70c-041b-4764-bed8-123f6c5750b9', '陳宮怨二首 一', '陳宮怨二首 一', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["風暖江城白日遲，昔人遺事後人悲。","草生宮闕國無主，玉樹後庭花爲誰。"]', '["风暖江城白日遲，昔人遺事後人悲。","草生宮闕国無主，玉樹後庭花爲誰。"]', '诗', 'shi', '', NULL, '陳宮怨二首 一 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc93b706-1335-4a13-bb33-c8cee82f28da', '陳宮怨二首 二', '陳宮怨二首 二', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["地雄山險水悠悠，不信隋兵到石頭。","玉樹後庭花一曲，與君同上景陽樓。"]', '["地雄山險水悠悠，不信隋兵到石头。","玉樹後庭花一曲，與君同上景陽楼。"]', '诗', 'shi', '', NULL, '陳宮怨二首 二 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e38c69eb-8cda-4c2a-8a66-cf950b9e69bf', '經故太尉段公廟', '經故太尉段公廟', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["靜想追兵緩翠華，古碑荒廟閉松花。","紀生不向滎陽死，爭有山河屬漢家。"]', '["静想追兵緩翠华，古碑荒廟閉松花。","紀生不向滎陽死，爭有山河屬漢家。"]', '诗', 'shi', '', NULL, '經故太尉段公廟 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44aa5f75-3db8-4657-a03d-7c45547482f2', '途經秦始皇墓', '途經秦始皇墓', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["龍盤虎踞樹層層，勢入浮雲亦是崩。","一種青山秋草裏，路人唯拜漢文陵。"]', '["龙盤虎踞樹層層，勢入浮云亦是崩。","一種青山秋草裏，路人唯拜漢文陵。"]', '诗', 'shi', '', NULL, '途經秦始皇墓 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f17bae59-31ff-4374-8af6-f21a92f6cab3', '游楞伽寺', '游楞伽寺', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["碧煙秋寺泛潮來，水浸城根古堞摧。","盡日傷心人不見，石榴花滿舊琴臺。"]', '["碧煙秋寺泛潮来，水浸城根古堞摧。","尽日傷心人不见，石榴花满旧琴台。"]', '诗', 'shi', '', NULL, '游楞伽寺 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db3f0de3-23ff-4bae-bd32-d2914e66b85c', '緱山廟', '緱山廟', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["王子吹簫月滿臺，玉簫清轉鶴裴回。","曲終飛去不知處，山下碧桃春自開。"]', '["王子吹簫月满台，玉簫清轉鹤裴回。","曲終飞去不知处，山下碧桃春自开。"]', '诗', 'shi', '', NULL, '緱山廟 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1be7b39c-8dbf-487d-a833-2309a90c67ab', '送薛先輩入關', '送薛先輩入关', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["一巵春酒送離歌，花落敬亭芳草多。","欲問歸期已深醉，只應孤夢繞關河。"]', '["一巵春酒送離歌，花落敬亭芳草多。","欲问归期已深醉，只應孤梦繞关河。"]', '诗', 'shi', '', NULL, '送薛先輩入關 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55de26a1-098e-4916-be9d-1aea3b806a40', '鴻溝', '鴻溝', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["相持未定各爲君，秦政山河此地分。","力盡烏江千載後，古溝芳草起寒雲。"]', '["相持未定各爲君，秦政山河此地分。","力尽烏江千載後，古溝芳草起寒云。"]', '诗', 'shi', '', NULL, '鴻溝 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('849a010b-702a-4aff-9bb0-9f4508f7a243', '韓信廟', '韓信廟', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["朝言雲夢暮南巡，已爲功名少退身。","盡握兵權猶不得，更將心計託何人。"]', '["朝言云梦暮南巡，已爲功名少退身。","尽握兵權猶不得，更將心計託何人。"]', '诗', 'shi', '', NULL, '韓信廟 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d68ad1c-84c0-4732-b82e-790aef17d280', '過湘妃廟', '過湘妃廟', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["古木蒼山掩翠娥，月明南浦起微波。","九疑望斷幾千載，斑竹淚痕今更多。"]', '["古木蒼山掩翠娥，月明南浦起微波。","九疑望斷幾千載，斑竹泪痕今更多。"]', '诗', 'shi', '', NULL, '過湘妃廟 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c98ffd7a-46a0-4bf3-8274-cbeed7ed2384', '寄雲際寺敬上人', '寄云際寺敬上人', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["萬山秋雨水縈回，紅葉多從紫閣來。","雲冷竹齋禪衲薄，已應飛錫過天台。"]', '["万山秋雨水縈回，紅葉多從紫閣来。","云冷竹斋禪衲薄，已應飞錫過天台。"]', '诗', 'shi', '', NULL, '寄雲際寺敬上人 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('366338ab-0519-49ed-ace6-1b297d0a54b1', '秋思', '秋思', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["琪樹西風枕簟秋，楚雲湘水憶同遊。","高歌一曲掩明鏡，昨日少年今白頭。"]', '["琪樹西风枕簟秋，楚云湘水憶同游。","高歌一曲掩明镜，昨日少年今白头。"]', '诗', 'shi', '', NULL, '秋思 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1546c07e-a015-4682-bac9-a414629c95d3', '送宋處士歸山', '送宋处士归山', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["賣藥修琴歸去遲，山風吹盡桂花枝。","世間甲子須臾事，逢著仙人莫看棋。"]', '["賣藥修琴归去遲，山风吹尽桂花枝。","世间甲子須臾事，逢著仙人莫看棋。"]', '诗', 'shi', '', NULL, '送宋處士歸山 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77abf77b-9c3c-43dd-8866-3e600d028bb8', '聽琵琶', '听琵琶', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["欲寫明妃萬里情，紫槽紅撥夜丁丁。","胡沙望盡漢宮遠，月落天山聞一聲。"]', '["欲寫明妃万里情，紫槽紅撥夜丁丁。","胡沙望尽漢宮远，月落天山闻一声。"]', '诗', 'shi', '', NULL, '聽琵琶 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('988039dc-1e67-4f3d-8306-f01e2e1c1e95', '秦樓曲', '秦楼曲', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["秦女夢餘仙路遙，月窗風簟夜迢迢。","潘郎翠鳳雙飛去，三十六宮聞玉簫。"]', '["秦女梦餘仙路遙，月窗风簟夜迢迢。","潘郎翠鳳雙飞去，三十六宮闻玉簫。"]', '诗', 'shi', '', NULL, '秦樓曲 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea81582e-0968-4517-9166-f004df071704', '旌儒廟', '旌儒廟', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["寒陌陰風萬古悲，儒冠相枕死秦時。","廟前亦有商山路，不學老翁歌紫芝。"]', '["寒陌陰风万古悲，儒冠相枕死秦时。","廟前亦有商山路，不学老翁歌紫芝。"]', '诗', 'shi', '', NULL, '旌儒廟 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edae60a3-4137-4c0d-9f59-e9cfeeda3a49', '覽故人題僧院詩', '覽故人題僧院诗', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["高閣清吟寄遠公，四時雲月一篇中。","今來借問獨何處，日暮槿花零落風。"]', '["高閣清吟寄远公，四时云月一篇中。","今来借问独何处，日暮槿花零落风。"]', '诗', 'shi', '', NULL, '覽故人題僧院詩 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c497abf-1636-472b-bc30-2b7722918ba3', '楚宮怨二首 一', '楚宮怨二首 一', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["十二山晴花盡開，楚宮雙闕對陽臺。","細腰爭舞君沈醉，白日秦兵天上來。"]', '["十二山晴花尽开，楚宮雙闕对陽台。","細腰爭舞君沈醉，白日秦兵天上来。"]', '诗', 'shi', '', NULL, '楚宮怨二首 一 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d77482d7-0921-471d-92b5-f493fb8bc41e', '楚宮怨二首 二', '楚宮怨二首 二', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["獵騎秋來在內稀，渚宮雲雨濕龍衣。","騰騰戰鼓動城闕，江畔射麋殊未歸。"]', '["獵騎秋来在內稀，渚宮云雨濕龙衣。","腾腾戰鼓动城闕，江畔射麋殊未归。"]', '诗', 'shi', '', NULL, '楚宮怨二首 二 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33f7be51-d3f1-4b2d-9403-e16bd3c4bde3', '聽唱山鷓鴣', '听唱山鷓鴣', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["金谷歌傳第一流，鷓鴣清怨碧煙愁。","夜來省得曾聞處，萬里月明湘水秋。"]', '["金谷歌傳第一流，鷓鴣清怨碧煙愁。","夜来省得曾闻处，万里月明湘水秋。"]', '诗', 'shi', '', NULL, '聽唱山鷓鴣 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd6e1da0-f5cb-43d4-b3d1-f617e81ffdf2', '晨起西樓', '晨起西楼', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["留情深處駐橫波，斂翠凝紅一曲歌。","明月下樓人未散，共愁三徑是天河。"]', '["留情深处駐橫波，斂翠凝紅一曲歌。","明月下楼人未散，共愁三徑是天河。"]', '诗', 'shi', '', NULL, '晨起西樓 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d517982-8603-4f46-af94-cbcae502099a', '酬江西盧端公藍口阻風見寄之什', '酬江西盧端公藍口阻风见寄之什', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["又攜刀筆泛膺舟，藍口風高桂檝留。","還似郢中歌一曲，夜來春雪照西樓。"]', '["又携刀笔泛膺舟，藍口风高桂檝留。","還似郢中歌一曲，夜来春雪照西楼。"]', '诗', 'shi', '', NULL, '酬江西盧端公藍口阻風見寄之什 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a4e6676-bfb1-4420-b3fa-f64cf5984489', '贈何處士', '贈何处士', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["東別茅峰北去秦，梅仙書裏說真人。","白頭主印青山下，雖遇唐生不敢親。"]', '["东別茅峰北去秦，梅仙书裏说真人。","白头主印青山下，雖遇唐生不敢親。"]', '诗', 'shi', '', NULL, '贈何處士 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb4db05d-3fd1-4fcc-a762-4f9731ad5b85', '鷺鷥', '鷺鷥', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["西風澹澹水悠悠，雪點絲飄帶雨愁。","何限歸心倚前閤，綠蒲紅蓼練塘秋。"]', '["西风澹澹水悠悠，雪点絲飄带雨愁。","何限归心倚前閤，綠蒲紅蓼練塘秋。"]', '诗', 'shi', '', NULL, '鷺鷥 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1755ac10-2864-48f1-8c2f-122f359dda70', '學仙二首 一', '学仙二首 一', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["漢武迎仙紫禁秋，玉笙瑤瑟祀崑丘。","年年望斷無消息，空閉重城十二樓。"]', '["漢武迎仙紫禁秋，玉笙瑤瑟祀崑丘。","年年望斷無消息，空閉重城十二楼。"]', '诗', 'shi', '', NULL, '學仙二首 一 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6a0fc25-c8f2-488b-a920-f4cd631c97cb', '學仙二首 二', '学仙二首 二', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["心期仙訣意無窮，采畫雲車起壽宮。","聞有三山未知處，茂陵松柏滿西風。"]', '["心期仙訣意無窮，采畫云车起壽宮。","闻有三山未知处，茂陵松柏满西风。"]', '诗', 'shi', '', NULL, '學仙二首 二 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('438e966a-8517-4270-a19c-d52b48063a3f', '酬康州韋侍御同年', '酬康州韋侍御同年', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["桂楫美人歌木蘭，西風褭褭露溥溥。","夜長曲盡意不盡，月在清湘洲渚寒。"]', '["桂楫美人歌木蘭，西风褭褭露溥溥。","夜长曲尽意不尽，月在清湘洲渚寒。"]', '诗', 'shi', '', NULL, '酬康州韋侍御同年 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adffb7af-5583-4ec6-8c2e-a68d2a161d63', '紫藤', '紫藤', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["綠蔓穠陰紫袖低，客來留坐小堂西。","醉中掩瑟無人會，家近江南罨畫溪。"]', '["綠蔓穠陰紫袖低，客来留坐小堂西。","醉中掩瑟無人會，家近江南罨畫溪。"]', '诗', 'shi', '', NULL, '紫藤 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9bb4eba2-0aaa-4ee2-8ed6-839fa68a9d8f', '宿咸宜觀', '宿咸宜观', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["羽袖飄飄杳夜風，翠幢歸殿玉壇空。","步虛聲盡天未曉，露壓桃花月滿宮。"]', '["羽袖飄飄杳夜风，翠幢归殿玉壇空。","步虛声尽天未晓，露壓桃花月满宮。"]', '诗', 'shi', '', NULL, '宿咸宜觀 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04503c2d-97c7-4fe6-9805-215534b1b452', '金谷園', '金谷园', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["三惑沈身是此園，古藤荒草野禽喧。","二十四友一朝盡，愛妾墜樓何足言。"]', '["三惑沈身是此园，古藤荒草野禽喧。","二十四友一朝尽，愛妾墜楼何足言。"]', '诗', 'shi', '', NULL, '金谷園 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4d43374-832a-4846-a518-0bd079946fc7', '送崔珦入朝', '送崔珦入朝', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["書劒功遲白髮新，強登蕭寺送歸秦。","月斜松桂倚高閣，明夜江南江北人。"]', '["书劒功遲白髮新，強登蕭寺送归秦。","月斜松桂倚高閣，明夜江南江北人。"]', '诗', 'shi', '', NULL, '送崔珦入朝 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e533b0ec-e6d5-4b1b-928a-865a95ea4fab', '病中和大夫翫江月', '病中和大夫翫江月', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["江上懸光海上生，仙舟迢遰繞軍營。","高歌一曲同筵醉，却是劉楨坐到明。"]', '["江上懸光海上生，仙舟迢遰繞軍營。","高歌一曲同筵醉，却是劉楨坐到明。"]', '诗', 'shi', '', NULL, '病中和大夫翫江月 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d5f2709-a375-4ded-a665-0871e0b63c7c', '讀戾太子傳', '读戾太子傳', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["佞臣巫蠱已相疑，身沒湖邊築望思。","今日更歸何處是，年年芳草上臺基。"]', '["佞臣巫蠱已相疑，身沒湖邊築望思。","今日更归何处是，年年芳草上台基。"]', '诗', 'shi', '', NULL, '讀戾太子傳 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a6c6d2c-735f-4b5e-8fad-c407abf630d0', '酬對雪見寄', '酬对雪见寄', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["飛度龍山下遠空，拂簷縈竹晝濛濛。","知君吟罷意無限，曾聽玉堂歌北風。"]', '["飞度龙山下远空，拂簷縈竹晝濛濛。","知君吟罷意無限，曾听玉堂歌北风。"]', '诗', 'shi', '', NULL, '酬對雪見寄 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72366286-73aa-49c3-9ac0-fa0017da8a4a', '王可封臨終', '王可封臨終', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["十世爲儒少子孫，一生長負信陵恩。","今朝埋骨寒山下，爲報慈親休倚門。"]', '["十世爲儒少子孫，一生长負信陵恩。","今朝埋骨寒山下，爲報慈親休倚门。"]', '诗', 'shi', '', NULL, '王可封臨終 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c29fe36-3fec-4c18-b3ff-342e9e816d01', '僧院影堂', '僧院影堂', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["香銷雲凝舊僧家，僧剎殘燈壁半斜。","日暮松煙空漠漠，秋風吹破妙蓮華。"]', '["香銷云凝旧僧家，僧剎殘灯壁半斜。","日暮松煙空漠漠，秋风吹破妙蓮华。"]', '诗', 'shi', '', NULL, '僧院影堂 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98140fff-28fa-4b59-9c60-ce456b6a4397', '紀夢', '紀梦', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["曉入瑤臺露氣清，座中唯有許飛瓊。","塵心未盡俗緣在，十里下山空月明。"]', '["晓入瑤台露氣清，座中唯有許飞瓊。","塵心未尽俗緣在，十里下山空月明。"]', '诗', 'shi', '', NULL, '紀夢 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a154a9b3-bd7f-4dd9-af49-22eca32c51a7', '三十六灣', '三十六灣', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["縹緲臨風思美人，荻花楓葉帶離聲。","夜深吹笛移船去，三十六灣秋月明。"]', '["縹緲臨风思美人，荻花楓葉带離声。","夜深吹笛移船去，三十六灣秋月明。"]', '诗', 'shi', '', NULL, '三十六灣 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93060e2d-d4a1-4d09-941b-e030136eaf17', '越中', '越中', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["石城花暖鷓鴣飛，征客春帆秋不歸。","猶自保郎心似石，綾梭夜夜織寒衣。"]', '["石城花暖鷓鴣飞，征客春帆秋不归。","猶自保郎心似石，綾梭夜夜织寒衣。"]', '诗', 'shi', '', NULL, '越中 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0eb3016-9288-4dc0-9257-3de36e5ad73c', '錦瑟', '錦瑟', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["錦瑟無端五十絃，一絃一柱思華年。","莊生曉夢迷蝴蝶，望帝春心託杜鵑。","滄海月明珠有淚，藍田日暖玉生煙。","此情可待成追憶，只是當時已惘然。"]', '["錦瑟無端五十絃，一絃一柱思华年。","莊生晓梦迷蝴蝶，望帝春心託杜鵑。","滄海月明珠有泪，藍田日暖玉生煙。","此情可待成追憶，只是當时已惘然。"]', '诗', 'shi', '', NULL, '錦瑟 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7d221a9-62ed-4b94-8713-c2d70e174526', '重過聖女祠', '重過聖女祠', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["白石巖扉碧蘚滋，上清淪謫得歸遲。","一春夢雨常飄瓦，盡日靈風不滿旗。","萼綠華來無定所，杜蘭香去未移時。","玉郎會此通仙籍，憶向天階問紫芝。"]', '["白石巖扉碧蘚滋，上清淪謫得归遲。","一春梦雨常飄瓦，尽日靈风不满旗。","萼綠华来無定所，杜蘭香去未移时。","玉郎會此通仙籍，憶向天階问紫芝。"]', '诗', 'shi', '', NULL, '重過聖女祠 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70779e79-e103-4985-9e37-0e408d149c71', '寄羅劭興', '寄羅劭兴', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["棠棣黃花發，忘憂碧葉齊。","人閑微病酒，燕重遠兼泥。","混沌何由鑿，青冥有未梯。","高陽舊徒侶，時復一相攜。"]', '["棠棣黄花發，忘憂碧葉齊。","人闲微病酒，燕重远兼泥。","混沌何由鑿，青冥有未梯。","高陽旧徒侶，时复一相携。"]', '诗', 'shi', '', NULL, '寄羅劭興 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6683b74-ed00-456c-8c1d-9847d9546e11', '令狐舍人說昨夜西掖翫月因戲贈', '令狐舍人说昨夜西掖翫月因戲贈', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["昨夜玉輪明，傳聞近太清。","涼波衝碧瓦，曉暈落金莖。","露索秦宮井，風絃漢殿箏。","幾時緜竹頌，擬薦子虛名。"]', '["昨夜玉輪明，傳闻近太清。","涼波衝碧瓦，晓暈落金莖。","露索秦宮井，风絃漢殿箏。","幾时緜竹頌，擬薦子虛名。"]', '诗', 'shi', '', NULL, '令狐舍人說昨夜西掖翫月因戲贈 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('714393ee-b874-436c-9c76-59964b530556', '崔處士', '崔处士', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["真人塞其內，夫子入於機。","未肯投竿起，惟歡負米歸。","雪中東郭履，堂上老萊衣。","讀遍先賢傳，如君事者稀。"]', '["真人塞其內，夫子入於機。","未肯投竿起，惟歡負米归。","雪中东郭履，堂上老萊衣。","读遍先賢傳，如君事者稀。"]', '诗', 'shi', '', NULL, '崔處士 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('288e18ae-3c84-47db-b7ef-41f41605d397', '自喜', '自喜', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["自喜蝸牛舍，兼容燕子巢。","綠筠遺粉籜，紅藥綻香苞。","虎過遙知穽，魚來且佐庖。","慢行成酩酊，鄰壁有松醪。"]', '["自喜蝸牛舍，兼容燕子巢。","綠筠遺粉籜，紅藥綻香苞。","虎過遙知穽，鱼来且佐庖。","慢行成酩酊，鄰壁有松醪。"]', '诗', 'shi', '', NULL, '自喜 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c99fc38-53b2-48be-b92d-ee089fc614be', '題僧壁', '題僧壁', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["捨生求道有前蹤，乞腦剜身結願重。","大去便應欺粟顆，小來兼可隱針鋒。","蚌胎未滿思新桂，琥珀初成憶舊松。","若信貝多真實語，三生同聽一樓鐘。"]', '["捨生求道有前蹤，乞腦剜身結願重。","大去便應欺粟顆，小来兼可隐針鋒。","蚌胎未满思新桂，琥珀初成憶旧松。","若信貝多真實語，三生同听一楼鐘。"]', '诗', 'shi', '', NULL, '題僧壁 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f653e6b-c416-4d2e-9866-c6dbcfcf0b99', '霜月', '霜月', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["初聞征雁已無蟬，百尺樓高水接天。","青女素娥俱耐冷，月中霜裏鬬嬋娟。"]', '["初闻征雁已無蟬，百尺楼高水接天。","青女素娥俱耐冷，月中霜裏鬬嬋娟。"]', '诗', 'shi', '', NULL, '霜月 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36d0e69d-6290-44db-8e9f-3a9625079cef', '異俗二首 一', '異俗二首 一', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["鬼瘧朝朝避，春寒夜夜添。","未驚雷破柱，不報水齊簷。","虎箭侵膚毒，魚鉤刺骨銛。","鳥言成諜訴，多是恨彤幨。"]', '["鬼瘧朝朝避，春寒夜夜添。","未驚雷破柱，不報水齊簷。","虎箭侵膚毒，鱼鉤刺骨銛。","鸟言成諜訴，多是恨彤幨。"]', '诗', 'shi', '', NULL, '異俗二首 一 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e1c2074-1e65-4118-9c6e-f8e3aeac511e', '異俗二首 二', '異俗二首 二', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["戶盡懸秦網，家多事越巫。","未曾容獺祭，只是縱猪都。","點對連鰲餌，搜求縛虎符。","賈生兼事鬼，不信有洪爐。"]', '["戶尽懸秦網，家多事越巫。","未曾容獺祭，只是縱猪都。","点对連鰲餌，搜求縛虎符。","賈生兼事鬼，不信有洪爐。"]', '诗', 'shi', '', NULL, '異俗二首 二 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ac175f6-6785-4fc9-bbdc-c788540c51fc', '歸墅', '归墅', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["行李踰南極，旬時到舊鄉。","楚芝應徧紫，鄧橘未全黃。","渠濁村舂急，旗高社酒香。","故山歸夢喜，先入讀書堂。"]', '["行李踰南極，旬时到旧乡。","楚芝應徧紫，鄧橘未全黄。","渠濁村舂急，旗高社酒香。","故山归梦喜，先入读书堂。"]', '诗', 'shi', '', NULL, '歸墅 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a702135-6667-47b5-8c68-5b908f1eee18', '商於', '商於', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["商於朝雨霽，歸路有秋光。","背塢猿收果，投巖麝退香。","建瓴真得勢，橫戟豈能當。","割地張儀詐，謀身綺季長。","清渠州外月，黃葉廟前霜。","今日看雲意，依依入帝鄉。"]', '["商於朝雨霽，归路有秋光。","背塢猿收果，投巖麝退香。","建瓴真得勢，橫戟豈能當。","割地張儀詐，謀身綺季长。","清渠州外月，黄葉廟前霜。","今日看云意，依依入帝乡。"]', '诗', 'shi', '', NULL, '商於 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e37fb83-959d-4b18-8229-d8f5506f9e1e', '和孫朴韋蟾孔雀詠', '和孫朴韋蟾孔雀詠', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["此去三梁遠，今來萬里攜。","西施因網得，秦客被花迷。","可在青鸚鵡，非關碧野雞。","約眉憐翠羽，刮目想金篦。","瘴氣籠飛遠，蠻花向坐低。","輕於趙皇后，貴極楚懸黎。","都護矜羅幕，佳人炫繡袿。","屏風臨燭釦，捍撥倚香臍。","舊思牽雲葉，新愁待雪泥。","愛堪通夢寐，畫得不端倪。","地錦排蒼雁，簾釘鏤白犀。","曙霞星斗外，涼月露盤西。","妬好休誇舞，經寒且少啼。","紅樓三十級，穩穩上丹梯。"]', '["此去三梁远，今来万里携。","西施因網得，秦客被花迷。","可在青鸚鵡，非关碧野雞。","約眉怜翠羽，刮目想金篦。","瘴氣籠飞远，蠻花向坐低。","轻於趙皇后，貴極楚懸黎。","都護矜羅幕，佳人炫繡袿。","屏风臨燭釦，捍撥倚香臍。","旧思牽云葉，新愁待雪泥。","愛堪通梦寐，畫得不端倪。","地錦排蒼雁，簾釘鏤白犀。","曙霞星斗外，涼月露盤西。","妬好休誇舞，經寒且少啼。","紅楼三十級，穩穩上丹梯。"]', '诗', 'shi', '', NULL, '和孫朴韋蟾孔雀詠 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('084f2451-8aed-4fc9-8e58-986c3d6e95b8', '人欲', '人欲', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["人欲天從竟不疑，莫言圓蓋便無私。","秦中已久烏頭白，却是君王未備知。"]', '["人欲天從竟不疑，莫言圓蓋便無私。","秦中已久烏头白，却是君王未備知。"]', '诗', 'shi', '', NULL, '人欲 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcbeff30-583c-4d6c-a4d7-3f0b790e7d7c', '華山題王母祠', '华山題王母祠', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["蓮華峰下鎖雕梁，此去瑤池地共長。","好爲麻姑到東海，勸栽黃竹莫栽桑。"]', '["蓮华峰下鎖雕梁，此去瑤池地共长。","好爲麻姑到东海，勸栽黄竹莫栽桑。"]', '诗', 'shi', '', NULL, '華山題王母祠 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5624914b-f695-4597-ad74-a12319e4e181', '華清宮', '华清宮', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["華清恩幸古無倫，猶恐蛾眉不勝人。","未免被他褒女笑，只教天子暫蒙塵。"]', '["华清恩幸古無倫，猶恐蛾眉不勝人。","未免被他褒女笑，只教天子暫蒙塵。"]', '诗', 'shi', '', NULL, '華清宮 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fc515bd-7e51-4759-acff-3686100584c7', '楚澤', '楚澤', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["夕陽歸路後，霜野物聲乾。","集鳥翻漁艇，殘虹拂馬鞍。","劉楨元抱病，虞寄數辭官。","白袷經年卷，西來及早寒。"]', '["夕陽归路後，霜野物声乾。","集鸟翻漁艇，殘虹拂马鞍。","劉楨元抱病，虞寄數辞官。","白袷經年卷，西来及早寒。"]', '诗', 'shi', '', NULL, '楚澤 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3de619f-cc8b-457d-942b-49f06651aba4', '蟬', '蟬', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["本以高難飽，徒勞恨費聲。","五更疎欲斷，一樹碧無情。","薄宦梗猶汎，故園蕪已平。","煩君最相警，我亦舉家清。"]', '["本以高难飽，徒勞恨費声。","五更疎欲斷，一樹碧無情。","薄宦梗猶汎，故园蕪已平。","煩君最相警，我亦舉家清。"]', '诗', 'shi', '', NULL, '蟬 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c96efde-f36f-44ef-934a-874377c14e5f', '江亭散席循柳路吟', '江亭散席循柳路吟', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["春詠敢輕裁，銜辭入半杯。","已遭江映柳，更被雪藏梅。","寡和真徒爾，殷憂動即來。","從詩得何報，惟感二毛催。"]', '["春詠敢轻裁，銜辞入半杯。","已遭江映柳，更被雪藏梅。","寡和真徒爾，殷憂动即来。","從诗得何報，惟感二毛催。"]', '诗', 'shi', '', NULL, '江亭散席循柳路吟 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac47b62e-5756-4ae0-a9f9-973354451549', '潭州', '潭州', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["潭州官舍暮樓空，今古無端入望中。","湘淚淺深滋竹色，楚歌重疊怨蘭叢。","陶公戰艦空灘雨，賈傅承塵破廟風。","目斷故園人不至，松醪一醉與誰同。"]', '["潭州官舍暮楼空，今古無端入望中。","湘泪淺深滋竹色，楚歌重叠怨蘭叢。","陶公戰艦空灘雨，賈傅承塵破廟风。","目斷故园人不至，松醪一醉與誰同。"]', '诗', 'shi', '', NULL, '潭州 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57ee870e-5fea-4717-992d-73683ed0680e', '贈劉司戶', '贈劉司戶', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["江風吹浪動雲根，重碇危檣白日昏。","已斷燕鴻初起勢，更驚騷客後歸魂。","漢廷急詔誰先入，楚路高歌自欲翻。","萬里相逢歡復泣，鳳巢西隔九重門。"]', '["江风吹浪动云根，重碇危檣白日昏。","已斷燕鴻初起勢，更驚騷客後归魂。","漢廷急詔誰先入，楚路高歌自欲翻。","万里相逢歡复泣，鳳巢西隔九重门。"]', '诗', 'shi', '', NULL, '贈劉司戶 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('deef7ba3-321f-4369-89c6-c537c545e17a', '哭劉司戶二首 一', '哭劉司戶二首 一', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["離居星歲易，失望死生分。","酒甕凝餘桂，書籤冷舊芸。","江風吹鴈急，山木帶蟬曛。","一呌千迴首，天高不爲聞。"]', '["離居星歲易，失望死生分。","酒甕凝餘桂，书籤冷旧芸。","江风吹鴈急，山木带蟬曛。","一呌千迴首，天高不爲闻。"]', '诗', 'shi', '', NULL, '哭劉司戶二首 一 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f90656d1-0400-4f14-a2c7-6bd5d3b43ca1', '哭劉司戶二首 二', '哭劉司戶二首 二', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["有美扶皇運，無誰薦直言。","已爲秦逐客，復作楚冤魂。","湓浦應分派，荆江有會源。","幷將添恨淚，一灑問乾坤。"]', '["有美扶皇運，無誰薦直言。","已爲秦逐客，复作楚冤魂。","湓浦應分派，荆江有會源。","幷將添恨泪，一灑问乾坤。"]', '诗', 'shi', '', NULL, '哭劉司戶二首 二 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41464110-35a8-44f3-bf5c-76ecb6a4c324', '悼傷後赴東蜀辟至散關遇雪', '悼傷後赴东蜀辟至散关遇雪', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["劍外從軍遠，無家與寄衣。","散關三尺雪，回夢舊鴛機。"]', '["劍外從軍远，無家與寄衣。","散关三尺雪，回梦旧鴛機。"]', '诗', 'shi', '', NULL, '悼傷後赴東蜀辟至散關遇雪 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7c6d072-6e84-482e-856a-5a4c21226a3c', '樂遊原', '乐游原', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["向晚意不適，驅車登古原。","夕陽無限好，只是近黃昏。"]', '["向晚意不適，驱车登古原。","夕陽無限好，只是近黄昏。"]', '诗', 'shi', '', NULL, '樂遊原 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf2d420a-183e-4a15-9573-65405bd59c37', '北齊二首 一', '北齊二首 一', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["一笑相傾國便亡，何勞荆棘始堪傷。","小憐玉體橫陳夜，已報周師入晉陽。"]', '["一笑相傾国便亡，何勞荆棘始堪傷。","小怜玉體橫陳夜，已報周師入晉陽。"]', '诗', 'shi', '', NULL, '北齊二首 一 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f664ffbd-72d2-469a-8ea9-38f07e89da32', '北齊二首 二', '北齊二首 二', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["巧笑知堪敵萬幾，傾城最在著戎衣。","晉陽已陷休回顧，更請君王獵一圍。"]', '["巧笑知堪敵万幾，傾城最在著戎衣。","晉陽已陷休回顧，更請君王獵一圍。"]', '诗', 'shi', '', NULL, '北齊二首 二 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9aa6d4de-b69e-4014-8c48-61e78ba8eae8', '街西池館', '街西池館', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["白閣他年別，朱門此夜過。","疎簾留月魄，珍簟接煙波。","太守三刀夢，將軍一箭歌。","國租容客旅，香熟玉山禾。"]', '["白閣他年別，朱门此夜過。","疎簾留月魄，珍簟接煙波。","太守三刀梦，將軍一箭歌。","国租容客旅，香熟玉山禾。"]', '诗', 'shi', '', NULL, '街西池館 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b5ddd79-3af3-4a8b-af40-6518271fd803', '南朝', '南朝', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["玄武湖中玉漏催，雞鳴埭口繡襦迴。","誰言瓊樹朝朝見，不及金蓮步步來。","敵國軍營漂木柹，前朝神廟鎖煙煤。","滿宮學士皆顏色，江令當年只費才。"]', '["玄武湖中玉漏催，雞鳴埭口繡襦迴。","誰言瓊樹朝朝见，不及金蓮步步来。","敵国軍營漂木柹，前朝神廟鎖煙煤。","满宮学士皆顏色，江令當年只費才。"]', '诗', 'shi', '', NULL, '南朝 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd7468ad-47dc-4649-9d6c-ee54a20898e7', '復京', '复京', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["虜騎胡兵一戰摧，萬靈回首賀軒臺。","天教李令心如日，可要昭陵石馬來。"]', '["虜騎胡兵一戰摧，万靈回首賀軒台。","天教李令心如日，可要昭陵石马来。"]', '诗', 'shi', '', NULL, '復京 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b84ef046-ac28-4874-90c8-f47d0a56145d', '渾河中', '渾河中', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["九廟無塵八馬回，奉天城壘長春苔。","咸陽原上英雄骨，半向君家養馬來。"]', '["九廟無塵八马回，奉天城壘长春苔。","咸陽原上英雄骨，半向君家養马来。"]', '诗', 'shi', '', NULL, '渾河中 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c4de9fe-8f11-48c5-9e13-efa389cc9d9b', '鄠杜馬上念漢書', '鄠杜马上念漢书', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["世上蒼龍種，人間武帝孫。","小來惟射獵，興罷得乾坤。","渭水天開苑，咸陽地獻原。","英靈殊未已，丁傅漸華軒。"]', '["世上蒼龙種，人间武帝孫。","小来惟射獵，兴罷得乾坤。","渭水天开苑，咸陽地獻原。","英靈殊未已，丁傅漸华軒。"]', '诗', 'shi', '', NULL, '鄠杜馬上念漢書 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77545bf3-4b59-4497-890b-63bdf574debd', '柳', '柳', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["動春何限葉，撼曉幾多枝。","解有相思[否]，應無不舞時。","絮飛藏皓蝶，帶弱露黃鸝。","傾國宜通體，誰來獨賞眉。"]', '["动春何限葉，撼晓幾多枝。","解有相思[否]，應無不舞时。","絮飞藏皓蝶，带弱露黄鸝。","傾国宜通體，誰来独賞眉。"]', '诗', 'shi', '', NULL, '柳 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c7f0d3e-9a2c-43f0-b16e-09f79d2ac6b9', '巴江柳', '巴江柳', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["巴江可惜柳，柳色綠侵江。","好向金鑾殿，移陰入綺窗。"]', '["巴江可惜柳，柳色綠侵江。","好向金鑾殿，移陰入綺窗。"]', '诗', 'shi', '', NULL, '巴江柳 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c533fae8-97bd-4d1f-bf97-c17b826883b6', '咸陽', '咸陽', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["咸陽宮闕鬱嵯峨，六國樓臺豔綺羅。","自是當時天帝醉，不關秦地有山河。"]', '["咸陽宮闕鬱嵯峨，六国楼台豔綺羅。","自是當时天帝醉，不关秦地有山河。"]', '诗', 'shi', '', NULL, '咸陽 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65831daa-4494-43b4-8405-e162cb81ec73', '同崔八詣藥山訪融禪師', '同崔八詣藥山訪融禪師', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["共受征南不次恩，報恩惟是有忘言。","巖花澗草西林路，未見高僧只見猿。"]', '["共受征南不次恩，報恩惟是有忘言。","巖花澗草西林路，未见高僧只见猿。"]', '诗', 'shi', '', NULL, '同崔八詣藥山訪融禪師 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1061247-281a-49d5-be00-fd15cb352bf5', '聞著明凶問哭寄飛卿', '闻著明凶问哭寄飞卿', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["昔歎讒銷骨，今傷淚滿膺。","空餘雙玉劍，無復一壺冰。","江勢翻銀礫，天文露玉繩。","何因攜庾信，同去哭徐陵。"]', '["昔歎讒銷骨，今傷泪满膺。","空餘雙玉劍，無复一壺冰。","江勢翻銀礫，天文露玉繩。","何因携庾信，同去哭徐陵。"]', '诗', 'shi', '', NULL, '聞著明凶問哭寄飛卿 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('183987da-b8e6-4632-bc8d-8b50a1766ad4', '聽鼓', '听鼓', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["城頭疊鼓聲，城下暮江清。","欲問漁陽摻，時無禰正平。"]', '["城头叠鼓声，城下暮江清。","欲问漁陽摻，时無禰正平。"]', '诗', 'shi', '', NULL, '聽鼓 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c3c5b7a-80f1-42a5-9209-b73263839c10', '送崔珏往西川', '送崔珏往西川', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["年少因何有旅愁，欲爲東下更西遊。","一條雪浪吼巫峽，千里火雲燒益州。","卜肆至今多寂寞，酒壚從古擅風流。","浣花牋紙桃花色，好好題詩詠玉鉤。"]', '["年少因何有旅愁，欲爲东下更西游。","一條雪浪吼巫峽，千里火云燒益州。","卜肆至今多寂寞，酒壚從古擅风流。","浣花牋紙桃花色，好好題诗詠玉鉤。"]', '诗', 'shi', '', NULL, '送崔珏往西川 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec00137e-f391-4173-91b9-725c0644ae64', '代贈', '代贈', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["楊柳路盡處，芙蓉湖上頭。","雖同錦步障，獨映鈿箜篌。","鴛鴦可羨頭俱白，飛去飛來煙雨秋。"]', '["楊柳路尽处，芙蓉湖上头。","雖同錦步障，独映鈿箜篌。","鴛鴦可羨头俱白，飞去飞来煙雨秋。"]', '诗', 'shi', '', NULL, '代贈 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b96fec6-886f-4e98-b144-0ae0e09f5935', '桂林', '桂林', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["城窄山將壓，江寬地共浮。","東南通絕域，西北有高樓。","神護青楓岸，龍移白石湫。","殊鄉竟何禱，簫鼓不曾休。"]', '["城窄山將壓，江寬地共浮。","东南通絕域，西北有高楼。","神護青楓岸，龙移白石湫。","殊乡竟何禱，簫鼓不曾休。"]', '诗', 'shi', '', NULL, '桂林 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75db753d-e7da-48a1-a6c0-6ed9147e58db', '夜雨寄北', '夜雨寄北', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["君問歸期未有期，巴山夜雨漲秋池。","何當共剪西窗燭，却話巴山夜雨時。"]', '["君问归期未有期，巴山夜雨漲秋池。","何當共剪西窗燭，却話巴山夜雨时。"]', '诗', 'shi', '', NULL, '夜雨寄北 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8371f9a-23c9-46f5-babc-19e230bb9ff5', '陳後宮', '陳後宮', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["茂苑城如畫，閶門瓦欲流。","還依水光殿，更起月華樓。","侵夜鸞開鏡，迎冬雉獻裘。","從臣皆半醉，天子正無愁。"]', '["茂苑城如畫，閶门瓦欲流。","還依水光殿，更起月华楼。","侵夜鸾开镜，迎冬雉獻裘。","從臣皆半醉，天子正無愁。"]', '诗', 'shi', '', NULL, '陳後宮 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50ab4770-f08a-4fd7-917a-95087a5886e4', '屬疾', '屬疾', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["許靖猶羈宦，安仁復悼亡。","茲辰聊屬疾，何日免殊方。","秋蝶無端麗，寒花只暫香。","多情真命薄，容易即迴腸。"]', '["許靖猶羈宦，安仁复悼亡。","茲辰聊屬疾，何日免殊方。","秋蝶無端丽，寒花只暫香。","多情真命薄，容易即迴腸。"]', '诗', 'shi', '', NULL, '屬疾 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72aac7c5-766e-476f-b094-a780465c172b', '石榴', '石榴', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["榴枝婀娜榴實繁，榴膜輕明榴子鮮。","可羨瑤池碧桃樹，碧桃紅頰一千年。"]', '["榴枝婀娜榴實繁，榴膜轻明榴子鲜。","可羨瑤池碧桃樹，碧桃紅頰一千年。"]', '诗', 'shi', '', NULL, '石榴 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88f7fe7a-b54f-425c-a071-d3b3f7a3b2f8', '明日', '明日', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["天上參旗過，人間燭燄銷。","誰言整雙履，便是隔三橋。","知處黃金鏁，曾來碧綺寮。","憑欄明日意，池闊雨蕭蕭。"]', '["天上參旗過，人间燭燄銷。","誰言整雙履，便是隔三橋。","知处黄金鏁，曾来碧綺寮。","憑欄明日意，池闊雨蕭蕭。"]', '诗', 'shi', '', NULL, '明日 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a47cdd5d-29e7-4366-ad6a-852c52053894', '飲席戲贈同舍', '饮席戲贈同舍', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["洞中屐響省分攜，不是花迷客自迷。","珠樹重行憐翡翠，玉樓雙舞羨鵾雞。","蘭迴舊蘂緣屏綠，椒綴新香和壁泥。","唱盡陽關無限疊，半杯松葉凍頗黎。"]', '["洞中屐响省分携，不是花迷客自迷。","珠樹重行怜翡翠，玉楼雙舞羨鵾雞。","蘭迴旧蘂緣屏綠，椒綴新香和壁泥。","唱尽陽关無限叠，半杯松葉凍頗黎。"]', '诗', 'shi', '', NULL, '飲席戲贈同舍 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a05d50d-c871-46d7-be27-7e2c2cf9cc09', '西溪', '西溪', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["近郭西溪好，誰堪共酒壺。","苦吟防柳惲，多淚怯楊朱。","野鶴隨君子，寒松揖大夫。","天涯常病意，岑寂勝歡娛。"]', '["近郭西溪好，誰堪共酒壺。","苦吟防柳惲，多泪怯楊朱。","野鹤隨君子，寒松揖大夫。","天涯常病意，岑寂勝歡娛。"]', '诗', 'shi', '', NULL, '西溪 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5f86a2d-85f1-4c90-b963-adf541dc98a4', '憶梅', '憶梅', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["定定住天涯，依依向物華。","寒梅最堪恨，常作去年花。"]', '["定定住天涯，依依向物华。","寒梅最堪恨，常作去年花。"]', '诗', 'shi', '', NULL, '憶梅 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3294466-f013-45b2-ac51-bfebf036fd0c', '贈柳', '贈柳', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["章臺從掩映，郢路更參差。","見說風流極，來當婀娜時。","橋迴行欲斷，隄遠意相隨。","忍放花如雪，青樓撲酒旗。"]', '["章台從掩映，郢路更參差。","见说风流極，来當婀娜时。","橋迴行欲斷，隄远意相隨。","忍放花如雪，青楼撲酒旗。"]', '诗', 'shi', '', NULL, '贈柳 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a82a392-7715-49fb-8535-7c6293195bf5', '謔柳', '謔柳', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["已帶黃金縷，仍飛白玉花。","長時須拂馬，密處少藏鴉。","眉細從他斂，腰輕莫自斜。","玳梁誰道好，偏擬映盧家。"]', '["已带黄金縷，仍飞白玉花。","长时須拂马，密处少藏鴉。","眉細從他斂，腰轻莫自斜。","玳梁誰道好，偏擬映盧家。"]', '诗', 'shi', '', NULL, '謔柳 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca9041ae-c4a9-4e2d-954f-3c54eac4d399', '北禽', '北禽', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["爲戀巴江好，無辭瘴霧蒸。","縱能朝杜宇，可得值蒼鷹。","石小虛填海，蘆銛未破矰。"]', '["爲戀巴江好，無辞瘴霧蒸。","縱能朝杜宇，可得值蒼鷹。","石小虛填海，蘆銛未破矰。"]', '诗', 'shi', '', NULL, '北禽 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39d4f078-6426-4c54-a98d-a982a3c7512d', '初起', '初起', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["想像咸池日欲光，五更鐘後更迴腸。","三年苦霧巴江水，不爲離人照屋梁。"]', '["想像咸池日欲光，五更鐘後更迴腸。","三年苦霧巴江水，不爲離人照屋梁。"]', '诗', 'shi', '', NULL, '初起 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('deb5d0c9-3679-4270-9984-c18a3e262827', '楚宮', '楚宮', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["複壁交青瑣，重簾挂紫繩。","如何一柱觀，不礙九枝燈。","扇薄常規月，釵斜只鏤冰。","歌成猶未唱，秦火入夷陵。"]', '["複壁交青瑣，重簾挂紫繩。","如何一柱观，不礙九枝灯。","扇薄常規月，釵斜只鏤冰。","歌成猶未唱，秦火入夷陵。"]', '诗', 'shi', '', NULL, '楚宮 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7fd23d94-707f-4553-afe4-84228157bbab', '柳', '柳', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["柳映江潭底有情，望中頻遣客心驚。","巴雷隱隱千山外，更作章臺走馬聲。"]', '["柳映江潭底有情，望中頻遣客心驚。","巴雷隐隐千山外，更作章台走马声。"]', '诗', 'shi', '', NULL, '柳 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6028db2f-bac8-432c-a0c1-edf7fe69b567', '石城', '石城', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["石城誇窈窕，花縣更風流。","簟冰將飄枕，簾烘不隱鉤。","玉童收夜鑰，金狄守更籌。","共笑鴛鴦綺，鴛鴦兩白頭。"]', '["石城誇窈窕，花縣更风流。","簟冰將飄枕，簾烘不隐鉤。","玉童收夜鑰，金狄守更籌。","共笑鴛鴦綺，鴛鴦兩白头。"]', '诗', 'shi', '', NULL, '石城 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d2c5fba-d350-4c3f-b55e-72a491a84df6', '韓碑', '韓碑', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["元和天子神武姿，彼何人哉軒與羲。","誓將上雪列聖恥，坐法宮中朝四夷。","淮西有賊五十載，封狼生貙貙生羆。","不據山河據平地，長戈利矛日可麾。","帝得聖相相曰度，賊斫不死神扶持。","腰懸相印作都統，陰風慘澹天王旗。","愬武古通作牙爪，儀曹外郎載筆隨。","行軍司馬智且勇，十四萬衆猶虎貔。","入蔡縛賊獻太廟，功無與讓恩不訾。","帝曰汝度功第一，汝從事愈宜爲辭。","愈拜稽首蹈且舞，金石刻畫臣能爲。","古者世稱大手筆，此事不繫于職司。","當仁自古有不讓，言訖屢頷天子頤。","公退齋戒坐小閣，濡染大筆何淋漓。","點竄堯典舜典字，塗改清廟生民詩。","文成破體書在紙，清晨再拜鋪丹墀。","表曰臣愈昧死上，詠神聖功書之碑。","碑高三丈字如斗，負以靈鼇蟠以螭。","句奇語重喻者少，讒之天子言其私。","長繩百尺拽碑倒，麤砂大石相磨治。","公之斯文若元氣，先時已入人肝脾。","湯盤孔鼎有述作，今無其器存其辭。","嗚呼聖皇及聖相，相與烜赫流淳熙。","公之斯文不示後，曷與三五相攀追。","願書萬本誦萬過，口角流沫右手胝。","傳之七十有二代，以爲封禪玉檢明堂基。"]', '["元和天子神武姿，彼何人哉軒與羲。","誓將上雪列聖恥，坐法宮中朝四夷。","淮西有賊五十載，封狼生貙貙生羆。","不據山河據平地，长戈利矛日可麾。","帝得聖相相曰度，賊斫不死神扶持。","腰懸相印作都統，陰风慘澹天王旗。","愬武古通作牙爪，儀曹外郎載笔隨。","行軍司马智且勇，十四万衆猶虎貔。","入蔡縛賊獻太廟，功無與讓恩不訾。","帝曰汝度功第一，汝從事愈宜爲辞。","愈拜稽首蹈且舞，金石刻畫臣能爲。","古者世稱大手笔，此事不繫于職司。","當仁自古有不讓，言訖屢頷天子頤。","公退斋戒坐小閣，濡染大笔何淋漓。","点竄堯典舜典字，塗改清廟生民诗。","文成破體书在紙，清晨再拜鋪丹墀。","表曰臣愈昧死上，詠神聖功书之碑。","碑高三丈字如斗，負以靈鼇蟠以螭。","句奇語重喻者少，讒之天子言其私。","长繩百尺拽碑倒，麤砂大石相磨治。","公之斯文若元氣，先时已入人肝脾。","湯盤孔鼎有述作，今無其器存其辞。","嗚呼聖皇及聖相，相與烜赫流淳熙。","公之斯文不示後，曷與三五相攀追。","願书万本誦万過，口角流沫右手胝。","傳之七十有二代，以爲封禪玉檢明堂基。"]', '诗', 'shi', '', NULL, '韓碑 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c16d46f-edbd-423e-a3b1-c6e361ac7b9d', '令狐八拾遺見招送裴十四歸華州', '令狐八拾遺见招送裴十四归华州', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["二十中郎未足希，驪駒先自有光輝。","蘭亭讌罷方回去，雪夜詩成道韞歸。","漢苑風煙吹客夢，雲臺洞穴接郊扉。","嗟予久抱臨邛渴，便欲因君問釣磯。"]', '["二十中郎未足希，驪駒先自有光輝。","蘭亭讌罷方回去，雪夜诗成道韞归。","漢苑风煙吹客梦，云台洞穴接郊扉。","嗟予久抱臨邛渴，便欲因君问釣磯。"]', '诗', 'shi', '', NULL, '令狐八拾遺見招送裴十四歸華州 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4c68770-d2b0-4281-b4e9-e9fbe7ff7a56', '離思', '離思', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["氣盡前溪舞，心酸子夜歌。","峽雲尋不得，溝水欲如何。","朔雁傳書絕，湘篁染淚多。","無由見顏色，還自託微波。"]', '["氣尽前溪舞，心酸子夜歌。","峽云尋不得，溝水欲如何。","朔雁傳书絕，湘篁染泪多。","無由见顏色，還自託微波。"]', '诗', 'shi', '', NULL, '離思 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d538dace-1398-4b98-ba44-600d6168de07', '宿駱氏亭寄懷崔雍衮', '宿駱氏亭寄懷崔雍衮', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["竹塢無塵水檻清，相思迢遞隔重城。","秋陰不散霜飛晚，留得枯荷聽雨聲。"]', '["竹塢無塵水檻清，相思迢遞隔重城。","秋陰不散霜飞晚，留得枯荷听雨声。"]', '诗', 'shi', '', NULL, '宿駱氏亭寄懷崔雍衮 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d32a2610-09d7-49ad-8cdf-dd9c649144c7', '風雨', '风雨', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["淒涼寶劍篇，羈泊欲窮年。","黃葉仍風雨，青樓自管絃。","新知遭薄俗，舊好隔良緣。","心斷新豐酒，銷愁斗幾千。"]', '["淒涼寶劍篇，羈泊欲窮年。","黄葉仍风雨，青楼自管絃。","新知遭薄俗，旧好隔良緣。","心斷新豐酒，銷愁斗幾千。"]', '诗', 'shi', '', NULL, '風雨 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81bb84d2-9d4a-45d1-bd40-1858c9993f7d', '夢澤', '梦澤', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["夢澤悲風動白茅，楚王葬盡滿城嬌。","未知歌舞能多少，虛減宮廚爲細腰。"]', '["梦澤悲风动白茅，楚王葬尽满城嬌。","未知歌舞能多少，虛減宮廚爲細腰。"]', '诗', 'shi', '', NULL, '夢澤 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('166e4c58-3443-49c1-8201-2f0f3de2af8e', '贈歌妓二首 一', '贈歌妓二首 一', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["水精如意玉連環，下蔡城危莫破顏。","紅綻櫻桃含白雪，斷腸聲裏唱陽關。"]', '["水精如意玉連环，下蔡城危莫破顏。","紅綻櫻桃含白雪，斷腸声裏唱陽关。"]', '诗', 'shi', '', NULL, '贈歌妓二首 一 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d37e138e-e4e4-4e18-a3e8-25584c54c5aa', '贈歌妓二首 二', '贈歌妓二首 二', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["白日相思可奈何，嚴城清夜斷經過。","只知解道春來瘦，不道春來獨自多。"]', '["白日相思可奈何，嚴城清夜斷經過。","只知解道春来瘦，不道春来独自多。"]', '诗', 'shi', '', NULL, '贈歌妓二首 二 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fa747cb-4f5d-4181-ade8-2e89cc0a71d5', '謝書', '謝书', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["微意何曾有一毫，空攜筆硯奉龍韜。","自蒙半夜傳衣後，不羨王祥得佩刀。"]', '["微意何曾有一毫，空携笔硯奉龙韜。","自蒙半夜傳衣後，不羨王祥得佩刀。"]', '诗', 'shi', '', NULL, '謝書 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90b38fe6-b5ab-4031-94e4-b73a877a61fc', '寄令狐學士', '寄令狐学士', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["秘殿崔嵬拂彩霓，曹司今在殿東西。","賡歌太液翻黃鵠，從獵陳倉獲碧雞。","曉飲豈知金掌迥，夜吟應訝玉繩低。","鈞天雖許人間聽，閶闔門多夢自迷。"]', '["秘殿崔嵬拂彩霓，曹司今在殿东西。","賡歌太液翻黄鵠，從獵陳倉獲碧雞。","晓饮豈知金掌迥，夜吟應訝玉繩低。","鈞天雖許人间听，閶闔门多梦自迷。"]', '诗', 'shi', '', NULL, '寄令狐學士 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbb31c57-4c0d-4dc1-9e10-399ae6e9b74c', '酬令狐郎中見寄', '酬令狐郎中见寄', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["望郎臨古郡，佳句灑丹青。","應自丘遲宅，仍過柳惲汀。","封來江渺渺，信去雨冥冥。","句曲聞仙訣，臨川得佛經。","朝吟搘客枕，夜讀漱僧瓶。","不見銜蘆雁，空流腐草螢。","土宜悲坎井，天怒識雷霆。","象卉分疆近，蛟涎浸岸腥。","補羸貪紫桂，負氣託青萍。","萬里懸離抱，危於訟閤鈴。"]', '["望郎臨古郡，佳句灑丹青。","應自丘遲宅，仍過柳惲汀。","封来江渺渺，信去雨冥冥。","句曲闻仙訣，臨川得佛經。","朝吟搘客枕，夜读漱僧瓶。","不见銜蘆雁，空流腐草螢。","土宜悲坎井，天怒識雷霆。","象卉分疆近，蛟涎浸岸腥。","補羸貪紫桂，負氣託青萍。","万里懸離抱，危於訟閤鈴。"]', '诗', 'shi', '', NULL, '酬令狐郎中見寄 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8291b5d8-531d-4eed-9175-3da19e4e3093', '七月二十八日夜與王鄭二秀才聽雨後夢作', '七月二十八日夜與王鄭二秀才听雨後梦作', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["初夢龍宮寶燄然，瑞霞明麗滿晴天。","旋成醉倚蓬萊樹，有箇仙人拍我肩。","少頃遠聞吹細管，聞聲不見隔飛煙。","逡巡又過瀟湘雨，雨打湘靈五十絃。","瞥見馮夷殊悵望，鮫綃休賣海爲田。","亦逢毛女無憀極，龍伯擎將華嶽蓮。","恍惚無倪明又暗，低迷不已斷還連。","覺來正是平階雨，獨背寒燈枕手眠。"]', '["初梦龙宮寶燄然，瑞霞明丽满晴天。","旋成醉倚蓬萊樹，有箇仙人拍我肩。","少頃远闻吹細管，闻声不见隔飞煙。","逡巡又過瀟湘雨，雨打湘靈五十絃。","瞥见馮夷殊悵望，鮫綃休賣海爲田。","亦逢毛女無憀極，龙伯擎將华嶽蓮。","恍惚無倪明又暗，低迷不已斷還連。","覺来正是平階雨，独背寒灯枕手眠。"]', '诗', 'shi', '', NULL, '七月二十八日夜與王鄭二秀才聽雨後夢作 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb376b71-91c6-44ee-b2e4-40f5b3f71b8f', '寄令狐郎中', '寄令狐郎中', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["嵩雲秦樹久離居，雙鯉迢迢一紙書。","休問梁園舊賓客，茂陵秋雨病相如。"]', '["嵩云秦樹久離居，雙鯉迢迢一紙书。","休问梁园旧賓客，茂陵秋雨病相如。"]', '诗', 'shi', '', NULL, '寄令狐郎中 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b4440f8-f452-4515-b766-be813d27871e', '漫成三首 一', '漫成三首 一', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["不妨何范盡詩家，未解當年重物華。","遠把龍山千里雪，將來擬並洛陽花。"]', '["不妨何范尽诗家，未解當年重物华。","远把龙山千里雪，將来擬並洛陽花。"]', '诗', 'shi', '', NULL, '漫成三首 一 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfacd1bc-7db5-42df-ad78-b14662f81cff', '漫成三首 二', '漫成三首 二', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["沈約憐何遜，延年毀謝莊。","清新俱有得，名譽底相傷。"]', '["沈約怜何遜，延年毀謝莊。","清新俱有得，名譽底相傷。"]', '诗', 'shi', '', NULL, '漫成三首 二 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6084bd4e-86bd-4d2f-8e34-d6db2b74b8ef', '漫成三首 三', '漫成三首 三', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["霧夕詠芙蕖，何郎得意初。","此時誰最賞，沈范兩尚書。"]', '["霧夕詠芙蕖，何郎得意初。","此时誰最賞，沈范兩尚书。"]', '诗', 'shi', '', NULL, '漫成三首 三 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a808938-d03b-48b2-a4b8-6015ad7b6bc1', '無題', '無題', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["白道縈迴入暮霞，斑騅嘶斷七香車。","春風自共何人笑，枉破陽城十萬家。"]', '["白道縈迴入暮霞，斑騅嘶斷七香车。","春风自共何人笑，枉破陽城十万家。"]', '诗', 'shi', '', NULL, '無題 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7dd62de1-8821-4c7f-9359-c572fd6f82e6', '槿花二首 一', '槿花二首 一', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["燕體傷風力，雞香積露文。","殷鮮一相雜，啼笑兩難分。","月裏寧無姊，雲中亦有君。","三清與仙島，何事亦離羣。"]', '["燕體傷风力，雞香積露文。","殷鲜一相杂，啼笑兩难分。","月裏寧無姊，云中亦有君。","三清與仙島，何事亦離羣。"]', '诗', 'shi', '', NULL, '槿花二首 一 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9538622b-0e41-4daf-be20-403a90d37cc2', '槿花二首 二', '槿花二首 二', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["珠館薰燃久，玉房梳掃餘。","燒蘭才作燭，襞錦不成書。","本以亭亭遠，翻嫌眽眽疎。","迴頭問殘照，殘照更空虛。"]', '["珠館薰燃久，玉房梳掃餘。","燒蘭才作燭，襞錦不成书。","本以亭亭远，翻嫌眽眽疎。","迴头问殘照，殘照更空虛。"]', '诗', 'shi', '', NULL, '槿花二首 二 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1459406-b1e8-4e70-a81a-db84b302a560', '哭劉蕡', '哭劉蕡', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["上帝深宮閉九閽，巫咸不下問銜冤。","廣陵別後春濤隔，湓浦書來秋雨翻。","只有安仁能作誄，何曾宋玉解招魂。","平生風義兼師友，不敢同君哭寢門。"]', '["上帝深宮閉九閽，巫咸不下问銜冤。","廣陵別後春濤隔，湓浦书来秋雨翻。","只有安仁能作誄，何曾宋玉解招魂。","平生风義兼師友，不敢同君哭寢门。"]', '诗', 'shi', '', NULL, '哭劉蕡 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2af162e-d81f-4e16-9ffb-41e2a1514aa3', '杜司勳', '杜司勳', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["高樓風雨感斯文，短翼差池不及羣。","刻意傷春復傷別，人間惟有杜司勳。"]', '["高楼风雨感斯文，短翼差池不及羣。","刻意傷春复傷別，人间惟有杜司勳。"]', '诗', 'shi', '', NULL, '杜司勳 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ae5d09e-62e1-4183-9e12-002e80b027bf', '荆門西下', '荆门西下', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["一夕南風一葉危，荆雲迴望夏雲時。","人生豈得輕離別，天意何曾忌嶮巇。","骨肉書題安絕徼，蕙蘭蹊徑失佳期。","洞庭湖闊蛟龍惡，却羨楊朱泣路岐。"]', '["一夕南风一葉危，荆云迴望夏云时。","人生豈得轻離別，天意何曾忌嶮巇。","骨肉书題安絕徼，蕙蘭蹊徑失佳期。","洞庭湖闊蛟龙惡，却羨楊朱泣路岐。"]', '诗', 'shi', '', NULL, '荆門西下 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('358c2152-ac78-4747-b30c-18d21cd2d10c', '碧瓦', '碧瓦', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["碧瓦銜珠樹，紅輪結綺寮。","無雙漢殿鬢，第一楚宮腰。","霧唾香難盡，珠啼冷易銷。","歌從雍門學，酒是蜀城燒。","柳暗將翻巷，荷欹正抱橋。","鈿轅開道入，金管隔隣調。","夢到飛魂急，書成即席遙。","河流衝柱轉，海沫近槎飄。","吳市蠀蛦甲，巴賨翡翠翹。","他時未知意，重疊贈嬌饒。"]', '["碧瓦銜珠樹，紅輪結綺寮。","無雙漢殿鬢，第一楚宮腰。","霧唾香难尽，珠啼冷易銷。","歌從雍门学，酒是蜀城燒。","柳暗將翻巷，荷欹正抱橋。","鈿轅开道入，金管隔隣調。","梦到飞魂急，书成即席遙。","河流衝柱轉，海沫近槎飄。","吳市蠀蛦甲，巴賨翡翠翹。","他时未知意，重叠贈嬌饒。"]', '诗', 'shi', '', NULL, '碧瓦 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14f75f94-3c45-4442-9c18-339af0b9ac97', '蜨', '蜨', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["葉葉復翻翻，斜橋對側門。","蘆花惟有白，柳絮可能溫。","西子尋遺殿，昭君覓故村。","年年芳物盡，來別敗蘭蓀。"]', '["葉葉复翻翻，斜橋对側门。","蘆花惟有白，柳絮可能溫。","西子尋遺殿，昭君覓故村。","年年芳物尽，来別敗蘭蓀。"]', '诗', 'shi', '', NULL, '蜨 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e96cddef-b91e-4ed1-b460-b3c9073a6ae8', '蠅蜨雞麝鷥鳳等成篇', '蠅蜨雞麝鷥鳳等成篇', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["韓蝶翻羅幕，曹蠅拂綺窗。","鬬雞迴玉勒，融麝暖金釭。","瑇瑁明書閣，琉璃冰酒缸。","畫樓多有主，鸞鳳各雙雙。"]', '["韓蝶翻羅幕，曹蠅拂綺窗。","鬬雞迴玉勒，融麝暖金釭。","瑇瑁明书閣，琉璃冰酒缸。","畫楼多有主，鸾鳳各雙雙。"]', '诗', 'shi', '', NULL, '蠅蜨雞麝鷥鳳等成篇 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ac3275e-34f6-4e38-a35f-67c350ecc677', '韓翃舍人即事', '韓翃舍人即事', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["萱草含丹粉，荷花抱綠房。","鳥應悲蜀帝，蟬是怨齊王。","通內藏珠府，應官解玉坊。","橋南荀令過，十里送衣香。"]', '["萱草含丹粉，荷花抱綠房。","鸟應悲蜀帝，蟬是怨齊王。","通內藏珠府，應官解玉坊。","橋南荀令過，十里送衣香。"]', '诗', 'shi', '', NULL, '韓翃舍人即事 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb9addd7-7a3c-446f-9e2b-a3b3bf05c3b1', '公子', '公子', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["一盞新羅酒，凌晨恐易消。","歸應衝鼓半，去不待笙調。","歌好惟愁和，香濃豈惜飄。","春場鋪艾帳，下馬雉媒嬌。"]', '["一盞新羅酒，凌晨恐易消。","归應衝鼓半，去不待笙調。","歌好惟愁和，香濃豈惜飄。","春場鋪艾帳，下马雉媒嬌。"]', '诗', 'shi', '', NULL, '公子 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72b042b5-0353-4304-b8e0-09356bf98d93', '子初全溪作', '子初全溪作', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["全溪不可到，況復盡餘醅。","漢苑生春水，昆池換劫灰。","戰蒲知雁唼，皺月覺魚來。","清興恭聞命，言詩未敢迴。"]', '["全溪不可到，況复尽餘醅。","漢苑生春水，昆池換劫灰。","戰蒲知雁唼，皺月覺鱼来。","清兴恭闻命，言诗未敢迴。"]', '诗', 'shi', '', NULL, '子初全溪作 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b6adc4d-ba8f-43c4-867a-a256ebfdfe55', '楊本勝說於長安見小男阿衮', '楊本勝说於长安见小男阿衮', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["聞君來日下，見我最嬌兒。","漸大啼應數，長貧學恐遲。","寄人龍種瘦，失母鳳雛癡。","語罷休邊角，青燈兩鬢絲。"]', '["闻君来日下，见我最嬌兒。","漸大啼應數，长貧学恐遲。","寄人龙種瘦，失母鳳雛癡。","語罷休邊角，青灯兩鬢絲。"]', '诗', 'shi', '', NULL, '楊本勝說於長安見小男阿衮 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35bca1b9-9185-4d49-ac39-58b2962b358e', '西溪', '西溪', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["悵望西溪水，潺湲奈爾何。","不驚春物少，只覺夕陽多。","色染妖韶柳，光含窈窕蘿。","人間從到海，天上莫爲河。","鳳女彈瑤瑟，龍孫撼玉珂。","京華他夜夢，好好寄雲波。"]', '["悵望西溪水，潺湲奈爾何。","不驚春物少，只覺夕陽多。","色染妖韶柳，光含窈窕蘿。","人间從到海，天上莫爲河。","鳳女彈瑤瑟，龙孫撼玉珂。","京华他夜梦，好好寄云波。"]', '诗', 'shi', '', NULL, '西溪 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f6c36a5-b2a0-4a77-9c2d-a59e95a8cdc5', '柳下暗記', '柳下暗記', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["無奈巴南柳，千條傍吹臺。","更將黃映白，擬作杏花媒。"]', '["無奈巴南柳，千條傍吹台。","更將黄映白，擬作杏花媒。"]', '诗', 'shi', '', NULL, '柳下暗記 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1db4154b-fe66-40d4-8934-0caded561716', '妓席', '妓席', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["樂府聞桃葉，人前道得無。","勸君書小字，慎莫喚官奴。"]', '["乐府闻桃葉，人前道得無。","勸君书小字，慎莫喚官奴。"]', '诗', 'shi', '', NULL, '妓席 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9df0a61d-7466-4b2e-92dc-221dc07aebf4', '少年', '少年', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["外戚平羌第一功，生年二十有重封。","直登宣室螭頭上，橫過干泉豹尾中。","別館覺來雲雨夢，後門歸去蕙蘭叢。","灞陵夜獵隨田竇，不識寒郊自轉蓬。"]', '["外戚平羌第一功，生年二十有重封。","直登宣室螭头上，橫過干泉豹尾中。","別館覺来云雨梦，後门归去蕙蘭叢。","灞陵夜獵隨田竇，不識寒郊自轉蓬。"]', '诗', 'shi', '', NULL, '少年 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac26dd32-e1c4-4b9c-a040-a6e88db2cbe8', '無題', '無題', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["近知名阿侯，住處小江流。","腰細不勝舞，眉長惟是愁。","黄金堪作屋，何不作重樓。"]', '["近知名阿侯，住处小江流。","腰細不勝舞，眉长惟是愁。","黄金堪作屋，何不作重楼。"]', '诗', 'shi', '', NULL, '無題 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b559d48f-5a6a-4359-85fd-f0eede83005f', '玄微先生', '玄微先生', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["仙翁無定數，時入一壺藏。","夜夜桂露濕，村村桃水香。","醉中拋浩劫，宿處起神光。","藥裹丹山鳳，碁函白石郎。","弄河移砥柱，吞日倚扶桑。","龍竹裁輕策，鮫綃熨下裳。","樹栽嗤漢帝，橋扳笑秦王。","徑欲隨關令，龍沙萬里強。"]', '["仙翁無定數，时入一壺藏。","夜夜桂露濕，村村桃水香。","醉中拋浩劫，宿处起神光。","藥裹丹山鳳，碁函白石郎。","弄河移砥柱，吞日倚扶桑。","龙竹裁轻策，鮫綃熨下裳。","樹栽嗤漢帝，橋扳笑秦王。","徑欲隨关令，龙沙万里強。"]', '诗', 'shi', '', NULL, '玄微先生 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb945404-b9b7-4c4b-ae91-d65b5e2eebaf', '藥轉', '藥轉', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["鬱金堂北畫樓東，換骨神方上藥通。","露氣暗連青桂苑，風聲偏獵紫蘭叢。","長籌未必輸孫皓，香棗何勞問石崇。","憶事懷人兼得句，翠衾歸臥繡簾中。"]', '["鬱金堂北畫楼东，換骨神方上藥通。","露氣暗連青桂苑，风声偏獵紫蘭叢。","长籌未必輸孫皓，香棗何勞问石崇。","憶事懷人兼得句，翠衾归臥繡簾中。"]', '诗', 'shi', '', NULL, '藥轉 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adbed253-25b4-4bea-9f8d-52da370d9218', '岳陽樓', '岳陽楼', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["欲爲平生一散愁，洞庭湖上岳陽樓。","可憐萬里堪乘興，枉是蛟龍解覆舟。"]', '["欲爲平生一散愁，洞庭湖上岳陽楼。","可怜万里堪乘兴，枉是蛟龙解覆舟。"]', '诗', 'shi', '', NULL, '岳陽樓 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('398af96c-8c59-4614-b859-5a3205bbb40a', '寄成都高苗二從事', '寄成都高苗二從事', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["家近紅蕖曲水濱，全家羅襪起秋塵。","莫將越客千絲網，網得西施別贈人。"]', '["家近紅蕖曲水濱，全家羅襪起秋塵。","莫將越客千絲網，網得西施別贈人。"]', '诗', 'shi', '', NULL, '寄成都高苗二從事 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a8163d9-7f52-40a9-ab0f-6bcc125e3d48', '岳陽樓', '岳陽楼', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["漢水方城帶百蠻，四隣誰道亂周班。","如何一夢高唐雨，自此無心入武關。"]', '["漢水方城带百蠻，四隣誰道亂周班。","如何一梦高唐雨，自此無心入武关。"]', '诗', 'shi', '', NULL, '岳陽樓 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b490e3c6-ee9e-4aa3-9575-a01e4bca22c1', '越燕二首 一', '越燕二首 一', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["上國社方見，此鄉秋不歸。","爲矜皇后舞，猶著羽人衣。","拂水斜紋亂，銜花片影微。","盧家文杏好，試近莫愁飛。"]', '["上国社方见，此乡秋不归。","爲矜皇后舞，猶著羽人衣。","拂水斜紋亂，銜花片影微。","盧家文杏好，試近莫愁飞。"]', '诗', 'shi', '', NULL, '越燕二首 一 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3c25a75-6445-47e0-a5ae-265559f9f990', '越燕二首 二', '越燕二首 二', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["將泥紅蓼岸，得草綠楊村。","命侶添新意，安巢復舊痕。","去應逢阿母，來莫害王孫。","記取丹山鳳，今爲百鳥尊。"]', '["將泥紅蓼岸，得草綠楊村。","命侶添新意，安巢复旧痕。","去應逢阿母，来莫害王孫。","記取丹山鳳，今爲百鸟尊。"]', '诗', 'shi', '', NULL, '越燕二首 二 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d82417b-95c8-48a8-a026-18fc4e2842f4', '杜工部蜀中離席', '杜工部蜀中離席', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["人生何處不離羣，世路干戈惜暫分。","雪嶺未歸天外使，松州猶駐殿前軍。","座中醉客延醒客，江上晴雲雜雨雲。","美酒成都堪送老，當壚仍是卓文君。"]', '["人生何处不離羣，世路干戈惜暫分。","雪嶺未归天外使，松州猶駐殿前軍。","座中醉客延醒客，江上晴云杂雨云。","美酒成都堪送老，當壚仍是卓文君。"]', '诗', 'shi', '', NULL, '杜工部蜀中離席 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('670009c2-a701-4140-aa31-b4973f76d632', '隋宮', '隋宮', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["紫泉宮殿鎖煙霞，欲取蕪城作帝家。","玉璽不緣歸日角，錦帆應是到天涯。","于今腐草無螢火，終古垂楊有暮鴉。","地下若逢陳後主，豈宜重問後庭花。"]', '["紫泉宮殿鎖煙霞，欲取蕪城作帝家。","玉璽不緣归日角，錦帆應是到天涯。","于今腐草無螢火，終古垂楊有暮鴉。","地下若逢陳後主，豈宜重问後庭花。"]', '诗', 'shi', '', NULL, '隋宮 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c73c112-1a3d-4408-ae4f-dba739d0bf7a', '二月二日', '二月二日', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["二月二日江上行，東風日暖聞吹笙。","花鬚柳眼各無賴，紫蝶黃蜂俱有情。","萬里憶歸元亮井，三年從事亞夫營。","新灘莫悟遊人意，更作風簷夜雨聲。"]', '["二月二日江上行，东风日暖闻吹笙。","花鬚柳眼各無賴，紫蝶黄蜂俱有情。","万里憶归元亮井，三年從事亞夫營。","新灘莫悟游人意，更作风簷夜雨声。"]', '诗', 'shi', '', NULL, '二月二日 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('131c9f87-273f-4684-9b67-bd7b58ad4008', '籌筆驛', '籌笔驛', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["猿鳥猶疑畏簡書，風雲常爲護儲胥。","徒令上將揮神筆，終見降王走傳車。","管樂有才終不忝，關張無命欲何如。","他年錦里經祠廟，梁父吟成恨有餘。"]', '["猿鸟猶疑畏簡书，风云常爲護儲胥。","徒令上將揮神笔，終见降王走傳车。","管乐有才終不忝，关張無命欲何如。","他年錦里經祠廟，梁父吟成恨有餘。"]', '诗', 'shi', '', NULL, '籌筆驛 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3caf535b-7cdd-40bb-8d50-9b25cb6831a8', '屏風', '屏风', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["六曲連環接翠帷，高樓半夜酒醒時。","掩燈遮霧密如此，雨落月明俱不知。"]', '["六曲連环接翠帷，高楼半夜酒醒时。","掩灯遮霧密如此，雨落月明俱不知。"]', '诗', 'shi', '', NULL, '屏風 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0b2be49-3f48-48c4-9e8a-43ec3dd42a36', '春日', '春日', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["欲入盧家白玉堂，新春催破舞衣裳。","蝶銜紅蘂蜂銜粉，共助青樓一日忙。"]', '["欲入盧家白玉堂，新春催破舞衣裳。","蝶銜紅蘂蜂銜粉，共助青楼一日忙。"]', '诗', 'shi', '', NULL, '春日 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e525ae0b-4ca6-4a73-b50b-b703fab31cf5', '武侯廟古柏', '武侯廟古柏', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["蜀相階前柏，龍蛇捧閟宮。","陰成外江畔，老向惠陵東。","大樹思馮異，甘棠憶召公。","葉凋湘燕雨，枝拆海鵬風。","玉壘經綸遠，金刀歷數終。","誰將出師表，一爲問昭融。"]', '["蜀相階前柏，龙蛇捧閟宮。","陰成外江畔，老向惠陵东。","大樹思馮異，甘棠憶召公。","葉凋湘燕雨，枝拆海鵬风。","玉壘經綸远，金刀歷數終。","誰將出師表，一爲问昭融。"]', '诗', 'shi', '', NULL, '武侯廟古柏 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d80def6-d6de-4742-83e5-e5faef51cdcd', '風', '风', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["撩釵盤孔雀，惱帶拂鴛鴦。","蘿薦誰教近，齋時鎖洞房。"]', '["撩釵盤孔雀，惱带拂鴛鴦。","蘿薦誰教近，斋时鎖洞房。"]', '诗', 'shi', '', NULL, '風 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('602939e3-7d7a-4513-8351-57542a010c1b', '即日', '即日', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["一歲林花即日休，江間亭下悵淹留。","重吟細把真無奈，已落猶開未放愁。","山色正來銜小苑，春陰只欲傍高樓。","金鞍忽散銀壺漏，更醉誰家白玉鉤。"]', '["一歲林花即日休，江间亭下悵淹留。","重吟細把真無奈，已落猶开未放愁。","山色正来銜小苑，春陰只欲傍高楼。","金鞍忽散銀壺漏，更醉誰家白玉鉤。"]', '诗', 'shi', '', NULL, '即日 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87beeed5-93f8-4ac6-a8e0-6bc7e42957c2', '九成宮', '九成宮', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["十二層城閬苑西，平時避暑拂虹霓。","雲隨夏后雙龍尾，風逐周王八駿蹄。","吳岳曉光連翠巘，甘泉晚景上丹梯。","荔枝盧橘沾恩幸，鸞鵲天書濕紫泥。"]', '["十二層城閬苑西，平时避暑拂虹霓。","云隨夏后雙龙尾，风逐周王八駿蹄。","吳岳晓光連翠巘，甘泉晚景上丹梯。","荔枝盧橘沾恩幸，鸾鵲天书濕紫泥。"]', '诗', 'shi', '', NULL, '九成宮 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84119cd7-ee93-4fb0-b56a-ab630f224665', '少將', '少將', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["族亞齊安陸，風高漢武威。","煙波別墅醉，花月後門歸。","青海聞傳箭，天山報合圍。","一朝攜劍起，上馬即如飛。"]', '["族亞齊安陸，风高漢武威。","煙波別墅醉，花月後门归。","青海闻傳箭，天山報合圍。","一朝携劍起，上马即如飞。"]', '诗', 'shi', '', NULL, '少將 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04da453a-1a99-4019-ab79-410a591fc650', '詠史', '詠史', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["歷覽前賢國與家，成由勤儉破由奢。","何須琥珀方爲枕，豈得真珠始是車。","運去不逢青海馬，力窮難拔蜀山蛇。","幾人曾預南薰曲，終古蒼梧哭翠華。"]', '["歷覽前賢国與家，成由勤儉破由奢。","何須琥珀方爲枕，豈得真珠始是车。","運去不逢青海马，力窮难拔蜀山蛇。","幾人曾預南薰曲，終古蒼梧哭翠华。"]', '诗', 'shi', '', NULL, '詠史 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55c9cbab-ff67-47db-9d3c-d9b7e6fe2495', '贈白道者', '贈白道者', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["十二樓前再拜辭，靈風正滿碧桃枝。","壺中若是有天地，又向壺中傷別離。"]', '["十二楼前再拜辞，靈风正满碧桃枝。","壺中若是有天地，又向壺中傷別離。"]', '诗', 'shi', '', NULL, '贈白道者 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3410e7ce-df3a-4ab8-bea3-7f681661b240', '無題二首 一', '無題二首 一', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["昨夜星辰昨夜風，畫樓西畔桂堂東。","身無綵鳳雙飛翼，心有靈犀一點通。","隔座送鉤春酒暖，分曹射覆蠟燈紅。","嗟余聽鼓應官去，走馬蘭臺類斷蓬。"]', '["昨夜星辰昨夜风，畫楼西畔桂堂东。","身無綵鳳雙飞翼，心有靈犀一点通。","隔座送鉤春酒暖，分曹射覆蠟灯紅。","嗟余听鼓應官去，走马蘭台類斷蓬。"]', '诗', 'shi', '', NULL, '無題二首 一 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13345c36-ff7f-4c93-87e4-037d648d3c55', '無題二首 二', '無題二首 二', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["聞到閶門萼綠華，昔年相望抵天涯。","豈知一夜秦樓客，偷看吳王苑內花。"]', '["闻到閶门萼綠华，昔年相望抵天涯。","豈知一夜秦楼客，偷看吳王苑內花。"]', '诗', 'shi', '', NULL, '無題二首 二 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('738b365c-fd9a-4d86-acd7-8e5bd6ce92c6', '漢宮詞', '漢宮词', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["青雀西飛竟未迴，君王長在集靈臺。","侍臣最有相如渴，不賜金莖露一杯。"]', '["青雀西飞竟未迴，君王长在集靈台。","侍臣最有相如渴，不賜金莖露一杯。"]', '诗', 'shi', '', NULL, '漢宮詞 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7377e34a-1aab-47e3-a6dd-376c98a5d6b7', '無題四首 一', '無題四首 一', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["來是空言去絕踪，月斜樓上五更鐘。","夢爲遠別啼難喚，書被催成墨未濃。","蠟照半籠金翡翠，麝熏微度繡芙蓉。","劉郎已恨蓬山遠，更隔蓬山一萬重。"]', '["来是空言去絕踪，月斜楼上五更鐘。","梦爲远別啼难喚，书被催成墨未濃。","蠟照半籠金翡翠，麝熏微度繡芙蓉。","劉郎已恨蓬山远，更隔蓬山一万重。"]', '诗', 'shi', '', NULL, '無題四首 一 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('811a5f9e-0df5-46f1-a587-0d4df7bca5a0', '無題四首 二', '無題四首 二', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["颯颯東風細雨來，芙蓉塘外有輕雷。","金蟾齧鏁燒香入，玉虎牽絲汲井迴。","賈氏窺簾韓掾少，宓妃留枕魏王才。","春心莫共花爭發，一寸相思一寸灰。"]', '["颯颯东风細雨来，芙蓉塘外有轻雷。","金蟾齧鏁燒香入，玉虎牽絲汲井迴。","賈氏窺簾韓掾少，宓妃留枕魏王才。","春心莫共花爭發，一寸相思一寸灰。"]', '诗', 'shi', '', NULL, '無題四首 二 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8338c17-7f29-4d64-9c17-2e5eb4c4fa9d', '無題四首 三', '無題四首 三', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["含情春晼晚，暫見夜闌干。","樓響將登怯，簾烘欲過難。","多羞釵上燕，真媿鏡中鸞。","歸去橫塘曉，華星送寶鞍。"]', '["含情春晼晚，暫见夜闌干。","楼响將登怯，簾烘欲過难。","多羞釵上燕，真媿镜中鸾。","归去橫塘晓，华星送寶鞍。"]', '诗', 'shi', '', NULL, '無題四首 三 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b47c2562-516b-44b9-a754-a332867d99af', '無題四首 四', '無題四首 四', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["何處哀箏隨急管，櫻花永巷垂楊岸。","東家老女嫁不售，白日當天三月半。","溧陽公主年十四，清明暖後同墻看。","歸來展轉到五更，梁間燕子聞長歎。"]', '["何处哀箏隨急管，櫻花永巷垂楊岸。","东家老女嫁不售，白日當天三月半。","溧陽公主年十四，清明暖後同墻看。","归来展轉到五更，梁间燕子闻长歎。"]', '诗', 'shi', '', NULL, '無題四首 四 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29db6b06-b7c0-46fa-8c3c-68a2ebec9f50', '赴職梓潼留別畏之員外同年', '赴職梓潼留別畏之員外同年', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["佳兆聯翩遇鳳凰，雕文羽帳紫金牀。","桂花香處同高第，柿葉翻時獨悼亡。","烏鵲失棲長不定，鴛鴦何事自相將。","京華庸蜀三千里，送到咸陽見夕陽。"]', '["佳兆聯翩遇鳳凰，雕文羽帳紫金牀。","桂花香处同高第，柿葉翻时独悼亡。","烏鵲失棲长不定，鴛鴦何事自相將。","京华庸蜀三千里，送到咸陽见夕陽。"]', '诗', 'shi', '', NULL, '赴職梓潼留別畏之員外同年 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ef6c707-a77b-4e22-8257-7b5ab458d3e1', '桂林路中作', '桂林路中作', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["地暖無秋色，江晴有暮暉。","空餘蟬嘒嘒，猶向客依依。","村小犬相護，沙平僧獨歸。","欲成西北望，又見鷓鴣飛。"]', '["地暖無秋色，江晴有暮暉。","空餘蟬嘒嘒，猶向客依依。","村小犬相護，沙平僧独归。","欲成西北望，又见鷓鴣飞。"]', '诗', 'shi', '', NULL, '桂林路中作 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59c8f6e0-c96b-4d3d-82e7-c57919c0930d', '無題', '無題', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["照梁初有情，出水舊知名。","帬衩芙蓉小，釵茸翡翠輕。","錦長書鄭重，眉細恨分明。","莫近彈碁局，中心最不平。"]', '["照梁初有情，出水旧知名。","帬衩芙蓉小，釵茸翡翠轻。","錦长书鄭重，眉細恨分明。","莫近彈碁局，中心最不平。"]', '诗', 'shi', '', NULL, '無題 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('611f55f2-54f8-4b74-b65b-3703ace42ed6', '蝶三首 一', '蝶三首 一', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["初來小苑中，稍與瑣闈通。","遠恐芳塵斷，輕憂豔雪融。","只知防皓露，不覺逆尖風。","迴首雙飛燕，乘時入綺櫳。"]', '["初来小苑中，稍與瑣闈通。","远恐芳塵斷，轻憂豔雪融。","只知防皓露，不覺逆尖风。","迴首雙飞燕，乘时入綺櫳。"]', '诗', 'shi', '', NULL, '蝶三首 一 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5fbee39-67c1-4b49-b193-5cb7e3f1d95e', '蝶三首 二', '蝶三首 二', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["長眉畫了繡簾開，碧玉行收白玉臺。","爲問翠釵釵上鳳，不知香頸爲誰迴。"]', '["长眉畫了繡簾开，碧玉行收白玉台。","爲问翠釵釵上鳳，不知香頸爲誰迴。"]', '诗', 'shi', '', NULL, '蝶三首 二 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('404f4b36-a6ca-4c67-b4b3-a4d2a349eb15', '蝶三首 三', '蝶三首 三', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["壽陽公主嫁時妝，八字宮眉捧額黃。","見我佯羞頻照影，不知身屬冶遊郎。"]', '["壽陽公主嫁时妝，八字宮眉捧額黄。","见我佯羞頻照影，不知身屬冶游郎。"]', '诗', 'shi', '', NULL, '蝶三首 三 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e936cb1-f405-4848-bfbd-8db8f74f898a', '無題二首 一', '無題二首 一', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["八歲偷照鏡，長眉已能畫。","十歲去踏青，芙蓉作帬衩。","十二學彈箏，銀甲不曾卸。","十四藏六親，懸知猶未嫁。","十五泣春風，背面鞦韆下。"]', '["八歲偷照镜，长眉已能畫。","十歲去踏青，芙蓉作帬衩。","十二学彈箏，銀甲不曾卸。","十四藏六親，懸知猶未嫁。","十五泣春风，背面鞦韆下。"]', '诗', 'shi', '', NULL, '無題二首 一 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6072a95b-6994-4c35-96e2-4577d586ba28', '無題二首 二', '無題二首 二', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["幽人不倦賞，秋暑貴招邀。","竹碧轉悵望，池清尤寂寥。","露花終裛濕，風蝶強嬌饒。","此地如攜手，兼君不自聊。"]', '["幽人不倦賞，秋暑貴招邀。","竹碧轉悵望，池清尤寂寥。","露花終裛濕，风蝶強嬌饒。","此地如携手，兼君不自聊。"]', '诗', 'shi', '', NULL, '無題二首 二 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('400ba099-a00e-45ee-96b5-f0ff089c098c', '王十二兄與畏之員外相訪見招小飲時予以悼亡日近不去因寄', '王十二兄與畏之員外相訪见招小饮时予以悼亡日近不去因寄', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["謝傅門庭舊末行，今朝歌管屬檀郎。","更無人處簾垂地，欲拂塵時簟竟牀。","嵇氏幼男猶可憫，左家嬌女豈能忘。","秋霖腹疾俱難遣，萬里西風夜正長。"]', '["謝傅门庭旧末行，今朝歌管屬檀郎。","更無人处簾垂地，欲拂塵时簟竟牀。","嵇氏幼男猶可憫，左家嬌女豈能忘。","秋霖腹疾俱难遣，万里西风夜正长。"]', '诗', 'shi', '', NULL, '王十二兄與畏之員外相訪見招小飲時予以悼亡日近不去因寄 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91f95b30-c42f-470a-9df8-dd6284fca474', '隋宮', '隋宮', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["乘興南遊不戒嚴，九重誰省諫書函。","春風舉國裁宮錦，半作障泥半作帆。"]', '["乘兴南游不戒嚴，九重誰省諫书函。","春风舉国裁宮錦，半作障泥半作帆。"]', '诗', 'shi', '', NULL, '隋宮 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da157c27-d317-4205-9cdc-a254445659fc', '落花', '落花', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["高閣客竟去，小園花亂飛。","參差連曲陌，迢遰送斜暉。","腸斷未忍掃，眼穿仍欲歸。","芳心向春盡，所得是沾衣。"]', '["高閣客竟去，小园花亂飞。","參差連曲陌，迢遰送斜暉。","腸斷未忍掃，眼穿仍欲归。","芳心向春尽，所得是沾衣。"]', '诗', 'shi', '', NULL, '落花 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18ed9e1d-38bc-4f8e-86d1-a2fa4c0d10e0', '月', '月', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["池上與橋邊，難忘復可憐。","簾開最明夜，簟卷已涼天。","流處水花急，吐時雲葉鮮。","姮娥無粉黛，只是逞嬋娟。"]', '["池上與橋邊，难忘复可怜。","簾开最明夜，簟卷已涼天。","流处水花急，吐时云葉鲜。","姮娥無粉黛，只是逞嬋娟。"]', '诗', 'shi', '', NULL, '月 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55e6a23b-20c1-4e46-aba5-c3ef7526c3c9', '贈宗魯笻竹杖', '贈宗魯笻竹杖', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["大夏資輕策，全溪贈所思。","靜憐穿樹遠，滑想過苔遲。","鶴怨朝還望，僧閑暮有期。","風流真底事，常欲傍清羸。"]', '["大夏資轻策，全溪贈所思。","静怜穿樹远，滑想過苔遲。","鹤怨朝還望，僧闲暮有期。","风流真底事，常欲傍清羸。"]', '诗', 'shi', '', NULL, '贈宗魯笻竹杖 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bf8bd2e-3d1e-4c96-bc33-568180867267', '垂柳', '垂柳', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["娉婷小苑中，婀娜曲池東。","朝佩皆垂地，仙衣盡帶風。","七賢寧占竹，三品且饒松。","腸斷靈和殿，先皇玉座空。"]', '["娉婷小苑中，婀娜曲池东。","朝佩皆垂地，仙衣尽带风。","七賢寧占竹，三品且饒松。","腸斷靈和殿，先皇玉座空。"]', '诗', 'shi', '', NULL, '垂柳 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97352008-84fa-451b-988c-d2b84a372506', '曲池', '曲池', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["日下繁香不自持，月中流豔與誰期。","迎憂急鼓疎鐘斷，分隔休燈滅燭時。","張蓋欲判江灩灩，迴頭更望柳絲絲。","從來此地黃昏散，未信河梁是別離。"]', '["日下繁香不自持，月中流豔與誰期。","迎憂急鼓疎鐘斷，分隔休灯滅燭时。","張蓋欲判江灩灩，迴头更望柳絲絲。","從来此地黄昏散，未信河梁是別離。"]', '诗', 'shi', '', NULL, '曲池 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f07565e0-7e86-444a-b796-8e4070b9d6c0', '代應二首 一', '代應二首 一', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["溝水分流西復東，九秋霜月五更風。","離鸞別鳳今何在，十二玉樓空更空。"]', '["溝水分流西复东，九秋霜月五更风。","離鸾別鳳今何在，十二玉楼空更空。"]', '诗', 'shi', '', NULL, '代應二首 一 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe66a669-912c-4ed8-97a0-fc63a0319093', '代應二首 二', '代應二首 二', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["昨夜雙鉤敗，今朝百草輸。","關西狂小吏，惟喝遶牀盧。"]', '["昨夜雙鉤敗，今朝百草輸。","关西狂小吏，惟喝遶牀盧。"]', '诗', 'shi', '', NULL, '代應二首 二 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86ea8175-fabb-425d-85fd-6987c2dae0fd', '席上作', '席上作', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["淡雲輕雨拂高唐，玉殿秋來夜正長。","料得也應憐宋玉，一生惟事楚襄王。"]', '["淡云轻雨拂高唐，玉殿秋来夜正长。","料得也應怜宋玉，一生惟事楚襄王。"]', '诗', 'shi', '', NULL, '席上作 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cdd870a-88c1-48d6-859e-fec3185ae0df', '訪隱者不遇成二絕 一', '訪隐者不遇成二絕 一', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["秋水悠悠浸墅扉，夢中來數覺來稀。","玄蟬去盡葉黃落，一樹冬青人未歸。"]', '["秋水悠悠浸墅扉，梦中来數覺来稀。","玄蟬去尽葉黄落，一樹冬青人未归。"]', '诗', 'shi', '', NULL, '訪隱者不遇成二絕 一 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d3b643d-0b60-427c-91f3-6068cbf682f2', '訪隱者不遇成二絕 二', '訪隐者不遇成二絕 二', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["城郭休過識者稀，哀猿啼處有柴扉。","滄江白日樵漁路，日暮歸來雨滿衣。"]', '["城郭休過識者稀，哀猿啼处有柴扉。","滄江白日樵漁路，日暮归来雨满衣。"]', '诗', 'shi', '', NULL, '訪隱者不遇成二絕 二 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3350502f-b765-424c-8c79-dd0050d04233', '破鏡', '破镜', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["玉匣清光不復持，菱花散亂月輪虧。","秦臺一照山雞後，便是孤鸞罷舞時。"]', '["玉匣清光不复持，菱花散亂月輪虧。","秦台一照山雞後，便是孤鸾罷舞时。"]', '诗', 'shi', '', NULL, '破鏡 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('461e8253-fbe1-46e1-a40f-1b107a6db31f', '無題', '無題', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["紫府仙人號寶燈，雲漿未飲結成冰。","如何雪月交光夜，更在瑤臺十二層。"]', '["紫府仙人號寶灯，云漿未饮結成冰。","如何雪月交光夜，更在瑤台十二層。"]', '诗', 'shi', '', NULL, '無題 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b16a2371-bbd0-4322-828e-da45e2632bd5', '贈庾十二朱版', '贈庾十二朱版', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["固漆投膠不可開，贈君珍重抵瓊瑰。","君王曉坐金鑾殿，只待相如草詔來。"]', '["固漆投膠不可开，贈君珍重抵瓊瑰。","君王晓坐金鑾殿，只待相如草詔来。"]', '诗', 'shi', '', NULL, '贈庾十二朱版 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2346dbc-f057-4e05-87b3-6b725a70ded8', '李花', '李花', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["李徑獨來數，愁情相與懸。","自明無月夜，強笑欲風天。","減粉與園籜，分香沾渚蓮。","徐妃久已嫁，猶自玉爲鈿。"]', '["李徑独来數，愁情相與懸。","自明無月夜，強笑欲风天。","減粉與园籜，分香沾渚蓮。","徐妃久已嫁，猶自玉爲鈿。"]', '诗', 'shi', '', NULL, '李花 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15ed6ad5-cc7e-43a1-a843-42b442ff9ed3', '柳', '柳', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["曾逐東風拂舞筵，樂遊春苑斷腸天。","如何肯到清秋日，已帶斜陽又帶蟬。"]', '["曾逐东风拂舞筵，乐游春苑斷腸天。","如何肯到清秋日，已带斜陽又带蟬。"]', '诗', 'shi', '', NULL, '柳 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c899576-0b49-42c3-8fe2-b3af2c1a7aac', '三月十日流杯亭', '三月十日流杯亭', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["身屬中軍少得歸，木蘭花盡失春期。","偷隨柳絮到城外，行過水西聞子規。"]', '["身屬中軍少得归，木蘭花尽失春期。","偷隨柳絮到城外，行過水西闻子規。"]', '诗', 'shi', '', NULL, '三月十日流杯亭 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bfdfaf3-7ec6-459b-9c62-d04f3b755ba2', '過招國李家南園二首 一', '過招国李家南园二首 一', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["潘岳無妻客爲愁，新人來坐舊妝樓。","春風猶自疑聯句，雪絮相和飛不休。"]', '["潘岳無妻客爲愁，新人来坐旧妝楼。","春风猶自疑聯句，雪絮相和飞不休。"]', '诗', 'shi', '', NULL, '過招國李家南園二首 一 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bc0c393-aa7d-4ab6-b8f0-a189be3fb151', '過招國李家南園二首 二', '過招国李家南园二首 二', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["長亭歲盡雪如波，此去秦關路幾多。","惟有夢中相近分，臥來無睡欲如何。"]', '["长亭歲尽雪如波，此去秦关路幾多。","惟有梦中相近分，臥来無睡欲如何。"]', '诗', 'shi', '', NULL, '過招國李家南園二首 二 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cff5da44-589d-4c35-bf38-674d74dc4d1f', '留贈畏之 一', '留贈畏之 一', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["清時無事奏明光，不遣當關報早霜。","中禁詞臣尋引領，左川歸客自迴腸。","郎君下筆驚鸚鵡，侍女吹笙弄鳳凰。","空寄大羅天上事，衆仙同日詠霓裳。"]', '["清时無事奏明光，不遣當关報早霜。","中禁词臣尋引領，左川归客自迴腸。","郎君下笔驚鸚鵡，侍女吹笙弄鳳凰。","空寄大羅天上事，衆仙同日詠霓裳。"]', '诗', 'shi', '', NULL, '留贈畏之 一 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26d9723f-501f-407f-98a9-2486bc9e160e', '留贈畏之 二', '留贈畏之 二', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["待得郎來月已低，寒暄不道醉如泥。","五更又欲向何處，騎馬出門烏夜啼。"]', '["待得郎来月已低，寒暄不道醉如泥。","五更又欲向何处，騎马出门烏夜啼。"]', '诗', 'shi', '', NULL, '留贈畏之 二 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63fd26bc-6b80-4094-bd9d-27a4ec35bef3', '留贈畏之 三', '留贈畏之 三', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["戶外重陰黯不開，含羞迎夜復臨臺。","瀟湘浪上有煙景，安得好風吹汝來。"]', '["戶外重陰黯不开，含羞迎夜复臨台。","瀟湘浪上有煙景，安得好风吹汝来。"]', '诗', 'shi', '', NULL, '留贈畏之 三 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('974914ee-1fc0-4952-a863-820bad2e4065', '爲有', '爲有', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["爲有雲屏無限嬌，鳳城寒盡怕春宵。","無端嫁得金龜壻，辜負香衾事早朝。"]', '["爲有云屏無限嬌，鳳城寒尽怕春宵。","無端嫁得金龟壻，辜負香衾事早朝。"]', '诗', 'shi', '', NULL, '爲有 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed79f9bc-d5d1-4251-b22d-d091e0758a3f', '無題', '無題', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["相見時難別亦難，東風無力百花殘。","春蠶到死絲方盡，蠟炬成灰淚始乾。","曉鏡但愁雲鬢改，夜吟應覺月光寒。","蓬山此去無多路，青鳥殷勤爲探看。"]', '["相见时难別亦难，东风無力百花殘。","春蠶到死絲方尽，蠟炬成灰泪始乾。","晓镜但愁云鬢改，夜吟應覺月光寒。","蓬山此去無多路，青鸟殷勤爲探看。"]', '诗', 'shi', '', NULL, '無題 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7d541d4-757c-4759-9c36-64649e5e7c20', '碧城三首 一', '碧城三首 一', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["碧城十二曲闌干，犀辟塵埃玉辟寒。","閬苑有書多附鶴，女牀無樹不棲鸞。","星沉海底當窗見，雨過河源隔座看。","若是曉珠明又定，一生長樹水晶盤。"]', '["碧城十二曲闌干，犀辟塵埃玉辟寒。","閬苑有书多附鹤，女牀無樹不棲鸾。","星沉海底當窗见，雨過河源隔座看。","若是晓珠明又定，一生长樹水晶盤。"]', '诗', 'shi', '', NULL, '碧城三首 一 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe4d5a74-8e5f-421c-84df-e7f3cd53c8a2', '碧城三首 二', '碧城三首 二', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["對影聞聲已可憐，玉池荷葉正田田。","不逢蕭史休回首，莫見洪崖又拍肩。","紫鳳放嬌銜楚佩，赤鱗狂舞撥湘絃。","鄂君悵望舟中夜，繡被焚香獨自眠。"]', '["对影闻声已可怜，玉池荷葉正田田。","不逢蕭史休回首，莫见洪崖又拍肩。","紫鳳放嬌銜楚佩，赤鱗狂舞撥湘絃。","鄂君悵望舟中夜，繡被焚香独自眠。"]', '诗', 'shi', '', NULL, '碧城三首 二 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c1782ad-fa9d-458c-94ef-a8f3ad8b38ff', '碧城三首 三', '碧城三首 三', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["七夕來時先有期，洞房簾箔至今垂。","玉輪顧兔初生魄，鐵網珊瑚未有枝。","檢與神方教駐景，收將鳳紙寫相思。","武皇內傳分明在，莫道人間總不知。"]', '["七夕来时先有期，洞房簾箔至今垂。","玉輪顧兔初生魄，鐵網珊瑚未有枝。","檢與神方教駐景，收將鳳紙寫相思。","武皇內傳分明在，莫道人间總不知。"]', '诗', 'shi', '', NULL, '碧城三首 三 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4a7c497-cd2a-4d23-a086-4343f9821125', '對雪二首 一', '对雪二首 一', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["寒氣先侵玉女扉，清光旋透省郎闈。","梅花大庾嶺頭發，柳絮章臺街裏飛。","欲舞定隨曹植馬，有情應濕謝莊衣。","龍山萬里無多遠，留待行人二月歸。"]', '["寒氣先侵玉女扉，清光旋透省郎闈。","梅花大庾嶺头發，柳絮章台街裏飞。","欲舞定隨曹植马，有情應濕謝莊衣。","龙山万里無多远，留待行人二月归。"]', '诗', 'shi', '', NULL, '對雪二首 一 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25b4f480-f96d-4a3e-b343-8d327d413d3d', '對雪二首 二', '对雪二首 二', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["旋撲珠簾過粉墻，輕於柳絮重於霜。","已隨江令誇瓊樹，又入盧家妬玉堂。","侵夜可能爭桂魄，忍寒應欲試梅妝。","關河凍合東西路，腸斷斑騅送陸郎。"]', '["旋撲珠簾過粉墻，轻於柳絮重於霜。","已隨江令誇瓊樹，又入盧家妬玉堂。","侵夜可能爭桂魄，忍寒應欲試梅妝。","关河凍合东西路，腸斷斑騅送陸郎。"]', '诗', 'shi', '', NULL, '對雪二首 二 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aeaf48a2-a37f-4ae2-8fe0-da74da693b95', '蜂', '蜂', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["小苑華池爛熳通，後門前檻思無窮。","宓妃腰細纔勝露，趙后身輕欲倚風。","紅壁寂寥崖蜜盡，碧簾迢遰霧巢空。","青陵粉碟休離恨，長定相逢二月中。"]', '["小苑华池爛熳通，後门前檻思無窮。","宓妃腰細纔勝露，趙后身轻欲倚风。","紅壁寂寥崖蜜尽，碧簾迢遰霧巢空。","青陵粉碟休離恨，长定相逢二月中。"]', '诗', 'shi', '', NULL, '蜂 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28028f84-29d9-4a60-ba22-81bc988b9f22', '公子', '公子', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["外戚封侯自有恩，平明通籍九華門。","金唐公主年應小，二十君王未許婚。"]', '["外戚封侯自有恩，平明通籍九华门。","金唐公主年應小，二十君王未許婚。"]', '诗', 'shi', '', NULL, '公子 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6be98d11-1f5f-46ea-971e-61d4de82b8b9', '賦得雞', '賦得雞', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["稻粱猶足活諸雛，妬敵專場好自娛。","可要五更驚曉夢，不辭風雪爲陽烏。"]', '["稻粱猶足活諸雛，妬敵專場好自娛。","可要五更驚晓梦，不辞风雪爲陽烏。"]', '诗', 'shi', '', NULL, '賦得雞 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77ad6636-67fe-4c9c-a0ba-bbed4c3f147f', '明神', '明神', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["明神司過豈令冤，暗室由來有禍門。","莫爲無人欺一物，他時須慮石能言。"]', '["明神司過豈令冤，暗室由来有禍门。","莫爲無人欺一物，他时須慮石能言。"]', '诗', 'shi', '', NULL, '明神 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc1ce54a-dd77-4db2-98f2-9c606c71c408', '辛未七夕', '辛未七夕', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["恐是仙家好別離，故教迢遰作佳期。","由來碧落銀河畔，可要金風玉露時。","清漏漸移相望久，微雲未接過來遲。","豈能無意酬烏鵲，惟與蜘蛛乞巧絲。"]', '["恐是仙家好別離，故教迢遰作佳期。","由来碧落銀河畔，可要金风玉露时。","清漏漸移相望久，微云未接過来遲。","豈能無意酬烏鵲，惟與蜘蛛乞巧絲。"]', '诗', 'shi', '', NULL, '辛未七夕 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c70eb9a-a78c-4acf-9077-e5ab2a231459', '壬申七夕', '壬申七夕', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["已駕七香車，心心待曉霞。","風輕惟響珮，日薄不嫣花。","桂嫩傳香遠，榆高送影斜。","成都過卜肆，曾妬識靈槎。"]', '["已駕七香车，心心待晓霞。","风轻惟响珮，日薄不嫣花。","桂嫩傳香远，榆高送影斜。","成都過卜肆，曾妬識靈槎。"]', '诗', 'shi', '', NULL, '壬申七夕 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73f08183-ce53-4eba-823f-4813f07ddfba', '壬申閏秋題贈鳥鵲', '壬申閏秋題贈鸟鵲', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["繞樹無衣月正高，鄴城新淚濺雲袍。","幾年始得逢秋閏，兩度填河莫告勞。"]', '["繞樹無衣月正高，鄴城新泪濺云袍。","幾年始得逢秋閏，兩度填河莫告勞。"]', '诗', 'shi', '', NULL, '壬申閏秋題贈鳥鵲 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27bae607-f1b8-44c7-bc78-d73454e6c3a4', '端居', '端居', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["遠書歸夢兩悠悠，只有空牀敵素秋。","堦下青苔與紅樹，雨中寥落月中愁。"]', '["远书归梦兩悠悠，只有空牀敵素秋。","堦下青苔與紅樹，雨中寥落月中愁。"]', '诗', 'shi', '', NULL, '端居 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('386e25f8-f6b7-4054-aed1-eb82c64c5126', '夜半', '夜半', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["三更三點萬家眠，露欲爲霜月墮煙。","鬬鼠上堂蝙蝠出，玉琴時動倚窗絃。"]', '["三更三点万家眠，露欲爲霜月墮煙。","鬬鼠上堂蝙蝠出，玉琴时动倚窗絃。"]', '诗', 'shi', '', NULL, '夜半 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60de2318-4bff-455c-84d4-7ea4d1ef1af0', '玉山', '玉山', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["玉山高與閬風齊，玉水清流不貯泥。","何處更求回日馭，此中兼有上天梯。","珠容百斛龍休睡，桐拂千尋鳳要棲。","聞道神仙有才子，赤簫吹罷好相攜。"]', '["玉山高與閬风齊，玉水清流不貯泥。","何处更求回日馭，此中兼有上天梯。","珠容百斛龙休睡，桐拂千尋鳳要棲。","闻道神仙有才子，赤簫吹罷好相携。"]', '诗', 'shi', '', NULL, '玉山 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('232ba85c-9279-47c0-9c86-6a4e10e0ebed', '張惡子廟', '張惡子廟', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["下馬捧椒漿，迎神白玉堂。","如何鐵如意，獨自與姚萇。"]', '["下马捧椒漿，迎神白玉堂。","如何鐵如意，独自與姚萇。"]', '诗', 'shi', '', NULL, '張惡子廟 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b44a7fc3-3890-4221-aed2-2fc9343c5285', '雨', '雨', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["摵摵度瓜園，依依傍竹軒。","秋池不自冷，風葉共成喧。","窗迥有時見，簷高相續翻。","侵宵送書雁，應爲稻粱恩。"]', '["摵摵度瓜园，依依傍竹軒。","秋池不自冷，风葉共成喧。","窗迥有时见，簷高相續翻。","侵宵送书雁，應爲稻粱恩。"]', '诗', 'shi', '', NULL, '雨 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b0ce34d-ac0b-46f7-9e30-c7433a73d83a', '菊', '菊', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["暗暗淡淡紫，融融冶冶黃。","陶令籬邊色，羅含宅裏香。","幾時禁重露，實是怯殘陽。","願泛金鸚鵡，升君白玉堂。"]', '["暗暗淡淡紫，融融冶冶黄。","陶令籬邊色，羅含宅裏香。","幾时禁重露，實是怯殘陽。","願泛金鸚鵡，升君白玉堂。"]', '诗', 'shi', '', NULL, '菊 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0de5c9dc-8bd5-45db-bfbe-efba1c3e0db7', '牡丹', '牡丹', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["錦幃初卷衛夫人，繡被猶堆越鄂君。","垂手亂翻雕玉佩，招腰爭舞鬱金帬。","石家蠟燭何曾剪，荀令香爐可待熏。","我是夢中傳彩筆，欲書花葉寄朝雲。"]', '["錦幃初卷衛夫人，繡被猶堆越鄂君。","垂手亂翻雕玉佩，招腰爭舞鬱金帬。","石家蠟燭何曾剪，荀令香爐可待熏。","我是梦中傳彩笔，欲书花葉寄朝云。"]', '诗', 'shi', '', NULL, '牡丹 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('948ef71c-c0b8-4388-bdd8-3c983068f1a4', '北樓', '北楼', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["春物豈相干，人生只強歡。","花猶曾斂夕，酒竟不知寒。","異城東風濕，中華上象寬。","此樓堪北望，輕命倚危欄。"]', '["春物豈相干，人生只強歡。","花猶曾斂夕，酒竟不知寒。","異城东风濕，中华上象寬。","此楼堪北望，轻命倚危欄。"]', '诗', 'shi', '', NULL, '北樓 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffb33b2d-d22c-41df-8a4b-c8ff7ffc9a80', '擬沈下賢', '擬沈下賢', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["千二百輕鸞，春衫瘦著寬。","倚風行稍急，含雪語應寒。","帶火遺金斗，兼珠碎玉盤。","河陽看花過，曾不問潘安。"]', '["千二百轻鸾，春衫瘦著寬。","倚风行稍急，含雪語應寒。","带火遺金斗，兼珠碎玉盤。","河陽看花過，曾不问潘安。"]', '诗', 'shi', '', NULL, '擬沈下賢 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcc367cf-fd08-48b7-b0cd-88b01ee5f1a0', '蝶', '蝶', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["飛來繡戶陰，穿過畫樓深。","重傅秦臺粉，輕塗漢殿金。","相兼惟柳絮，所得是花心。","可要凌孤客，邀爲子夜吟。"]', '["飞来繡戶陰，穿過畫楼深。","重傅秦台粉，轻塗漢殿金。","相兼惟柳絮，所得是花心。","可要凌孤客，邀爲子夜吟。"]', '诗', 'shi', '', NULL, '蝶 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92d31d11-8416-4a65-a109-6378a1493b82', '飲席代官妓贈兩從事', '饮席代官妓贈兩從事', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["新人橋上著春衫，舊主江邊側帽簷。","願得化爲紅綬帶，許教雙鳳一時銜。"]', '["新人橋上著春衫，旧主江邊側帽簷。","願得化爲紅綬带，許教雙鳳一时銜。"]', '诗', 'shi', '', NULL, '飲席代官妓贈兩從事 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c87356ef-797e-4aac-9e68-821a85a083e3', '代魏宮私贈', '代魏宮私贈', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["來時西館阻佳期，去後漳河隔夢思。","知有宓妃無限意，春松秋菊可同時。"]', '["来时西館阻佳期，去後漳河隔梦思。","知有宓妃無限意，春松秋菊可同时。"]', '诗', 'shi', '', NULL, '代魏宮私贈 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b534565-9537-4df2-80ad-760cf04a103f', '代元城吳令暗爲荅', '代元城吳令暗爲荅', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["背闕歸藩路欲分，水邊風日半西曛。","荆王枕上原無夢，莫枉陽臺一片雲。"]', '["背闕归藩路欲分，水邊风日半西曛。","荆王枕上原無梦，莫枉陽台一片云。"]', '诗', 'shi', '', NULL, '代元城吳令暗爲荅 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7559e729-f9be-41c3-bf80-0ed4ecb17029', '牡丹', '牡丹', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["壓逕復緣溝，當窗又映樓。","終銷一國破，不啻萬金求。","鸞鳳戲三島，神仙居十洲。","應憐萱草淡，却得號忘憂。"]', '["壓逕复緣溝，當窗又映楼。","終銷一国破，不啻万金求。","鸾鳳戲三島，神仙居十洲。","應怜萱草淡，却得號忘憂。"]', '诗', 'shi', '', NULL, '牡丹 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1779cc74-d2b3-4a4c-8710-2b662ccfb5d6', '百果嘲櫻桃', '百果嘲櫻桃', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["珠實雖先熟，瓊莩縱早開。","流鸎猶故在，爭得諱含來。"]', '["珠實雖先熟，瓊莩縱早开。","流鸎猶故在，爭得諱含来。"]', '诗', 'shi', '', NULL, '百果嘲櫻桃 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b82bef3-d729-4452-890c-8be9d694c621', '櫻桃答', '櫻桃答', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["衆果莫相誚，天生名品高。","何因古樂府，惟有鄭櫻桃。"]', '["衆果莫相誚，天生名品高。","何因古乐府，惟有鄭櫻桃。"]', '诗', 'shi', '', NULL, '櫻桃答 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b309451-8607-4b72-a535-613629f02a24', '曉坐', '晓坐', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["後閤罷朝眠，前墀思黯然。","梅應未假雪，柳自不勝煙。","淚續淺深綆，腸危高下絃。","紅顏無定所，得失在當年。"]', '["後閤罷朝眠，前墀思黯然。","梅應未假雪，柳自不勝煙。","泪續淺深綆，腸危高下絃。","紅顏無定所，得失在當年。"]', '诗', 'shi', '', NULL, '曉坐 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2b3de24-67b2-4a7c-bb8b-f6d6b2e23772', '詠史', '詠史', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["北湖南埭水漫漫，一片降旗百尺竿。","三百年間同曉夢，鍾山何處有龍盤。"]', '["北湖南埭水漫漫，一片降旗百尺竿。","三百年间同晓梦，鍾山何处有龙盤。"]', '诗', 'shi', '', NULL, '詠史 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb757832-9421-4b38-9fa1-aa6430df8909', '一片', '一片', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["一片非煙隔九枝，蓬巒仙仗儼雲旗。","天泉水暖龍吟細，露畹春多鳳舞遲。","榆莢散來星斗轉，桂花尋去月輪移。","人間桑海朝朝變，莫遣佳期更後期。"]', '["一片非煙隔九枝，蓬巒仙仗儼云旗。","天泉水暖龙吟細，露畹春多鳳舞遲。","榆莢散来星斗轉，桂花尋去月輪移。","人间桑海朝朝变，莫遣佳期更後期。"]', '诗', 'shi', '', NULL, '一片 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7fd3021e-687c-4b6f-a99d-8dd78f1e32db', '日射', '日射', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["日射紗窗風撼扉，香羅拭手春事違。","迴廊四合掩寂寞，碧鸚鵡對紅薔薇。"]', '["日射紗窗风撼扉，香羅拭手春事違。","迴廊四合掩寂寞，碧鸚鵡对紅薔薇。"]', '诗', 'shi', '', NULL, '日射 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5be81cf2-65d6-440e-b7cb-8668b2988a4b', '題鵝', '題鵝', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["眠沙臥水自成羣，曲岸殘陽極浦雲。","那解將心憐孔翠，羈雌長共故雄分。"]', '["眠沙臥水自成羣，曲岸殘陽極浦云。","那解將心怜孔翠，羈雌长共故雄分。"]', '诗', 'shi', '', NULL, '題鵝 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a18daa1a-b079-4351-930b-1af9af91aab8', '華清宮', '华清宮', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["朝元閣迥羽衣新，首按昭陽第一人。","當日不來高處舞，可能天下有胡塵。"]', '["朝元閣迥羽衣新，首按昭陽第一人。","當日不来高处舞，可能天下有胡塵。"]', '诗', 'shi', '', NULL, '華清宮 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('470ddf3b-fee4-453b-b329-5b3d26032af3', '梓潼望長卿山至巴西復懷譙秀', '梓潼望长卿山至巴西复懷譙秀', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["梓潼不見馬相如，更欲南行問酒壚。","行到巴西覓譙秀，巴西惟是有寒蕪。"]', '["梓潼不见马相如，更欲南行问酒壚。","行到巴西覓譙秀，巴西惟是有寒蕪。"]', '诗', 'shi', '', NULL, '梓潼望長卿山至巴西復懷譙秀 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4d65f0b-8de2-4f25-baf9-4ea04c0e01e7', '齊宮詞', '齊宮词', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["永壽兵來夜不扃，金蓮無復印中庭。","梁臺歌管三更罷，猶自風搖九子鈴。"]', '["永壽兵来夜不扃，金蓮無复印中庭。","梁台歌管三更罷，猶自风搖九子鈴。"]', '诗', 'shi', '', NULL, '齊宮詞 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0595cc72-4707-4448-91c3-18935d916119', '十一月中旬至扶風界見梅花', '十一月中旬至扶风界见梅花', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["匝路亭亭豔，非時裛裛香。","素娥惟與月，青女不饒霜。","贈遠虛盈手，傷離適斷腸。","爲誰成早秀，不待作年芳。"]', '["匝路亭亭豔，非时裛裛香。","素娥惟與月，青女不饒霜。","贈远虛盈手，傷離適斷腸。","爲誰成早秀，不待作年芳。"]', '诗', 'shi', '', NULL, '十一月中旬至扶風界見梅花 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea6f4493-38e2-4f75-b674-1f894fa50bc4', '青陵臺', '青陵台', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["青陵臺畔日光斜，萬古貞魂倚暮霞。","莫訝韓憑爲蛺蝶，等閑飛上別枝花。"]', '["青陵台畔日光斜，万古貞魂倚暮霞。","莫訝韓憑爲蛺蝶，等闲飞上別枝花。"]', '诗', 'shi', '', NULL, '青陵臺 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c54c5f69-81c1-4dcf-8fab-3278f96f7467', '東還', '东還', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["自有仙才自不知，十年長夢採華芝。","秋風動地黃雲暮，歸去嵩陽尋舊師。"]', '["自有仙才自不知，十年长梦採华芝。","秋风动地黄云暮，归去嵩陽尋旧師。"]', '诗', 'shi', '', NULL, '東還 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95842e47-54e0-44dd-8b90-dbd1c2514ae3', '酬崔八早梅有贈兼示之作', '酬崔八早梅有贈兼示之作', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["知訪寒梅過野塘，久留金勒爲迴腸。","謝郎衣袖初翻雪，荀令熏爐更換香。","何處拂胸資蝶粉，幾時塗額藉蜂黃。","維摩一室雖多病，亦要天花作道場。"]', '["知訪寒梅過野塘，久留金勒爲迴腸。","謝郎衣袖初翻雪，荀令熏爐更換香。","何处拂胸資蝶粉，幾时塗額藉蜂黄。","維摩一室雖多病，亦要天花作道場。"]', '诗', 'shi', '', NULL, '酬崔八早梅有贈兼示之作 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8643adc-fc9c-4440-82b0-6512fe87fa06', '春風', '春风', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["春風雖自好，春物太昌昌。","若教春有意，惟遣一枝芳。","我意殊春意，先春已斷腸。"]', '["春风雖自好，春物太昌昌。","若教春有意，惟遣一枝芳。","我意殊春意，先春已斷腸。"]', '诗', 'shi', '', NULL, '春風 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0650447b-602d-4fd1-b0c0-967d7eb4c8b1', '蜀桐', '蜀桐', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["玉壘高桐拂玉繩，上含非霧下含冰。","枉教紫鳳無棲處，斵作秋琴彈壞陵。"]', '["玉壘高桐拂玉繩，上含非霧下含冰。","枉教紫鳳無棲处，斵作秋琴彈壞陵。"]', '诗', 'shi', '', NULL, '蜀桐 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d374f3b2-fae5-4555-98b3-557f3aebe0dd', '漢宮', '漢宮', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["通靈夜醮達清晨，承露盤晞甲帳春。","王母不來方朔去，更須重見李夫人。"]', '["通靈夜醮達清晨，承露盤晞甲帳春。","王母不来方朔去，更須重见李夫人。"]', '诗', 'shi', '', NULL, '漢宮 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c72c50c4-02c9-4291-802d-066c8879269c', '判春', '判春', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["一桃復一李，井上占年芳。","笑處如臨鏡，窺時不隱墻。","敢言西子短，誰覺宓妃長。","珠玉終相類，同名作夜光。"]', '["一桃复一李，井上占年芳。","笑处如臨镜，窺时不隐墻。","敢言西子短，誰覺宓妃长。","珠玉終相類，同名作夜光。"]', '诗', 'shi', '', NULL, '判春 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc96d1c5-e131-4a00-97d5-aeded8c681a5', '促漏', '促漏', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["促漏遙鐘動靜聞，報章重疊杳難分。","舞鸞鏡匣收殘黛，睡鴨香爐換夕熏。","歸去定知還向月，夢來何處更爲雲？","南塘漸暖蒲堪結，兩兩鴛鴦護水紋。"]', '["促漏遙鐘动静闻，報章重叠杳难分。","舞鸾镜匣收殘黛，睡鴨香爐換夕熏。","归去定知還向月，梦来何处更爲云？","南塘漸暖蒲堪結，兩兩鴛鴦護水紋。"]', '诗', 'shi', '', NULL, '促漏 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b01e157-57bd-44b7-924b-f1ef462cd9d9', '江東', '江东', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["驚魚撥刺燕翩翾，獨自江東上釣船。","今日春光太漂蕩，謝家輕絮沈郎錢。"]', '["驚鱼撥刺燕翩翾，独自江东上釣船。","今日春光太漂蕩，謝家轻絮沈郎錢。"]', '诗', 'shi', '', NULL, '江東 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e9d07db-3d09-4952-9ba2-fd457d7861df', '讀任彥昇碑', '读任彥昇碑', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["任昉當年有美名，可憐才調最縱橫。","梁臺初建應惆悵，不得蕭公作騎兵。"]', '["任昉當年有美名，可怜才調最縱橫。","梁台初建應惆悵，不得蕭公作騎兵。"]', '诗', 'shi', '', NULL, '讀任彥昇碑 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d040a94-a0dc-4759-b374-26278998fef9', '荷花', '荷花', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["都無色可並，不奈此香何。","瑤席乘涼設，金羈落晚過。","迴衾燈照綺，渡韈水沾羅。","預想前秋別，離居夢櫂歌。"]', '["都無色可並，不奈此香何。","瑤席乘涼設，金羈落晚過。","迴衾灯照綺，渡韈水沾羅。","預想前秋別，離居梦櫂歌。"]', '诗', 'shi', '', NULL, '荷花 李商隱 shi');
